const c=5,n="tin-hoc",h="Tin học lớp 5",i="internal",t=[{id:"may-tinh-va-em",title:"Máy tính và em",lessons:[{id:"th5-may-tinh-giup-gi",title:"Bài 1: Máy tính giúp em làm những gì?",weeks:[1,2],learn:[{title:"Máy tính giúp em học tập",text:"Máy tính giúp em tra cứu thông tin, làm bài luyện tập, làm bài trình chiếu và học trực tuyến.",example:"📚 tra cứu · ✏️ luyện tập · 🖥️ học trực tuyến"},{title:"Làm việc và giao tiếp",text:"Người lớn dùng máy tính để soạn văn bản, tính toán và quản lí công việc. Mọi người gửi thư điện tử, gọi video để trò chuyện dù ở xa nhau.",example:"📄 văn bản · 🧮 tính toán · 📧 thư · 📹 gọi video"},{title:"Giải trí và sáng tạo",text:"Em có thể nghe nhạc, xem phim, chơi trò chơi bổ ích, vẽ tranh, làm thiệp hay viết truyện bằng máy tính.",example:"🎵 nhạc · 🎬 phim · 🎨 vẽ · 💌 thiệp"},{title:"Máy tính cần con người",text:"Máy tính làm việc rất nhanh nhưng chỉ làm theo lệnh con người đưa vào. Con người phải suy nghĩ, chọn việc cần làm và kiểm tra lại kết quả.",example:"👩 ra lệnh → 💻 thực hiện → 👀 kiểm tra"}],practice:[{questions:[{id:"th5-may-tinh-giup-gi-01",type:"mc",q:"Việc nào sau đây là dùng máy tính để học tập?",explain:"Tra cứu thông tin cho bài học là dùng máy tính để học tập.",options:["Tra cứu thông tin cho bài học","Chơi trò xếp hình trên máy","Xem phim hoạt hình cuối tuần","Nghe một bản nhạc thật vui"],answer:0,emoji:"📚"},{id:"th5-may-tinh-giup-gi-02",type:"tf",q:"Máy tính có thể giúp người ở xa trò chuyện và nhìn thấy nhau qua gọi video.",explain:"Đúng. Gọi video giúp mọi người ở xa vẫn nhìn thấy và nói chuyện với nhau.",answer:!0,emoji:"📹"},{id:"th5-may-tinh-giup-gi-03",type:"tf",q:"Máy tính tự nghĩ ra việc cần làm mà không cần ai ra lệnh.",explain:"Sai. Máy tính chỉ làm theo lệnh do con người đưa vào.",answer:!1},{id:"th5-may-tinh-giup-gi-04",type:"match",q:"Ghép việc làm với lĩnh vực máy tính hỗ trợ.",explain:"Máy tính hỗ trợ con người trong học tập, giao tiếp, giải trí và sáng tạo.",pairs:[["Làm bài luyện tập trực tuyến","Học tập"],["Gửi thư điện tử cho bạn","Giao tiếp"],["Nghe nhạc thiếu nhi","Giải trí"],["Vẽ thiệp chúc mừng","Sáng tạo"]]},{id:"th5-may-tinh-giup-gi-05",type:"mc",q:"Phần mềm nào giúp em viết một bài văn trên máy tính?",explain:"Phần mềm soạn thảo dùng để gõ và sửa bài văn.",options:["Phần mềm vẽ","Phần mềm soạn thảo","Phần mềm nghe nhạc"],answer:1,emoji:"📝"},{id:"th5-may-tinh-giup-gi-06",type:"multi",q:"Những việc nào máy tính có thể giúp em làm?",explain:"Máy tính giúp tra cứu, vẽ tranh, gửi thư. Ăn cơm thì em phải tự làm.",options:["Tra cứu bài học","Vẽ tranh","Ăn cơm thay em","Gửi thư điện tử"],answers:[0,1,3]},{id:"th5-may-tinh-giup-gi-07",type:"tf",q:"Người lớn dùng máy tính để soạn văn bản và tính toán trong công việc.",explain:"Đúng. Máy tính giúp người lớn làm việc nhanh và gọn hơn.",answer:!0},{id:"th5-may-tinh-giup-gi-08",type:"mc",q:"Máy tính thực hiện công việc theo điều gì?",explain:"Máy tính làm theo lệnh mà con người đưa vào.",options:["Theo ý thích của máy","Theo thời tiết hôm đó","Theo lệnh của con người"],answer:2},{id:"th5-may-tinh-giup-gi-09",type:"fill",q:"Điền từ còn thiếu: Máy tính chỉ làm theo … do con người đưa vào.",explain:"Máy tính làm theo lệnh của con người.",answer:["lệnh","các lệnh","câu lệnh"]}]},{questions:[{id:"th5-may-tinh-giup-gi-10",type:"mc",q:"Vì sao nhiều người dùng thư điện tử thay cho thư giấy?",explain:"Thư điện tử gửi qua Internet nên đến nơi rất nhanh.",options:["Thư đến nơi rất nhanh","Thư phải dán tem","Thư chỉ gửi trong nhà"],answer:0,emoji:"📧"},{id:"th5-may-tinh-giup-gi-11",type:"tf",q:"Máy tính tính rất nhanh, nhưng nếu người dùng nhập sai số thì kết quả cũng sai.",explain:"Đúng. Máy làm đúng theo số được nhập, nhập sai thì kết quả sai.",answer:!0},{id:"th5-may-tinh-giup-gi-12",type:"mc",q:"Chi dùng máy tính vẽ tranh và làm thiệp tặng mẹ. Chi đang dùng máy tính để làm gì?",explain:"Vẽ tranh, làm thiệp là dùng máy tính để sáng tạo.",options:["Tính toán","Sáng tạo","Giao tiếp"],answer:1,emoji:"🎨"},{id:"th5-may-tinh-giup-gi-13",type:"multi",q:"Những việc nào là dùng máy tính để giao tiếp?",explain:"Gửi thư, gọi video, nhắn tin là trao đổi với người khác. Vẽ tranh một mình và nghe nhạc không phải giao tiếp.",options:["Gửi thư điện tử","Gọi video cho bà","Vẽ tranh một mình","Nhắn tin cho bạn cùng lớp","Nghe nhạc"],answers:[0,1,3]},{id:"th5-may-tinh-giup-gi-14",type:"tf",q:"Có máy tính rồi thì con người không cần học và suy nghĩ nữa.",explain:"Sai. Con người vẫn phải suy nghĩ, ra lệnh và kiểm tra kết quả.",answer:!1},{id:"th5-may-tinh-giup-gi-15",type:"match",q:"Ghép phần mềm với việc em làm.",explain:"Mỗi phần mềm giúp em làm một loại việc.",pairs:[["Phần mềm soạn thảo","Viết bài văn"],["Phần mềm trình chiếu","Làm bài thuyết trình"],["Trình duyệt","Xem trang web"],["Phần mềm vẽ","Vẽ bức tranh"]]},{id:"th5-may-tinh-giup-gi-16",type:"mc",q:"Điều nào cho thấy máy tính cần con người?",explain:"Máy tính chỉ làm việc khi con người ra lệnh.",options:["Máy chạy được khi không có điện","Máy tự biết bài em cần học","Người dùng phải ra lệnh cho máy"],answer:2},{id:"th5-may-tinh-giup-gi-17",type:"tf",q:"Xem phim hoạt hình trên máy tính là dùng máy tính để giao tiếp.",explain:"Sai. Xem phim hoạt hình là dùng máy tính để giải trí.",answer:!1,emoji:"🎬"},{id:"th5-may-tinh-giup-gi-18",type:"order",q:"Sắp xếp các bước làm một tấm thiệp trên máy tính.",explain:"Bật máy, mở phần mềm, vẽ xong rồi lưu lại.",items:["Bật máy tính","Mở phần mềm vẽ","Vẽ và tô màu tấm thiệp","Lưu tệp tấm thiệp"]}]},{questions:[{id:"th5-may-tinh-giup-gi-19",type:"mc",q:"Nam muốn biết ngày mai trời có mưa không. Nam nên dùng máy tính làm gì?",explain:"Bản tin thời tiết cho Nam biết ngày mai có mưa không.",options:["Xem bản tin thời tiết trên mạng","Gõ một bài văn về trời mưa","Mở phần mềm vẽ để vẽ mây"],answer:0,emoji:"🌧️"},{id:"th5-may-tinh-giup-gi-20",type:"mc",q:"Lớp em muốn giới thiệu về trường cho các bạn mới. Phần mềm nào phù hợp nhất?",explain:"Phần mềm trình chiếu giúp trình bày chữ và hình ảnh để giới thiệu.",options:["Phần mềm nghe nhạc","Phần mềm trình chiếu","Phần mềm luyện gõ phím"],answer:1},{id:"th5-may-tinh-giup-gi-21",type:"tf",q:"Bình nhờ máy tính tính tổng tiền mua sách cho lớp. Bình vẫn nên kiểm tra lại các số đã nhập.",explain:"Đúng. Nhập sai số thì máy cho kết quả sai, nên cần kiểm tra lại.",answer:!0},{id:"th5-may-tinh-giup-gi-22",type:"multi",q:"Bố của Vy làm việc ở nhà bằng máy tính. Bố có thể dùng máy tính để làm gì?",explain:"Máy tính giúp soạn báo cáo, gửi thư, họp trực tuyến. Nấu ăn thì cần làm bằng tay.",options:["Soạn báo cáo","Gửi thư cho đồng nghiệp","Nấu bữa tối","Họp trực tuyến"],answers:[0,1,3]},{id:"th5-may-tinh-giup-gi-23",type:"mc",q:"Hà chơi trò chơi trên máy tính suốt buổi chiều mà chưa làm bài. Hà dùng máy tính đã hợp lí chưa?",explain:"Máy tính dùng cho nhiều việc. Hà nên làm bài trước rồi mới giải trí.",options:["Hợp lí, vì máy chỉ để chơi","Hợp lí, vì trò chơi rất vui","Chưa, nên làm bài rồi mới chơi"],answer:2},{id:"th5-may-tinh-giup-gi-24",type:"tf",q:"Máy tính chỉ dùng được cho người lớn đi làm, không giúp gì cho học sinh.",explain:"Sai. Máy tính giúp học sinh tra cứu, luyện tập và sáng tạo.",answer:!1},{id:"th5-may-tinh-giup-gi-25",type:"mc",q:"Khoa viết truyện ngắn bằng phần mềm soạn thảo. Ai là người nghĩ ra câu chuyện?",explain:"Khoa nghĩ ra câu chuyện, máy tính chỉ giúp gõ và lưu lại.",options:["Khoa","Phần mềm soạn thảo","Bàn phím"],answer:0,emoji:"✍️"},{id:"th5-may-tinh-giup-gi-26",type:"match",q:"Ghép tình huống với cách máy tính giúp đỡ.",explain:"Mỗi nhu cầu có một cách dùng máy tính phù hợp.",pairs:[["Ông muốn gặp cháu ở xa","Gọi video"],["Lan muốn tìm hiểu về loài voi","Tra cứu trên mạng"],["Mẹ cần cộng tiền chi tiêu cả tháng","Tính toán nhanh"],["Minh muốn nghe một bài hát","Phát nhạc"]]},{id:"th5-may-tinh-giup-gi-27",type:"order",q:"Sắp xếp các bước khi máy tính giúp em làm một việc.",explain:"Con người ra lệnh, máy thực hiện và cho kết quả, rồi con người kiểm tra lại.",items:["Con người đưa lệnh vào máy","Máy tính thực hiện lệnh","Máy tính đưa ra kết quả","Con người kiểm tra kết quả"]}]}],challenge:{questions:[{id:"th5-may-tinh-giup-gi-28",type:"mc",q:"Phúc nhờ máy tính tính 25 nhân 4 nhưng gõ nhầm thành 25 nhân 5. Máy cho kết quả 125. Vì sao kết quả sai?",explain:"Máy tính đúng 25 nhân 5 bằng 125. Kết quả sai vì Phúc nhập nhầm số.",options:["Vì máy tính bị hỏng","Vì người dùng nhập sai","Vì máy tính tính chậm"],answer:1,emoji:"🧮"},{id:"th5-may-tinh-giup-gi-29",type:"multi",q:"Những câu nào nói đúng về máy tính?",explain:"Máy tính nhanh, làm theo lệnh và giúp giao tiếp. Máy không tự biết điều gì là đúng.",options:["Máy tính làm việc rất nhanh","Máy tính tự biết điều gì là đúng","Máy tính làm theo lệnh con người","Máy tính giúp người ở xa trò chuyện"],answers:[0,2,3]},{id:"th5-may-tinh-giup-gi-30",type:"tf",q:"Cùng một máy tính có thể dùng cho cả học tập, làm việc, giao tiếp và giải trí.",explain:"Đúng. Chỉ cần dùng phần mềm phù hợp với từng việc.",answer:!0},{id:"th5-may-tinh-giup-gi-16",type:"mc",q:"Điều nào cho thấy máy tính cần con người?",explain:"Máy tính chỉ làm việc khi con người ra lệnh.",options:["Máy chạy được khi không có điện","Máy tự biết bài em cần học","Người dùng phải ra lệnh cho máy"],answer:2},{id:"th5-may-tinh-giup-gi-21",type:"tf",q:"Bình nhờ máy tính tính tổng tiền mua sách cho lớp. Bình vẫn nên kiểm tra lại các số đã nhập.",explain:"Đúng. Nhập sai số thì máy cho kết quả sai, nên cần kiểm tra lại.",answer:!0},{id:"th5-may-tinh-giup-gi-25",type:"mc",q:"Khoa viết truyện ngắn bằng phần mềm soạn thảo. Ai là người nghĩ ra câu chuyện?",explain:"Khoa nghĩ ra câu chuyện, máy tính chỉ giúp gõ và lưu lại.",options:["Khoa","Phần mềm soạn thảo","Bàn phím"],answer:0,emoji:"✍️"},{id:"th5-may-tinh-giup-gi-27",type:"order",q:"Sắp xếp các bước khi máy tính giúp em làm một việc.",explain:"Con người ra lệnh, máy thực hiện và cho kết quả, rồi con người kiểm tra lại.",items:["Con người đưa lệnh vào máy","Máy tính thực hiện lệnh","Máy tính đưa ra kết quả","Con người kiểm tra kết quả"]}]},summary:["Máy tính giúp con người học tập, làm việc, giao tiếp, giải trí và sáng tạo.","Máy tính chỉ làm theo lệnh của con người, nên con người phải suy nghĩ và kiểm tra kết quả."]},{id:"th5-dung-may-tinh-hieu-qua",title:"Bài 2: Dùng máy tính hiệu quả và an toàn",weeks:[3,3],learn:[{title:"Dùng máy có giờ giấc",text:"Em nên dùng máy tính đúng mục đích và có giới hạn thời gian. Sau một lúc dùng máy, hãy nghỉ mắt, nhìn ra xa và vận động nhẹ.",example:"⏰ hẹn giờ · 👀 nhìn xa · 🤸 vận động"},{title:"Ngồi đúng tư thế",text:"Ngồi thẳng lưng, hai chân đặt trên sàn, không cúi sát màn hình. Phòng học cần đủ ánh sáng.",example:"🪑 thẳng lưng · 🦶 chân chạm sàn · 💡 đủ sáng"},{title:"Lưu bài thường xuyên",text:"Khi làm bài trên máy tính, em nên lưu thường xuyên để không mất bài khi mất điện hay máy bị treo. Đặt tên tệp rõ ràng để dễ tìm lại.",example:"💾 lưu · 🏷️ tên tệp rõ ràng"},{title:"Tắt máy và giữ gìn máy",text:"Lưu bài, đóng các phần mềm rồi chọn lệnh tắt máy, không rút điện khi máy đang chạy. Giữ tay khô, không để đồ ăn, nước uống gần máy.",example:"💾 → ❌ phần mềm → ⏻ tắt máy"}],practice:[{questions:[{id:"th5-dung-may-tinh-hieu-qua-01",type:"tf",q:"Rút phích điện là cách tắt máy tính đúng.",explain:"Sai. Em cần lưu bài, đóng phần mềm rồi chọn lệnh tắt máy.",answer:!1,emoji:"🔌"},{id:"th5-dung-may-tinh-hieu-qua-02",type:"mc",q:"Trước khi tắt máy tính, em cần làm gì với bài đang làm?",explain:"Lưu bài trước khi tắt máy để không bị mất bài.",options:["Phóng to bài","Xoá bài đi","Lưu bài lại"],answer:2,emoji:"💾"},{id:"th5-dung-may-tinh-hieu-qua-03",type:"tf",q:"Không nên để cốc nước gần bàn phím máy tính.",explain:"Đúng. Nước đổ vào có thể làm hỏng máy.",answer:!0,emoji:"🥤"},{id:"th5-dung-may-tinh-hieu-qua-04",type:"mc",q:"Khi dùng máy tính một lúc lâu, em nên làm gì để mắt đỡ mỏi?",explain:"Nghỉ và nhìn ra xa giúp mắt được thư giãn.",options:["Nghỉ và nhìn ra xa","Nhìn sát màn hình hơn","Tắt hết đèn trong phòng"],answer:0,emoji:"👀"},{id:"th5-dung-may-tinh-hieu-qua-05",type:"multi",q:"Những việc nào giúp bảo vệ máy tính?",explain:"Tay khô, gõ nhẹ, tắt máy đúng cách giúp máy bền. Đồ ăn rơi vào bàn phím làm hỏng phím.",options:["Giữ tay khô khi dùng máy","Để đồ ăn trên bàn phím","Gõ phím nhẹ nhàng","Tắt máy đúng cách"],answers:[0,2,3]},{id:"th5-dung-may-tinh-hieu-qua-06",type:"tf",q:"Ngồi thẳng lưng, hai chân đặt trên sàn là tư thế đúng khi dùng máy tính.",explain:"Đúng. Ngồi như vậy giúp lưng không bị đau.",answer:!0,emoji:"🪑"},{id:"th5-dung-may-tinh-hieu-qua-07",type:"mc",q:"Vì sao nên lưu bài thường xuyên khi làm trên máy tính?",explain:"Bài đã lưu vẫn còn khi máy mất điện hay bị treo.",options:["Để máy tính chạy nhanh hơn","Để không mất bài khi mất điện","Để màn hình sáng rõ hơn"],answer:1},{id:"th5-dung-may-tinh-hieu-qua-08",type:"fill",q:"Điền từ còn thiếu: Khi làm bài trên máy tính, em nên … bài thường xuyên.",explain:"Lưu bài thường xuyên giúp không bị mất bài.",answer:["lưu"]},{id:"th5-dung-may-tinh-hieu-qua-09",type:"tf",q:"Nên dùng máy tính trong phòng tối om để đỡ chói mắt.",explain:"Sai. Phòng tối làm mắt nhanh mỏi, phòng học cần đủ ánh sáng.",answer:!1,emoji:"💡"}]},{questions:[{id:"th5-dung-may-tinh-hieu-qua-10",type:"order",q:"Sắp xếp các bước tắt máy tính đúng cách.",explain:"Lưu bài, đóng phần mềm, chọn lệnh tắt máy rồi chờ máy tắt hẳn.",items:["Lưu bài đang làm","Đóng các phần mềm","Chọn lệnh tắt máy","Chờ màn hình tắt hẳn"]},{id:"th5-dung-may-tinh-hieu-qua-11",type:"mc",q:"Vì sao không nên rút điện khi máy tính đang chạy?",explain:"Rút điện đột ngột có thể làm mất bài chưa lưu và hại máy.",options:["Vì màn hình sẽ to ra hơn","Vì máy sẽ chạy nhanh hơn nữa","Vì có thể mất bài, hỏng máy"],answer:2},{id:"th5-dung-may-tinh-hieu-qua-12",type:"tf",q:"Dùng máy tính quá lâu có thể làm em mỏi mắt, đau lưng.",explain:"Đúng. Vì vậy cần giới hạn thời gian và nghỉ giải lao.",answer:!0},{id:"th5-dung-may-tinh-hieu-qua-13",type:"mc",q:"Đâu là cách dùng máy tính hiệu quả?",explain:"Tập trung làm xong việc chính rồi mới giải trí là hiệu quả.",options:["Làm bài xong rồi mới giải trí","Vừa xem phim vừa làm bài tập","Mở trò chơi khi đang làm bài"],answer:0},{id:"th5-dung-may-tinh-hieu-qua-14",type:"multi",q:"Những thói quen nào là không tốt khi dùng máy tính?",explain:"Ăn khi gõ phím, cúi sát màn hình, dùng máy không nghỉ đều có hại. Nghỉ giải lao là thói quen tốt.",options:["Ăn bánh khi đang gõ phím","Ngồi cúi sát màn hình","Nghỉ giải lao, vận động nhẹ","Dùng máy cả ngày không nghỉ"],answers:[0,1,3]},{id:"th5-dung-may-tinh-hieu-qua-15",type:"tf",q:"Tên tệp đặt tuỳ ý cũng được, vì máy tính tự nhớ giúp em nội dung bên trong.",explain:"Sai. Tên tệp rõ ràng giúp em nhìn là biết bên trong có gì, dễ tìm lại.",answer:!1,emoji:"🏷️"},{id:"th5-dung-may-tinh-hieu-qua-16",type:"match",q:"Ghép việc làm với lợi ích.",explain:"Mỗi thói quen tốt mang lại một lợi ích.",pairs:[["Lưu bài thường xuyên","Không mất bài khi có sự cố"],["Nghỉ mắt, nhìn ra xa","Mắt đỡ mỏi"],["Ngồi thẳng lưng","Lưng không bị đau"],["Tắt máy đúng cách","Máy bền, ít hỏng"]]},{id:"th5-dung-may-tinh-hieu-qua-17",type:"mc",q:"Nên chọn tên tệp nào cho bài văn tả con mèo?",explain:"Tên “Tả con mèo” cho biết rõ nội dung bài.",options:["Bài làm mới","Tả con mèo","Tệp số 123"],answer:1,emoji:"🐱"},{id:"th5-dung-may-tinh-hieu-qua-18",type:"tf",q:"Khi máy tính có mùi khét, em nên tự mở máy ra sửa.",explain:"Sai. Em cần ngừng dùng máy và báo ngay cho người lớn.",answer:!1}]},{questions:[{id:"th5-dung-may-tinh-hieu-qua-19",type:"mc",q:"An đang làm bài trình chiếu thì mẹ gọi đi ăn cơm. An nên làm gì trước khi rời máy?",explain:"Lưu bài trước để không mất phần đã làm.",options:["Rút ngay phích điện ra","Xoá bài để làm lại sau","Lưu bài trình chiếu lại"],answer:2},{id:"th5-dung-may-tinh-hieu-qua-20",type:"tf",q:"Minh chơi trò chơi trên máy tính rất lâu, mắt đã mỏi. Minh nên chơi tiếp cho xong màn.",explain:"Sai. Mắt mỏi thì Minh nên dừng lại, nghỉ ngơi và nhìn ra xa.",answer:!1},{id:"th5-dung-may-tinh-hieu-qua-21",type:"mc",q:"Chi thấy dây điện của máy tính bị hở. Chi nên làm gì?",explain:"Dây điện hở rất nguy hiểm, Chi cần báo người lớn và không chạm vào.",options:["Báo ngay cho người lớn","Vẫn dùng máy như thường","Tự quấn băng dính vào"],answer:0,emoji:"⚠️"},{id:"th5-dung-may-tinh-hieu-qua-22",type:"multi",q:"Tùng làm bài trên máy tính ở nhà. Việc nào giúp Tùng dùng máy hiệu quả và an toàn?",explain:"Nghỉ giải lao, lưu bài, ngồi đúng tư thế là thói quen tốt. Để cốc sữa cạnh bàn phím dễ đổ vào máy.",options:["Hẹn giờ nghỉ giải lao","Lưu bài sau mỗi phần","Để cốc sữa cạnh bàn phím","Ngồi đúng tư thế"],answers:[0,1,3]},{id:"th5-dung-may-tinh-hieu-qua-23",type:"mc",q:"Đang gõ bài thì máy tính bị mất điện. Bạn nào ít bị mất bài nhất?",explain:"Bạn vừa lưu bài chỉ mất phần gõ sau lần lưu đó.",options:["Bạn chưa lưu bài lần nào","Bạn vừa lưu bài ít phút trước","Bạn đang mở nhiều phần mềm"],answer:1},{id:"th5-dung-may-tinh-hieu-qua-24",type:"tf",q:"Ngọc dùng máy tính xong thì lưu bài, đóng phần mềm rồi chọn lệnh tắt máy. Ngọc làm đúng.",explain:"Đúng. Đó là cách tắt máy đúng.",answer:!0},{id:"th5-dung-may-tinh-hieu-qua-25",type:"mc",q:"Dũng ngồi cúi sát màn hình để nhìn chữ cho rõ. Dũng nên làm gì?",explain:"Phóng to chữ giúp nhìn rõ mà vẫn ngồi thẳng, không hại mắt.",options:["Nheo mắt để nhìn cho rõ","Cúi sát màn hình hơn nữa","Phóng to chữ, ngồi thẳng"],answer:2},{id:"th5-dung-may-tinh-hieu-qua-26",type:"match",q:"Ghép tình huống với cách xử lí đúng.",explain:"Mỗi tình huống cần cách xử lí an toàn và hợp lí.",pairs:[["Mắt mỏi khi dùng máy","Nghỉ, nhìn ra xa"],["Sắp phải rời máy","Lưu bài ngay"],["Dùng máy xong","Tắt máy đúng cách"],["Thấy máy bốc mùi khét","Báo người lớn"]]},{id:"th5-dung-may-tinh-hieu-qua-27",type:"tf",q:"Học xong, Thảo để máy chạy suốt đêm cho lần sau mở nhanh hơn. Thảo làm vậy là hợp lí.",explain:"Sai. Dùng xong nên tắt máy đúng cách để tiết kiệm điện và giữ máy bền.",answer:!1}]}],challenge:{questions:[{id:"th5-dung-may-tinh-hieu-qua-28",type:"mc",q:"Vy cần làm bài trên máy tính trong một giờ. Cách nào hợp lí nhất?",explain:"Nghỉ giữa chừng giúp mắt và lưng đỡ mỏi.",options:["Giữa chừng nghỉ, nhìn ra xa","Làm xong không cần lưu bài","Ngồi liền một giờ không nghỉ"],answer:0},{id:"th5-dung-may-tinh-hieu-qua-29",type:"multi",q:"Bài của Phúc bị mất vì máy bị treo. Lần sau Phúc nên làm gì?",explain:"Lưu ngay từ đầu và lưu thường xuyên giúp không mất bài. Rút điện có thể làm mất bài và hại máy.",options:["Lưu bài thường xuyên","Rút điện mỗi khi máy chậm","Lưu ngay khi bắt đầu làm","Không lưu cho đỡ mất thời gian"],answers:[0,2]},{id:"th5-dung-may-tinh-hieu-qua-30",type:"order",q:"Sắp xếp các việc khi dùng máy tính để làm một bài văn.",explain:"Bật máy, mở phần mềm, làm bài và lưu, xong thì đóng phần mềm và tắt máy.",items:["Bật máy tính","Mở phần mềm soạn thảo","Gõ bài và lưu lại","Đóng phần mềm, tắt máy"]},{id:"th5-dung-may-tinh-hieu-qua-19",type:"mc",q:"An đang làm bài trình chiếu thì mẹ gọi đi ăn cơm. An nên làm gì trước khi rời máy?",explain:"Lưu bài trước để không mất phần đã làm.",options:["Rút ngay phích điện ra","Xoá bài để làm lại sau","Lưu bài trình chiếu lại"],answer:2},{id:"th5-dung-may-tinh-hieu-qua-23",type:"mc",q:"Đang gõ bài thì máy tính bị mất điện. Bạn nào ít bị mất bài nhất?",explain:"Bạn vừa lưu bài chỉ mất phần gõ sau lần lưu đó.",options:["Bạn chưa lưu bài lần nào","Bạn vừa lưu bài ít phút trước","Bạn đang mở nhiều phần mềm"],answer:1},{id:"th5-dung-may-tinh-hieu-qua-25",type:"mc",q:"Dũng ngồi cúi sát màn hình để nhìn chữ cho rõ. Dũng nên làm gì?",explain:"Phóng to chữ giúp nhìn rõ mà vẫn ngồi thẳng, không hại mắt.",options:["Nheo mắt để nhìn cho rõ","Cúi sát màn hình hơn nữa","Phóng to chữ, ngồi thẳng"],answer:2},{id:"th5-dung-may-tinh-hieu-qua-26",type:"match",q:"Ghép tình huống với cách xử lí đúng.",explain:"Mỗi tình huống cần cách xử lí an toàn và hợp lí.",pairs:[["Mắt mỏi khi dùng máy","Nghỉ, nhìn ra xa"],["Sắp phải rời máy","Lưu bài ngay"],["Dùng máy xong","Tắt máy đúng cách"],["Thấy máy bốc mùi khét","Báo người lớn"]]}]},summary:["Dùng máy tính đúng mục đích, có giới hạn thời gian, ngồi đúng tư thế và nghỉ mắt.","Lưu bài thường xuyên, tắt máy đúng cách và giữ gìn máy cẩn thận."]}]},{id:"mang-may-tinh-internet",title:"Mạng máy tính và Internet",lessons:[{id:"th5-tim-kiem-tren-website",title:"Bài 3: Tìm kiếm thông tin trên một website",weeks:[4,5],learn:[{title:"Website và trang chủ",text:"Website gồm nhiều trang web có liên quan, được liên kết với nhau. Trang hiện ra đầu tiên khi mở website gọi là trang chủ.",example:"🏠 trang chủ → 📄 các trang khác"},{title:"Thanh menu",text:"Thanh menu chứa tên các mục lớn của website như Giới thiệu, Tin tức, Liên hệ. Nháy vào một mục để mở trang của mục đó.",example:"☰ Giới thiệu · Tin tức · Thư viện · Liên hệ"},{title:"Ô tìm kiếm của website",text:"Nhiều website có ô tìm kiếm riêng, thường có hình kính lúp. Ô này chỉ tìm trong các trang của website đó, không tìm khắp Internet.",example:"🔍 từ khoá → kết quả trong website"},{title:"Chọn từ khoá cho website",text:"Vì đã ở đúng website, em gõ từ khoá ngắn, đúng với điều cần tìm. Không thấy kết quả thì kiểm tra chính tả, thử từ khoá khác hoặc tìm qua menu và liên kết.",example:"✅ cá heo  ·  ❌ bài viết hay"}],practice:[{questions:[{id:"th5-tim-kiem-tren-website-01",type:"mc",q:"Trang hiện ra đầu tiên khi mở một website gọi là gì?",explain:"Trang đầu tiên của website gọi là trang chủ.",options:["Trang lỗi","Trang chủ","Trang cuối"],answer:1,emoji:"🏠"},{id:"th5-tim-kiem-tren-website-02",type:"mc",q:"Ô tìm kiếm trên website thường có biểu tượng nào?",explain:"Biểu tượng kính lúp thường dùng cho việc tìm kiếm.",options:["Cái kéo","Thùng rác","Kính lúp"],answer:2,emoji:"🔍"},{id:"th5-tim-kiem-tren-website-03",type:"tf",q:"Ô tìm kiếm riêng của một website chỉ tìm trong các trang của website đó.",explain:"Đúng. Muốn tìm khắp Internet thì dùng máy tìm kiếm.",answer:!0},{id:"th5-tim-kiem-tren-website-04",type:"tf",q:"Website nào cũng chỉ có duy nhất một trang.",explain:"Sai. Website thường gồm nhiều trang web liên kết với nhau.",answer:!1},{id:"th5-tim-kiem-tren-website-05",type:"fill",q:"Điền từ còn thiếu: Thanh chứa các mục lớn như Giới thiệu, Tin tức, Liên hệ gọi là thanh … .",explain:"Đó là thanh menu, còn gọi là thanh điều hướng.",answer:["menu","mê-nu","điều hướng"]},{id:"th5-tim-kiem-tren-website-06",type:"mc",q:"Muốn mở trang của một mục trên thanh menu, em làm gì?",explain:"Nháy vào tên mục trên menu sẽ mở trang của mục đó.",options:["Nháy chuột vào tên mục đó","Tắt rồi mở lại trình duyệt","Gõ tên mục bằng bàn phím"],answer:0},{id:"th5-tim-kiem-tren-website-07",type:"tf",q:"Trên website, nháy vào siêu liên kết có thể đưa em sang một trang khác của website đó.",explain:"Đúng. Các trang trong website được nối với nhau bằng liên kết.",answer:!0},{id:"th5-tim-kiem-tren-website-08",type:"multi",q:"Trên một website, em có thể tìm thông tin bằng những cách nào?",explain:"Menu, ô tìm kiếm và liên kết đều giúp tìm thông tin. Tắt màn hình thì không xem được gì.",options:["Dùng thanh menu","Dùng ô tìm kiếm của website","Tắt màn hình đi","Nháy vào các liên kết"],answers:[0,1,3]},{id:"th5-tim-kiem-tren-website-09",type:"match",q:"Ghép phần của website với công dụng.",explain:"Mỗi phần của website có một công dụng riêng.",pairs:[["Trang chủ","Trang đầu tiên của website"],["Thanh menu","Chứa các mục lớn"],["Ô tìm kiếm","Tìm nhanh bằng từ khoá"],["Siêu liên kết","Mở sang trang khác"]]}]},{questions:[{id:"th5-tim-kiem-tren-website-10",type:"mc",q:"Ô tìm kiếm của website khác máy tìm kiếm ở điểm nào?",explain:"Ô tìm kiếm của website chỉ tìm trong các trang của website ấy.",options:["Không cần gõ từ khoá","Chỉ tìm trong website đó","Tìm được trên khắp Internet"],answer:1},{id:"th5-tim-kiem-tren-website-11",type:"tf",q:"Gõ từ khoá vào ô tìm kiếm của website trường em sẽ cho kết quả từ mọi website trên thế giới.",explain:"Sai. Ô tìm kiếm đó chỉ tìm trong website của trường.",answer:!1},{id:"th5-tim-kiem-tren-website-12",type:"mc",q:"Website của trường có các mục: Giới thiệu, Tin tức, Thời khoá biểu, Liên hệ. Muốn xem lịch học, em chọn mục nào?",explain:"Lịch học của các lớp nằm ở mục Thời khoá biểu.",options:["Giới thiệu","Liên hệ","Thời khoá biểu","Tin tức"],answer:2,emoji:"📅"},{id:"th5-tim-kiem-tren-website-13",type:"mc",q:"Em đang ở website về động vật, muốn tìm bài về loài hổ. Từ khoá nào hợp lí nhất?",explain:"Đã ở website động vật nên chỉ cần gõ đúng tên con vật cần tìm.",options:["hổ","bài viết hay nhất","con vật"],answer:0,emoji:"🐯"},{id:"th5-tim-kiem-tren-website-14",type:"tf",q:"Khi đã ở đúng website, em nên gõ cả một câu thật dài để tìm cho nhanh.",explain:"Sai. Từ khoá ngắn, đúng nội dung giúp tìm nhanh và chính xác hơn.",answer:!1},{id:"th5-tim-kiem-tren-website-15",type:"multi",q:"Tìm trong website mà không thấy kết quả, em có thể làm gì?",explain:"Đổi từ khoá, sửa chính tả hoặc tìm qua menu đều có thể giúp em tìm thấy.",options:["Thử từ khoá khác","Kiểm tra chính tả của từ khoá","Tìm qua thanh menu","Tắt máy rồi bỏ cuộc"],answers:[0,1,2]},{id:"th5-tim-kiem-tren-website-16",type:"order",q:"Sắp xếp các bước tìm thông tin bằng ô tìm kiếm của website.",explain:"Mở website, gõ từ khoá vào ô tìm kiếm, nhấn tìm rồi chọn kết quả.",items:["Mở website cần tìm","Nháy vào ô tìm kiếm","Gõ từ khoá","Nhấn Enter hoặc nút tìm kiếm","Chọn kết quả phù hợp"]},{id:"th5-tim-kiem-tren-website-17",type:"mc",q:"Vì sao tìm trong một website thường ra ít kết quả hơn dùng máy tìm kiếm?",explain:"Ô tìm kiếm của website chỉ tìm trong các trang của nó nên ít kết quả hơn.",options:["Vì máy tính đang tắt","Vì chỉ tìm trong một website","Vì website không có chữ nào"],answer:1},{id:"th5-tim-kiem-tren-website-18",type:"tf",q:"Thanh menu của website thường nằm ở phía trên hoặc bên cạnh trang.",explain:"Đúng. Đặt menu ở đó giúp em dễ nhìn thấy.",answer:!0}]},{questions:[{id:"th5-tim-kiem-tren-website-19",type:"mc",q:"Lan vào website của thư viện để tìm truyện Thánh Gióng. Lan nên gõ gì vào ô tìm kiếm của website?",explain:"Đã ở website thư viện, Lan chỉ cần gõ đúng tên truyện.",options:["truyện hay để đọc ở nhà","thư viện thành phố","Thánh Gióng"],answer:2,emoji:"📖"},{id:"th5-tim-kiem-tren-website-20",type:"mc",q:"Website của một vườn thú có các mục: Các loài vật, Giờ mở cửa, Giá vé, Liên hệ. Nam muốn biết mấy giờ vườn mở cửa. Nam chọn mục nào?",explain:"Mục Giờ mở cửa cho biết thời gian vườn thú mở cửa.",options:["Các loài vật","Giá vé","Giờ mở cửa","Liên hệ"],answer:2,emoji:"🦒"},{id:"th5-tim-kiem-tren-website-21",type:"tf",q:"Bình muốn tìm “khủng long” nhưng gõ thiếu một chữ cái nên không thấy kết quả. Gõ đúng chính tả sẽ giúp tìm thấy dễ hơn.",explain:"Đúng. Từ khóa sai chính tả thường không khớp với nội dung trên website nên không tìm thấy.",answer:!0,emoji:"🦕"},{id:"th5-tim-kiem-tren-website-22",type:"mc",q:"Chi tìm “cá heo” trong website về biển nhưng có quá nhiều kết quả. Chi nên làm gì?",explain:"Thêm từ cho rõ điều cần tìm giúp kết quả ít và đúng hơn.",options:["Đóng website rồi bỏ cuộc","Thêm từ cho rõ: cá heo ăn gì","Bớt từ, chỉ gõ một chữ cá"],answer:1,emoji:"🐬"},{id:"th5-tim-kiem-tren-website-23",type:"multi",q:"Website của trường có thanh menu và ô tìm kiếm. Hà muốn đọc tin về lễ khai giảng năm nay. Hà có thể làm cách nào?",explain:"Tin về lễ khai giảng có thể tìm qua mục Tin tức hoặc ô tìm kiếm của website trường.",options:["Vào mục Tin tức trên menu","Gõ “khai giảng” vào ô tìm kiếm","Mở một website khác hẳn","Tắt trình duyệt đi"],answers:[0,1]},{id:"th5-tim-kiem-tren-website-24",type:"order",q:"Khoa muốn đọc bài về Hồ Gươm trên website du lịch của thành phố. Sắp xếp các bước.",explain:"Mở trình duyệt, vào website, tìm bằng từ khoá rồi chọn bài phù hợp.",items:["Mở trình duyệt","Mở website du lịch của thành phố","Gõ “Hồ Gươm” vào ô tìm kiếm","Nháy vào bài phù hợp"]},{id:"th5-tim-kiem-tren-website-25",type:"tf",q:"Ngọc dùng ô tìm kiếm của website trường để tìm tin về một giải bóng đá thế giới. Đây là cách tìm phù hợp.",explain:"Sai. Website trường không có tin đó, Ngọc nên dùng máy tìm kiếm.",answer:!1},{id:"th5-tim-kiem-tren-website-26",type:"match",q:"Ghép điều cần tìm với cách tìm phù hợp nhất.",explain:"Chọn cách tìm phù hợp giúp em tìm thấy nhanh hơn.",pairs:[["Số điện thoại của trường trên website trường","Mục Liên hệ"],["Một bài cụ thể trong website","Ô tìm kiếm của website"],["Thông tin trên nhiều website","Máy tìm kiếm"]]},{id:"th5-tim-kiem-tren-website-27",type:"tf",q:"Đã vào website của một bảo tàng, muốn đọc bài về trống đồng, em gõ “trống đồng” vào ô tìm kiếm của website là hợp lí.",explain:"Đúng. Từ khoá ngắn, đúng tên hiện vật giúp tìm nhanh trong website.",answer:!0,emoji:"🥁"}]}],challenge:{questions:[{id:"th5-tim-kiem-tren-website-28",type:"mc",q:"Website của câu lạc bộ cờ vua không có ô tìm kiếm. Muốn tìm lịch thi đấu, Minh nên làm gì?",explain:"Không có ô tìm kiếm thì Minh tìm qua các mục trên menu và liên kết.",options:["Gõ địa chỉ website bất kì","Đợi website tự hiện lịch","Xem các mục trên thanh menu"],answer:2,emoji:"♟️"},{id:"th5-tim-kiem-tren-website-29",type:"multi",q:"Những từ khoá nào phù hợp khi tìm trong website về các loài chim?",explain:"Từ khoá cần nói rõ điều muốn tìm, như tên loài chim hay việc cần biết.",options:["chim cánh cụt","website hay","cách nuôi chim sẻ","bài này"],answers:[0,2],emoji:"🐧"},{id:"th5-tim-kiem-tren-website-30",type:"tf",q:"Mọi website đều có ô tìm kiếm riêng.",explain:"Sai. Có website không có ô tìm kiếm, khi đó em tìm qua menu và liên kết.",answer:!1},{id:"th5-tim-kiem-tren-website-17",type:"mc",q:"Vì sao tìm trong một website thường ra ít kết quả hơn dùng máy tìm kiếm?",explain:"Ô tìm kiếm của website chỉ tìm trong các trang của nó nên ít kết quả hơn.",options:["Vì máy tính đang tắt","Vì chỉ tìm trong một website","Vì website không có chữ nào"],answer:1},{id:"th5-tim-kiem-tren-website-22",type:"mc",q:"Chi tìm “cá heo” trong website về biển nhưng có quá nhiều kết quả. Chi nên làm gì?",explain:"Thêm từ cho rõ điều cần tìm giúp kết quả ít và đúng hơn.",options:["Đóng website rồi bỏ cuộc","Thêm từ cho rõ: cá heo ăn gì","Bớt từ, chỉ gõ một chữ cá"],answer:1,emoji:"🐬"},{id:"th5-tim-kiem-tren-website-23",type:"multi",q:"Website của trường có thanh menu và ô tìm kiếm. Hà muốn đọc tin về lễ khai giảng năm nay. Hà có thể làm cách nào?",explain:"Tin về lễ khai giảng có thể tìm qua mục Tin tức hoặc ô tìm kiếm của website trường.",options:["Vào mục Tin tức trên menu","Gõ “khai giảng” vào ô tìm kiếm","Mở một website khác hẳn","Tắt trình duyệt đi"],answers:[0,1]},{id:"th5-tim-kiem-tren-website-26",type:"match",q:"Ghép điều cần tìm với cách tìm phù hợp nhất.",explain:"Chọn cách tìm phù hợp giúp em tìm thấy nhanh hơn.",pairs:[["Số điện thoại của trường trên website trường","Mục Liên hệ"],["Một bài cụ thể trong website","Ô tìm kiếm của website"],["Thông tin trên nhiều website","Máy tìm kiếm"]]}]},summary:["Trên một website, em tìm thông tin qua thanh menu, các liên kết và ô tìm kiếm của website.","Ô tìm kiếm của website chỉ tìm trong website đó, nên chỉ cần từ khoá ngắn, đúng chính tả."]},{id:"th5-do-tin-cay",title:"Bài 4: Đánh giá và lọc thông tin trên Internet",weeks:[6,7],learn:[{title:"Không phải tin nào cũng đúng",text:"Ai cũng có thể đưa thông tin lên Internet, nên có tin đúng, tin sai, tin đồn và quảng cáo. Em cần tỉnh táo trước khi tin.",example:"✅ tin đúng · ❌ tin sai · 📢 quảng cáo"},{title:"Nguồn đáng tin cậy",text:"Website chính thức của cơ quan nhà nước, trường học, báo chí uy tín hay bách khoa thư thường là nguồn đáng tin cậy hơn.",example:"🏛️ cơ quan · 🏫 trường học · 📰 báo uy tín"},{title:"Kiểm tra thông tin",text:"Hãy xem ai viết, viết khi nào và so sánh với vài nguồn khác. Thông tin cũ có thể không còn đúng.",example:"👤 ai viết? · 📅 khi nào? · 🔎 so sánh"},{title:"Lọc thông tin",text:"Lọc thông tin là giữ lại thông tin đúng, cần thiết và bỏ qua thông tin không phù hợp. Gặp quảng cáo, lời mời trúng thưởng hay tin lạ thì hỏi thầy cô, cha mẹ.",example:"🧹 giữ cái đúng, bỏ cái thừa"}],practice:[{questions:[{id:"th5-do-tin-cay-01",type:"tf",q:"Mọi thông tin trên Internet đều đúng.",explain:"Sai. Trên Internet có cả tin đúng, tin sai và tin đồn.",answer:!1},{id:"th5-do-tin-cay-02",type:"mc",q:"Nguồn nào thường đáng tin cậy hơn?",explain:"Website chính thức của trường có nơi chịu trách nhiệm về thông tin.",options:["Website chính thức của trường","Quảng cáo nhấp nháy trên trang","Bình luận của người lạ trên mạng"],answer:0,emoji:"🏫"},{id:"th5-do-tin-cay-03",type:"multi",q:"Khi đọc một thông tin trên mạng, em nên kiểm tra những gì?",explain:"Tác giả, thời gian và các nguồn khác giúp em đánh giá thông tin. Màu chữ không nói lên điều gì.",options:["Ai viết thông tin đó","Thông tin viết khi nào","Chữ được tô màu gì","Các nguồn khác nói gì"],answers:[0,1,3]},{id:"th5-do-tin-cay-04",type:"tf",q:"Thông tin viết từ lâu có thể không còn đúng ở hiện tại.",explain:"Đúng. Vì vậy em nên xem ngày đăng thông tin.",answer:!0,emoji:"📅"},{id:"th5-do-tin-cay-05",type:"mc",q:"Gặp thông tin lạ mà không biết đúng hay sai, em nên làm gì?",explain:"Người lớn giúp em kiểm tra thông tin trước khi tin.",options:["Chia sẻ ngay cho bạn bè","Hỏi thầy cô hoặc cha mẹ","Tin ngay vì có trên mạng"],answer:1},{id:"th5-do-tin-cay-06",type:"fill",q:"Điền từ còn thiếu: Quảng cáo, tin giật gân hay lời mời trúng … thường dụ em nháy vào.",explain:"Lời mời trúng thưởng thường là bẫy, em không nên nháy vào.",answer:["thưởng"]},{id:"th5-do-tin-cay-07",type:"tf",q:"Quảng cáo trên trang web luôn nói đúng sự thật.",explain:"Sai. Quảng cáo muốn bán hàng nên có thể nói quá lên.",answer:!1,emoji:"📢"},{id:"th5-do-tin-cay-08",type:"mc",q:"Thông tin nào em cần cẩn thận nhất?",explain:"Lời mời bấm vào để nhận quà thường là bẫy lừa.",options:["Bài trong bách khoa thư uy tín","Thông báo trên website trường","Tin “Bấm vào đây để nhận quà”"],answer:2,emoji:"🎁"},{id:"th5-do-tin-cay-09",type:"mc",q:"So sánh thông tin ở nhiều nguồn giúp em điều gì?",explain:"Nhiều nguồn tin cậy cùng nói giống nhau thì thông tin đáng tin hơn.",options:["Biết thông tin có đúng không","Làm máy tính chạy nhanh hơn","Xem thêm được nhiều quảng cáo"],answer:0}]},{questions:[{id:"th5-do-tin-cay-10",type:"match",q:"Ghép câu hỏi kiểm tra với điều cần xem.",explain:"Ba câu hỏi này giúp em đánh giá một thông tin.",pairs:[["Ai viết?","Tác giả hoặc nơi đăng tin"],["Viết khi nào?","Ngày đăng bài"],["Nơi khác nói gì?","So sánh với nguồn khác"]]},{id:"th5-do-tin-cay-11",type:"tf",q:"Một tin được nhiều người chia sẻ thì chắc chắn là tin đúng.",explain:"Sai. Tin sai cũng có thể bị chia sẻ rất nhiều.",answer:!1},{id:"th5-do-tin-cay-12",type:"mc",q:"Vì sao website chính thức của cơ quan nhà nước thường đáng tin cậy?",explain:"Cơ quan đăng tin phải chịu trách nhiệm về thông tin của mình.",options:["Vì có nhiều trò chơi vui","Vì có nơi chịu trách nhiệm","Vì có nhiều màu sắc đẹp"],answer:1,emoji:"🏛️"},{id:"th5-do-tin-cay-13",type:"multi",q:"Dấu hiệu nào cho thấy một tin có thể không đáng tin?",explain:"Không rõ tác giả, giật gân, chỉ một trang lạ đưa tin là dấu hiệu cần cẩn thận.",options:["Không rõ ai viết","Tiêu đề giật gân, gây sốc","Có trên website chính thức của trường","Chỉ một trang lạ đưa tin"],answers:[0,1,3]},{id:"th5-do-tin-cay-14",type:"tf",q:"Khi hai nguồn uy tín cùng đưa thông tin giống nhau, em có thể tin tưởng hơn.",explain:"Đúng. Nhiều nguồn uy tín giống nhau giúp thông tin đáng tin hơn.",answer:!0},{id:"th5-do-tin-cay-15",type:"mc",q:"Một bài viết nói “Ăn nhiều kẹo giúp răng chắc khoẻ” và không ghi ai viết. Em đánh giá thế nào?",explain:"Bài không rõ tác giả và nói sai điều quen thuộc: ăn nhiều kẹo dễ sâu răng.",options:["Đáng tin, vì câu viết rất ngắn","Đáng tin, vì đã có trên mạng","Chưa đáng tin, cần kiểm tra lại"],answer:2,emoji:"🍬"},{id:"th5-do-tin-cay-16",type:"order",q:"Sắp xếp các bước kiểm tra một thông tin trên mạng.",explain:"Đọc kĩ, xem nguồn, so sánh rồi mới quyết định.",items:["Đọc kĩ thông tin","Xem ai viết, viết khi nào","So sánh với nguồn khác","Quyết định có tin hay không"]},{id:"th5-do-tin-cay-17",type:"tf",q:"Lọc thông tin nghĩa là giữ lại mọi thông tin tìm được, kể cả tin sai.",explain:"Sai. Lọc thông tin là giữ thông tin đúng, cần thiết và bỏ thông tin không phù hợp.",answer:!1},{id:"th5-do-tin-cay-18",type:"mc",q:"Đang xem bài học thì hiện cửa sổ “Bạn đã trúng thưởng điện thoại”. Em nên làm gì?",explain:"Đây thường là quảng cáo lừa, em đóng lại và báo người lớn.",options:["Đóng lại, báo người lớn","Nhập địa chỉ nhà mình","Nháy vào để nhận quà"],answer:0,emoji:"📱"}]},{questions:[{id:"th5-do-tin-cay-19",type:"mc",q:"Nam tìm chiều cao của một ngọn núi, thấy ba trang ghi ba số khác nhau. Nam nên làm gì?",explain:"Khi các nguồn khác nhau, nên tin nguồn chính thức, uy tín.",options:["Chọn số to nhất","Xem trang chính thức, uy tín","Chọn trang hiện đầu tiên"],answer:1,emoji:"⛰️"},{id:"th5-do-tin-cay-20",type:"tf",q:"Hà đọc tin “Ngày mai trường nghỉ học” trên một trang lạ. Hà nên xem thông báo của trường hoặc hỏi cô giáo.",explain:"Đúng. Tin về trường nên kiểm tra ở nguồn chính thức của trường.",answer:!0},{id:"th5-do-tin-cay-21",type:"multi",q:"Thảo làm bài về loài gấu trúc. Nguồn nào phù hợp để Thảo tham khảo?",explain:"Bách khoa thư, vườn thú lớn và sách khoa học là nguồn đáng tin. Bình luận không tên thì khó kiểm chứng.",options:["Bách khoa thư uy tín","Website của một vườn thú lớn","Bình luận không tên trên mạng","Sách khoa học trong thư viện"],answers:[0,1,3],emoji:"🐼"},{id:"th5-do-tin-cay-22",type:"mc",q:"Bài hướng dẫn phòng bệnh đăng từ rất lâu, nay đã có hướng dẫn mới. Em nên dùng bài nào?",explain:"Thông tin cũ có thể không còn đúng, nên dùng hướng dẫn mới từ nguồn uy tín.",options:["Bài nào có nhiều hình hơn","Bài cũ vì viết trước","Hướng dẫn mới từ nguồn uy tín"],answer:2},{id:"th5-do-tin-cay-23",type:"tf",q:"Dũng thấy một bài có tiêu đề rất giật gân và chia sẻ ngay cho cả lớp mà chưa kiểm tra. Dũng làm đúng.",explain:"Sai. Dũng cần kiểm tra trước, chia sẻ tin sai có thể làm nhiều người hiểu lầm.",answer:!1},{id:"th5-do-tin-cay-24",type:"match",q:"Ghép tình huống với cách xử lí.",explain:"Mỗi tình huống có cách lọc thông tin phù hợp.",pairs:[["Tin không rõ ai viết","Kiểm tra ở nguồn khác"],["Lời mời trúng thưởng","Không nháy, báo người lớn"],["Bài viết đã cũ","Tìm thông tin mới hơn"],["Muốn biết lịch nghỉ của trường","Xem website của trường"]]},{id:"th5-do-tin-cay-25",type:"mc",q:"Bình đọc một tin trên trang lạ, Chi đọc cùng tin đó trên website chính thức của cơ quan nhà nước. Nguồn của ai đáng tin hơn?",explain:"Website chính thức của cơ quan nhà nước đáng tin hơn trang lạ.",options:["Nguồn của Chi","Hai nguồn như nhau","Nguồn của Bình"],answer:0},{id:"th5-do-tin-cay-26",type:"fill",q:"Điền từ còn thiếu: Trước khi tin một thông tin, em nên so sánh với nhiều … khác.",explain:"So sánh nhiều nguồn giúp em biết thông tin có đúng không.",answer:["nguồn","nguồn tin"]},{id:"th5-do-tin-cay-27",type:"tf",q:"Một trang web có nhiều quảng cáo nhấp nháy và mời tải trò chơi lạ là trang em cần cẩn thận.",explain:"Đúng. Trang như vậy dễ có lừa đảo hoặc phần mềm độc hại.",answer:!0}]}],challenge:{questions:[{id:"th5-do-tin-cay-28",type:"multi",q:"Minh muốn biết lịch thi đấu của một giải bóng đá thiếu nhi. Minh nên làm gì?",explain:"Nguồn chính thức, báo uy tín và ngày đăng giúp Minh có thông tin đúng. Bình luận người lạ khó kiểm chứng.",options:["Xem website chính thức của giải","So sánh với báo chí uy tín","Tin bình luận của người lạ","Xem ngày đăng thông tin"],answers:[0,1,3],emoji:"⚽"},{id:"th5-do-tin-cay-29",type:"mc",q:"Một bài viết ghi rõ tác giả, ngày đăng và nói giống sách giáo khoa. Bài này thế nào?",explain:"Rõ tác giả, rõ ngày và khớp với nguồn tin cậy là dấu hiệu đáng tin.",options:["Chắc chắn là quảng cáo","Có nhiều dấu hiệu đáng tin","Chắc chắn là tin sai"],answer:1},{id:"th5-do-tin-cay-30",type:"tf",q:"Thông tin có kèm hình ảnh thì luôn là thông tin đúng.",explain:"Sai. Hình ảnh cũng có thể bị sửa hoặc dùng sai chỗ.",answer:!1,emoji:"🖼️"},{id:"th5-do-tin-cay-15",type:"mc",q:"Một bài viết nói “Ăn nhiều kẹo giúp răng chắc khoẻ” và không ghi ai viết. Em đánh giá thế nào?",explain:"Bài không rõ tác giả và nói sai điều quen thuộc: ăn nhiều kẹo dễ sâu răng.",options:["Đáng tin, vì câu viết rất ngắn","Đáng tin, vì đã có trên mạng","Chưa đáng tin, cần kiểm tra lại"],answer:2,emoji:"🍬"},{id:"th5-do-tin-cay-19",type:"mc",q:"Nam tìm chiều cao của một ngọn núi, thấy ba trang ghi ba số khác nhau. Nam nên làm gì?",explain:"Khi các nguồn khác nhau, nên tin nguồn chính thức, uy tín.",options:["Chọn số to nhất","Xem trang chính thức, uy tín","Chọn trang hiện đầu tiên"],answer:1,emoji:"⛰️"},{id:"th5-do-tin-cay-22",type:"mc",q:"Bài hướng dẫn phòng bệnh đăng từ rất lâu, nay đã có hướng dẫn mới. Em nên dùng bài nào?",explain:"Thông tin cũ có thể không còn đúng, nên dùng hướng dẫn mới từ nguồn uy tín.",options:["Bài nào có nhiều hình hơn","Bài cũ vì viết trước","Hướng dẫn mới từ nguồn uy tín"],answer:2},{id:"th5-do-tin-cay-24",type:"match",q:"Ghép tình huống với cách xử lí.",explain:"Mỗi tình huống có cách lọc thông tin phù hợp.",pairs:[["Tin không rõ ai viết","Kiểm tra ở nguồn khác"],["Lời mời trúng thưởng","Không nháy, báo người lớn"],["Bài viết đã cũ","Tìm thông tin mới hơn"],["Muốn biết lịch nghỉ của trường","Xem website của trường"]]}]},summary:["Thông tin trên Internet có đúng có sai, em cần xem ai viết, viết khi nào và so sánh nhiều nguồn.","Ưu tiên nguồn chính thức, uy tín; cẩn thận với quảng cáo, tin giật gân và hỏi người lớn khi chưa chắc."]}]},{id:"luu-tru-tim-kiem-trao-doi",title:"Tổ chức lưu trữ, tìm kiếm và trao đổi thông tin",lessons:[{id:"th5-thong-tin-giai-quyet-van-de",title:"Bài 5: Thông tin giúp giải quyết vấn đề",weeks:[8,9],learn:[{title:"Cần thông tin gì?",text:"Muốn giải quyết một việc, trước hết em xác định cần biết những thông tin gì. Ví dụ, đi dã ngoại cần biết địa điểm, thời gian, thời tiết và chi phí.",example:"🗺️ địa điểm · ⏰ thời gian · ☀️ thời tiết · 💰 chi phí"},{title:"Thu thập và chọn lọc",text:"Thu thập thông tin từ nguồn tin cậy như sách, website chính thức hay hỏi người lớn. Giữ lại thông tin đúng, liên quan và bỏ thông tin không cần.",example:"📚 sách · 🌐 website chính thức · 🧑‍🏫 thầy cô"},{title:"Sắp xếp thông tin",text:"Sắp xếp thông tin vào bảng hoặc danh sách giúp em dễ nhìn, dễ so sánh.",example:"📋 Địa điểm | Khoảng cách | Giá vé"},{title:"Dùng thông tin để quyết định",text:"Dựa vào thông tin đã sắp xếp, em so sánh các lựa chọn rồi chọn cách làm phù hợp nhất.",example:"🔎 so sánh → ✅ quyết định"}],practice:[{questions:[{id:"th5-thong-tin-giai-quyet-van-de-01",type:"order",q:"Sắp xếp các bước dùng thông tin để giải quyết vấn đề.",explain:"Biết cần gì, thu thập, chọn lọc và sắp xếp, rồi mới quyết định.",items:["Xác định thông tin cần có","Thu thập thông tin","Chọn lọc và sắp xếp thông tin","Dùng thông tin để quyết định"]},{id:"th5-thong-tin-giai-quyet-van-de-02",type:"mc",q:"Để lên kế hoạch đi dã ngoại, thông tin nào cần thiết?",explain:"Thời tiết giúp chọn ngày đi và đồ cần mang.",options:["Tên con mèo nhà bạn","Màu áo của cô giáo","Thời tiết hôm đi"],answer:2,emoji:"⛺"},{id:"th5-thong-tin-giai-quyet-van-de-03",type:"tf",q:"Sắp xếp thông tin vào bảng giúp em dễ so sánh hơn.",explain:"Đúng. Bảng đặt các thông tin cạnh nhau nên dễ so sánh.",answer:!0,emoji:"📋"},{id:"th5-thong-tin-giai-quyet-van-de-04",type:"tf",q:"Thông tin càng nhiều càng tốt, không cần chọn lọc.",explain:"Sai. Cần giữ thông tin đúng, liên quan và bỏ thông tin thừa.",answer:!1},{id:"th5-thong-tin-giai-quyet-van-de-05",type:"multi",q:"Lớp em đi tham quan. Những thông tin nào cần biết?",explain:"Địa điểm, thời gian và chi phí liên quan tới chuyến đi. Món ăn của ca sĩ không liên quan.",options:["Địa điểm tham quan","Thời gian đi và về","Món ăn yêu thích của ca sĩ","Chi phí cho mỗi bạn"],answers:[0,1,3],emoji:"🚌"},{id:"th5-thong-tin-giai-quyet-van-de-06",type:"mc",q:"Bước đầu tiên khi dùng thông tin để giải quyết một việc là gì?",explain:"Phải biết mình cần thông tin gì thì mới thu thập đúng.",options:["Xác định cần thông tin gì","Chia sẻ lên mạng xã hội","Ra quyết định ngay lập tức"],answer:0},{id:"th5-thong-tin-giai-quyet-van-de-07",type:"fill",q:"Điền từ còn thiếu: Sắp xếp thông tin vào … giúp dễ so sánh các lựa chọn.",explain:"Bảng hoặc danh sách giúp nhìn và so sánh dễ hơn.",answer:["bảng","bảng biểu","danh sách"]},{id:"th5-thong-tin-giai-quyet-van-de-08",type:"tf",q:"Em có thể thu thập thông tin từ sách, website chính thức và hỏi người lớn.",explain:"Đúng. Đó là các nguồn thông tin tin cậy.",answer:!0},{id:"th5-thong-tin-giai-quyet-van-de-09",type:"mc",q:"Thông tin nào giúp em chọn trang phục khi đi chơi ngày mai?",explain:"Biết trời nắng hay mưa, lạnh hay nóng thì em chọn được trang phục phù hợp.",options:["Tên bài hát mới","Dự báo thời tiết","Giá vé xem phim"],answer:1,emoji:"👕"}]},{questions:[{id:"th5-thong-tin-giai-quyet-van-de-10",type:"mc",q:"Vì sao phải chọn lọc thông tin?",explain:"Chọn lọc giúp giữ lại thông tin đúng, có ích cho việc cần làm.",options:["Để có thật nhiều thông tin","Để bỏ hết thông tin đi","Để giữ thông tin đúng và cần"],answer:2},{id:"th5-thong-tin-giai-quyet-van-de-11",type:"match",q:"Ghép việc cần làm với thông tin cần tìm.",explain:"Mỗi việc cần một loại thông tin phù hợp.",pairs:[["Chọn giờ xuất phát","Giờ mở cửa nơi đến"],["Chuẩn bị tiền","Giá vé"],["Chọn mang áo mưa hay mũ","Dự báo thời tiết"],["Chọn đường đi","Bản đồ"]]},{id:"th5-thong-tin-giai-quyet-van-de-12",type:"tf",q:"Khi chọn quà sinh nhật cho bạn, biết sở thích của bạn giúp em chọn quà phù hợp.",explain:"Đúng. Sở thích của bạn là thông tin giúp em quyết định.",answer:!0,emoji:"🎁"},{id:"th5-thong-tin-giai-quyet-van-de-13",type:"mc",q:"Lan kẻ bảng có ba cột: Địa điểm, Khoảng cách, Giá vé. Bảng này giúp Lan làm gì?",explain:"Bảng đặt khoảng cách, giá vé của các nơi cạnh nhau để dễ so sánh.",options:["So sánh các địa điểm","Tô màu cho trang vở","Đếm số bạn trong lớp"],answer:0},{id:"th5-thong-tin-giai-quyet-van-de-14",type:"multi",q:"Nhóm em tìm hiểu cách trồng cây đậu. Thông tin nào liên quan?",explain:"Gieo hạt, tưới nước, ánh sáng đều liên quan tới trồng cây. Giá xe đạp thì không.",options:["Cách gieo hạt","Lượng nước tưới","Giá một chiếc xe đạp","Chỗ để đủ ánh sáng"],answers:[0,1,3],emoji:"🌱"},{id:"th5-thong-tin-giai-quyet-van-de-15",type:"tf",q:"Thông tin lấy từ nguồn không đáng tin có thể dẫn tới quyết định sai.",explain:"Đúng. Thông tin sai thì quyết định dựa vào nó cũng dễ sai.",answer:!0},{id:"th5-thong-tin-giai-quyet-van-de-16",type:"tf",q:"Thu thập xong thông tin thì không cần sắp xếp, vì sắp xếp chỉ làm mất thời gian.",explain:"Sai. Sắp xếp giúp so sánh nhanh và quyết định chính xác hơn.",answer:!1},{id:"th5-thong-tin-giai-quyet-van-de-17",type:"mc",q:"Muốn biết đi bộ hay đi xe buýt tới bảo tàng nhanh hơn, em cần thông tin gì?",explain:"So sánh thời gian đi của hai cách thì biết cách nào nhanh hơn.",options:["Tên của người bán vé","Thời gian đi của mỗi cách","Màu sơn của chiếc xe buýt"],answer:1,emoji:"🚌"},{id:"th5-thong-tin-giai-quyet-van-de-18",type:"order",q:"Sắp xếp các bước Nam chọn sách để đọc trong hè.",explain:"Xác định nhu cầu, thu thập, sắp xếp rồi mới chọn.",items:["Xác định muốn đọc về chủ đề gì","Tìm danh sách sách ở thư viện","Ghi tên sách, số trang vào bảng","Chọn cuốn phù hợp nhất"]}]},{questions:[{id:"th5-thong-tin-giai-quyet-van-de-19",type:"mc",q:"Vườn thú cách trường 5 ki-lô-mét, vé 20 nghìn đồng. Bảo tàng cách 3 ki-lô-mét, vé 10 nghìn đồng. Công viên nước cách 15 ki-lô-mét, vé 80 nghìn đồng. Nơi nào vừa gần nhất vừa rẻ nhất?",explain:"Bảo tàng gần nhất với 3 ki-lô-mét và rẻ nhất với 10 nghìn đồng.",options:["Công viên nước","Vườn thú","Bảo tàng"],answer:2,emoji:"🏛️"},{id:"th5-thong-tin-giai-quyet-van-de-20",type:"number",q:"Lớp có 30 bạn, mỗi vé tham quan giá 10 nghìn đồng. Lớp cần bao nhiêu nghìn đồng tiền vé?",explain:"Ba mươi nhân mười bằng ba trăm, lớp cần 300 nghìn đồng.",answer:300,unit:"nghìn đồng"},{id:"th5-thong-tin-giai-quyet-van-de-21",type:"tf",q:"Dự báo ngày đi tham quan có mưa to. Lớp nên chọn nơi tham quan trong nhà như bảo tàng.",explain:"Đúng. Thông tin thời tiết giúp chọn nơi đi phù hợp.",answer:!0,emoji:"🌧️"},{id:"th5-thong-tin-giai-quyet-van-de-22",type:"multi",q:"Chi lập kế hoạch học bơi trong hè. Chi cần thu thập thông tin gì?",explain:"Địa chỉ, giờ mở cửa và học phí giúp Chi lập kế hoạch. Màu tóc người bán vé không liên quan.",options:["Địa chỉ bể bơi","Giờ mở cửa bể bơi","Học phí lớp bơi","Màu tóc người bán vé"],answers:[0,1,2],emoji:"🏊"},{id:"th5-thong-tin-giai-quyet-van-de-23",type:"mc",q:"Phúc có 20 nghìn đồng. Bút xanh giá 25 nghìn, bút đỏ giá 15 nghìn, bút tím giá 30 nghìn. Phúc mua được bút nào?",explain:"Chỉ bút đỏ giá 15 nghìn là không quá 20 nghìn đồng.",options:["Bút đỏ","Bút tím","Bút xanh"],answer:0,emoji:"🖊️"},{id:"th5-thong-tin-giai-quyet-van-de-24",type:"tf",q:"Khoa chỉ đọc một bình luận lạ trên mạng rồi chọn ngay nơi đi chơi cho cả nhà. Khoa làm như vậy là hợp lí.",explain:"Sai. Khoa nên thu thập thông tin từ nguồn tin cậy và so sánh trước khi chọn.",answer:!1},{id:"th5-thong-tin-giai-quyet-van-de-25",type:"order",q:"Lớp em chọn nơi đi dã ngoại. Sắp xếp các việc cần làm.",explain:"Liệt kê lựa chọn, thu thập thông tin, sắp xếp vào bảng rồi quyết định.",items:["Liệt kê các nơi có thể đi","Tìm khoảng cách, giá vé mỗi nơi","Ghi thông tin vào bảng so sánh","Bình chọn nơi phù hợp nhất"]},{id:"th5-thong-tin-giai-quyet-van-de-26",type:"match",q:"Ghép bước với việc làm khi chuẩn bị đi dã ngoại.",explain:"Mỗi bước có một việc làm cụ thể.",pairs:[["Xác định thông tin cần có","Cần biết nơi đến, giờ đi, chi phí"],["Thu thập","Hỏi cô giáo, xem website chính thức"],["Sắp xếp","Kẻ bảng so sánh các nơi"],["Quyết định","Chọn nơi gần, an toàn, vừa tiền"]]},{id:"th5-thong-tin-giai-quyet-van-de-27",type:"mc",q:"Dự báo thời tiết cuối tuần: thứ Bảy mưa to, Chủ nhật nắng nhẹ. Nhóm em nên đi công viên ngày nào?",explain:"Chủ nhật nắng nhẹ, thuận lợi hơn để đi công viên.",options:["Thứ Bảy","Chủ nhật","Ngày nào cũng như nhau"],answer:1,emoji:"⛅"}]}],challenge:{questions:[{id:"th5-thong-tin-giai-quyet-van-de-28",type:"number",q:"Nhóm có 6 bạn, mỗi bạn góp 15 nghìn đồng để mua quả bóng. Nhóm góp được tất cả bao nhiêu nghìn đồng?",explain:"Sáu nhân mười lăm bằng chín mươi, nhóm có 90 nghìn đồng.",answer:90,unit:"nghìn đồng"},{id:"th5-thong-tin-giai-quyet-van-de-29",type:"mc",q:"Vườn hoa cách 2 ki-lô-mét, không có mái che. Nhà văn hoá cách 4 ki-lô-mét, có mái che. Dự báo hôm đó mưa. Nhóm nên chọn nơi nào?",explain:"Trời mưa nên chọn nơi có mái che, dù xa hơn một chút.",options:["Không cần xét gì","Vườn hoa","Nhà văn hoá"],answer:2,emoji:"☔"},{id:"th5-thong-tin-giai-quyet-van-de-30",type:"multi",q:"Những việc nào giúp em ra quyết định tốt hơn?",explain:"Thông tin tin cậy, được chọn lọc và sắp xếp giúp quyết định đúng hơn.",options:["Lấy thông tin từ nguồn tin cậy","Bỏ thông tin không liên quan","Chọn ngay thứ đầu tiên nhìn thấy","Sắp xếp thông tin để so sánh"],answers:[0,1,3]},{id:"th5-thong-tin-giai-quyet-van-de-19",type:"mc",q:"Vườn thú cách trường 5 ki-lô-mét, vé 20 nghìn đồng. Bảo tàng cách 3 ki-lô-mét, vé 10 nghìn đồng. Công viên nước cách 15 ki-lô-mét, vé 80 nghìn đồng. Nơi nào vừa gần nhất vừa rẻ nhất?",explain:"Bảo tàng gần nhất với 3 ki-lô-mét và rẻ nhất với 10 nghìn đồng.",options:["Công viên nước","Vườn thú","Bảo tàng"],answer:2,emoji:"🏛️"},{id:"th5-thong-tin-giai-quyet-van-de-23",type:"mc",q:"Phúc có 20 nghìn đồng. Bút xanh giá 25 nghìn, bút đỏ giá 15 nghìn, bút tím giá 30 nghìn. Phúc mua được bút nào?",explain:"Chỉ bút đỏ giá 15 nghìn là không quá 20 nghìn đồng.",options:["Bút đỏ","Bút tím","Bút xanh"],answer:0,emoji:"🖊️"},{id:"th5-thong-tin-giai-quyet-van-de-25",type:"order",q:"Lớp em chọn nơi đi dã ngoại. Sắp xếp các việc cần làm.",explain:"Liệt kê lựa chọn, thu thập thông tin, sắp xếp vào bảng rồi quyết định.",items:["Liệt kê các nơi có thể đi","Tìm khoảng cách, giá vé mỗi nơi","Ghi thông tin vào bảng so sánh","Bình chọn nơi phù hợp nhất"]},{id:"th5-thong-tin-giai-quyet-van-de-27",type:"mc",q:"Dự báo thời tiết cuối tuần: thứ Bảy mưa to, Chủ nhật nắng nhẹ. Nhóm em nên đi công viên ngày nào?",explain:"Chủ nhật nắng nhẹ, thuận lợi hơn để đi công viên.",options:["Thứ Bảy","Chủ nhật","Ngày nào cũng như nhau"],answer:1,emoji:"⛅"}]},summary:["Muốn giải quyết vấn đề, em xác định thông tin cần có, thu thập từ nguồn tin cậy, chọn lọc và sắp xếp.","Thông tin được sắp xếp, ví dụ thành bảng, giúp em so sánh và quyết định đúng."]},{id:"th5-sao-chep-di-chuyen-tep",title:"Bài 6: Sao chép và di chuyển tệp, thư mục",weeks:[10,11],learn:[{title:"Sao chép và di chuyển",text:"Sao chép tạo thêm một bản giống hệt ở chỗ mới, bản gốc vẫn còn. Di chuyển đưa tệp sang chỗ mới, chỗ cũ không còn tệp đó nữa.",example:"📄 → 📄📄 sao chép  ·  📄 → ➡️📄 di chuyển"},{title:"Lệnh Copy, Cut và Paste",text:"Chọn tệp hoặc thư mục, dùng lệnh Copy để sao chép hoặc Cut để cắt. Sau đó mở thư mục đích và dùng lệnh Paste để dán.",example:"🖱️ chuột phải → Copy / Cut → Paste"},{title:"Phím tắt",text:"Nhấn Ctrl + C để sao chép, Ctrl + X để cắt, Ctrl + V để dán.",example:"⌨️ Ctrl + C · Ctrl + X · Ctrl + V"},{title:"Kéo thả và tên trùng nhau",text:"Em cũng có thể giữ chuột vào tệp rồi kéo thả sang thư mục khác. Trong một thư mục, hai tệp không được trùng tên hoàn toàn, nên khi chép tệp vào thư mục đã có tệp cùng tên, máy tính sẽ hỏi em muốn làm gì.",example:"🖱️ giữ → kéo → thả"}],practice:[{questions:[{id:"th5-sao-chep-di-chuyen-tep-01",type:"mc",q:"Sau khi sao chép một tệp sang thư mục khác, tệp gốc thế nào?",explain:"Sao chép tạo thêm bản mới, bản gốc vẫn ở chỗ cũ.",options:["Vẫn còn ở chỗ cũ","Đổi thành thư mục","Bị xoá mất"],answer:0,emoji:"📄"},{id:"th5-sao-chep-di-chuyen-tep-02",type:"mc",q:"Tổ hợp phím nào dùng để dán?",explain:"Ctrl + V là dán, Ctrl + C là sao chép, Ctrl + X là cắt.",options:["Ctrl + X","Ctrl + V","Ctrl + C"],answer:1,emoji:"⌨️"},{id:"th5-sao-chep-di-chuyen-tep-03",type:"tf",q:"Di chuyển một tệp thì tệp không còn ở chỗ cũ nữa.",explain:"Đúng. Di chuyển đưa tệp sang chỗ mới.",answer:!0},{id:"th5-sao-chep-di-chuyen-tep-04",type:"tf",q:"Dùng lệnh Cut rồi Paste thì tệp gốc vẫn còn ở chỗ cũ.",explain:"Sai. Cut rồi Paste là di chuyển, chỗ cũ không còn tệp.",answer:!1},{id:"th5-sao-chep-di-chuyen-tep-05",type:"match",q:"Ghép tổ hợp phím với công dụng.",explain:"C là sao chép, X là cắt, V là dán.",pairs:[["Ctrl + C","Sao chép"],["Ctrl + X","Cắt"],["Ctrl + V","Dán"]]},{id:"th5-sao-chep-di-chuyen-tep-06",type:"fill",q:"Điền từ còn thiếu: Lệnh Paste dùng để … tệp vào thư mục mới.",explain:"Paste nghĩa là dán.",answer:["dán"]},{id:"th5-sao-chep-di-chuyen-tep-07",type:"multi",q:"Những cách nào dùng để sao chép hoặc di chuyển tệp?",explain:"Lệnh, phím tắt và kéo thả đều dùng được. Nút nguồn để bật tắt máy.",options:["Dùng lệnh Copy, Cut, Paste","Nhấn nút nguồn của máy","Dùng phím tắt Ctrl + C, Ctrl + X, Ctrl + V","Kéo thả bằng chuột"],answers:[0,2,3]},{id:"th5-sao-chep-di-chuyen-tep-08",type:"mc",q:"Muốn có thêm một bản giống hệt tệp ở thư mục khác, em dùng thao tác nào?",explain:"Sao chép tạo thêm một bản giống hệt.",options:["Xoá tệp","Di chuyển","Sao chép"],answer:2},{id:"th5-sao-chep-di-chuyen-tep-09",type:"tf",q:"Em có thể sao chép cả một thư mục cùng các tệp bên trong nó.",explain:"Đúng. Sao chép thư mục thì các tệp bên trong cũng được chép theo.",answer:!0,emoji:"📁"}]},{questions:[{id:"th5-sao-chep-di-chuyen-tep-10",type:"mc",q:"Điểm khác nhau giữa sao chép và di chuyển là gì?",explain:"Sao chép giữ lại bản gốc, di chuyển thì chỗ cũ không còn tệp.",options:["Sao chép còn bản gốc, di chuyển thì không","Di chuyển còn bản gốc, sao chép thì không","Cả hai đều xoá mất bản gốc"],answer:0},{id:"th5-sao-chep-di-chuyen-tep-11",type:"order",q:"Sắp xếp các bước sao chép tệp bằng phím tắt.",explain:"Chọn tệp, nhấn Ctrl + C, mở thư mục đích rồi nhấn Ctrl + V.",items:["Chọn tệp cần sao chép","Nhấn Ctrl + C","Mở thư mục cần đưa tệp tới","Nhấn Ctrl + V"]},{id:"th5-sao-chep-di-chuyen-tep-12",type:"tf",q:"Sau khi nhấn Ctrl + X rồi nhấn Ctrl + V ở thư mục mới, tệp chỉ còn ở thư mục mới.",explain:"Đúng. Cắt rồi dán là di chuyển tệp.",answer:!0},{id:"th5-sao-chep-di-chuyen-tep-13",type:"mc",q:"Em chép một tệp vào thư mục đã có tệp cùng tên. Máy tính thường làm gì?",explain:"Hai tệp trong một thư mục không được trùng tên, nên máy hỏi em muốn làm gì.",options:["Xoá hết cả thư mục đó đi","Hỏi em có thay thế tệp cũ không","Tự tắt máy tính ngay lập tức"],answer:1},{id:"th5-sao-chep-di-chuyen-tep-14",type:"tf",q:"Trong cùng một thư mục, có thể có hai tệp trùng tên hoàn toàn.",explain:"Sai. Trong một thư mục, mỗi tệp phải có tên riêng.",answer:!1},{id:"th5-sao-chep-di-chuyen-tep-15",type:"multi",q:"Sau khi di chuyển thư mục Toán vào thư mục Học tập, điều nào đúng?",explain:"Di chuyển thư mục thì cả thư mục và tệp bên trong sang chỗ mới, chỗ cũ không còn.",options:["Thư mục Toán nằm trong Học tập","Thư mục Toán vẫn còn ở chỗ cũ","Các tệp trong Toán cũng đi theo","Các tệp trong Toán bị xoá hết"],answers:[0,2],emoji:"📁"},{id:"th5-sao-chep-di-chuyen-tep-16",type:"mc",q:"Kéo thả tệp nghĩa là gì?",explain:"Kéo thả là giữ chuột vào tệp, kéo tới chỗ mới rồi thả ra.",options:["Nhấn phím Delete để xoá tệp","Nháy đúp chuột để mở tệp ra","Giữ chuột vào tệp, kéo tới chỗ mới"],answer:2,emoji:"🖱️"},{id:"th5-sao-chep-di-chuyen-tep-17",type:"tf",q:"Sau khi nhấn Ctrl + C hay Ctrl + X, em cần nhấn Ctrl + V ở chỗ mới để dán tệp.",explain:"Đúng. Phải dán thì tệp mới xuất hiện ở chỗ mới.",answer:!0},{id:"th5-sao-chep-di-chuyen-tep-18",type:"match",q:"Ghép thao tác với kết quả.",explain:"Copy hay Cut chỉ chuẩn bị, Paste mới đưa tệp tới chỗ mới.",pairs:[["Copy rồi Paste","Có hai bản, bản gốc vẫn còn"],["Cut rồi Paste","Tệp chuyển sang chỗ mới"],["Chỉ Copy, chưa Paste","Chưa có gì thay đổi"]]}]},{questions:[{id:"th5-sao-chep-di-chuyen-tep-19",type:"mc",q:"Lan muốn gửi bản bài vẽ vào thư mục Nhóm nhưng vẫn giữ bài trong thư mục của mình. Lan dùng thao tác nào?",explain:"Sao chép giúp có bài ở thư mục Nhóm mà bản gốc vẫn còn.",options:["Sao chép","Đổi tên","Di chuyển"],answer:0,emoji:"🎨"},{id:"th5-sao-chep-di-chuyen-tep-20",type:"mc",q:"Minh để nhầm tệp bài hát vào thư mục Toán, muốn chuyển nó sang thư mục Âm nhạc. Minh nhấn tổ hợp phím nào trước?",explain:"Muốn chuyển chỗ thì cắt bằng Ctrl + X, rồi dán bằng Ctrl + V ở thư mục Âm nhạc.",options:["Ctrl + C","Ctrl + X","Ctrl + V"],answer:1,emoji:"🎵"},{id:"th5-sao-chep-di-chuyen-tep-21",type:"tf",q:"Bình sao chép tệp sang ổ USB rồi xoá tệp trên máy. Tệp trên ổ USB vẫn còn.",explain:"Đúng. Bản sao trên ổ USB là một tệp riêng, xoá bản trên máy không ảnh hưởng.",answer:!0},{id:"th5-sao-chep-di-chuyen-tep-22",type:"order",q:"Sắp xếp các bước di chuyển tệp bằng chuột phải.",explain:"Cắt tệp ở chỗ cũ, mở thư mục đích rồi dán.",items:["Nháy chuột phải vào tệp","Chọn lệnh Cut","Mở thư mục đích","Nháy chuột phải vào chỗ trống, chọn Paste"]},{id:"th5-sao-chep-di-chuyen-tep-23",type:"multi",q:"Hà muốn đưa các ảnh lẫn lộn trên màn hình nền vào thư mục Ảnh lớp 5. Hà có thể làm gì?",explain:"Kéo thả, phím tắt hay lệnh Cut, Paste đều đưa ảnh vào thư mục được.",options:["Kéo thả ảnh vào thư mục","Dùng Ctrl + X rồi Ctrl + V","Xoá thư mục Ảnh lớp 5","Dùng lệnh Cut rồi Paste"],answers:[0,1,3],emoji:"🖼️"},{id:"th5-sao-chep-di-chuyen-tep-24",type:"tf",q:"Chi nhấn Ctrl + C vào tệp rồi tắt máy luôn. Tệp đã được sao chép sang thư mục mới.",explain:"Sai. Chi chưa mở thư mục mới và nhấn Ctrl + V nên chưa có bản sao nào.",answer:!1},{id:"th5-sao-chep-di-chuyen-tep-25",type:"mc",q:"Nam có hai tệp cùng tên “Bài văn” ở hai thư mục, muốn chép cả hai vào một thư mục và giữ cả hai. Nam nên làm gì?",explain:"Một thư mục không chứa hai tệp trùng tên, nên Nam đổi tên một tệp trước.",options:["Xoá cả hai tệp rồi làm lại","Chép đè tệp này lên tệp kia","Đổi tên một tệp trước khi chép"],answer:2},{id:"th5-sao-chep-di-chuyen-tep-26",type:"number",q:"Thư mục A có 4 tệp. Em sao chép 3 tệp khác tên từ thư mục B sang thư mục A. Thư mục A có bao nhiêu tệp?",explain:"Bốn cộng ba bằng bảy, thư mục A có 7 tệp.",answer:7,unit:"tệp"},{id:"th5-sao-chep-di-chuyen-tep-27",type:"number",q:"Thư mục B có 5 tệp. Em di chuyển 2 tệp sang thư mục khác. Thư mục B còn bao nhiêu tệp?",explain:"Di chuyển thì tệp rời khỏi chỗ cũ, năm trừ hai bằng ba.",answer:3,unit:"tệp"}]}],challenge:{questions:[{id:"th5-sao-chep-di-chuyen-tep-28",type:"number",q:"Thư mục Ảnh có 6 tệp. Em sao chép 2 tệp sang thư mục Bạn bè. Thư mục Ảnh còn bao nhiêu tệp?",explain:"Sao chép không lấy mất bản gốc, thư mục Ảnh vẫn có 6 tệp.",answer:6,unit:"tệp"},{id:"th5-sao-chep-di-chuyen-tep-29",type:"mc",q:"Tùng chọn tệp, nhấn Ctrl + X, mở thư mục mới rồi nhấn Ctrl + V. Tùng vừa làm gì?",explain:"Cắt rồi dán là di chuyển tệp sang thư mục mới.",options:["Di chuyển tệp","Xoá tệp","Sao chép tệp"],answer:0},{id:"th5-sao-chep-di-chuyen-tep-30",type:"tf",q:"Sao chép tệp quan trọng sang chỗ khác giúp có bản dự phòng nếu bản gốc bị xoá nhầm.",explain:"Đúng. Bản sao vẫn còn khi bản gốc bị mất.",answer:!0},{id:"th5-sao-chep-di-chuyen-tep-20",type:"mc",q:"Minh để nhầm tệp bài hát vào thư mục Toán, muốn chuyển nó sang thư mục Âm nhạc. Minh nhấn tổ hợp phím nào trước?",explain:"Muốn chuyển chỗ thì cắt bằng Ctrl + X, rồi dán bằng Ctrl + V ở thư mục Âm nhạc.",options:["Ctrl + C","Ctrl + X","Ctrl + V"],answer:1,emoji:"🎵"},{id:"th5-sao-chep-di-chuyen-tep-24",type:"tf",q:"Chi nhấn Ctrl + C vào tệp rồi tắt máy luôn. Tệp đã được sao chép sang thư mục mới.",explain:"Sai. Chi chưa mở thư mục mới và nhấn Ctrl + V nên chưa có bản sao nào.",answer:!1},{id:"th5-sao-chep-di-chuyen-tep-25",type:"mc",q:"Nam có hai tệp cùng tên “Bài văn” ở hai thư mục, muốn chép cả hai vào một thư mục và giữ cả hai. Nam nên làm gì?",explain:"Một thư mục không chứa hai tệp trùng tên, nên Nam đổi tên một tệp trước.",options:["Xoá cả hai tệp rồi làm lại","Chép đè tệp này lên tệp kia","Đổi tên một tệp trước khi chép"],answer:2},{id:"th5-sao-chep-di-chuyen-tep-27",type:"number",q:"Thư mục B có 5 tệp. Em di chuyển 2 tệp sang thư mục khác. Thư mục B còn bao nhiêu tệp?",explain:"Di chuyển thì tệp rời khỏi chỗ cũ, năm trừ hai bằng ba.",answer:3,unit:"tệp"}]},summary:["Sao chép tạo thêm một bản và giữ bản gốc; di chuyển đưa tệp sang chỗ mới, chỗ cũ không còn.","Dùng Copy hoặc Ctrl + C để sao chép, Cut hoặc Ctrl + X để cắt, Paste hoặc Ctrl + V để dán; cũng có thể kéo thả bằng chuột."]},{id:"th5-thu-dien-tu",title:"Bài 7: Thư điện tử",weeks:[12,13],learn:[{title:"Thư điện tử là gì?",text:"Thư điện tử là thư gửi qua Internet, đến nơi rất nhanh. Mỗi hộp thư có một địa chỉ riêng, gồm tên hộp thư, kí hiệu a còng và tên miền.",example:"📧 tenhopthu@tenmien.vn"},{title:"Các phần của bức thư",text:"Bức thư có người nhận, tiêu đề, nội dung và có thể có tệp đính kèm. Tiêu đề ngắn gọn cho biết thư nói về việc gì.",example:"👤 Người nhận · 📝 Tiêu đề · ✉️ Nội dung · 📎 Đính kèm"},{title:"Trả lời và chuyển tiếp",text:"Trả lời là viết thư đáp lại người đã gửi. Chuyển tiếp là gửi tiếp bức thư em nhận được cho người khác.",example:"↩️ Trả lời · ↪️ Chuyển tiếp"},{title:"Dùng thư an toàn, lịch sự",text:"Giữ bí mật mật khẩu, đăng xuất khi dùng máy chung. Không mở tệp hay liên kết trong thư lạ. Viết thư có lời chào, lời cảm ơn, gặp thư lạ thì hỏi người lớn.",example:"🔒 mật khẩu · ⚠️ thư lạ · 🙏 lịch sự"}],practice:[{questions:[{id:"th5-thu-dien-tu-01",type:"mc",q:"Kí hiệu nào luôn có trong địa chỉ thư điện tử?",explain:"Địa chỉ thư điện tử luôn có kí hiệu a còng.",options:["Kí hiệu # (dấu thăng)","Kí hiệu @ (a còng)","Kí hiệu % (phần trăm)"],answer:1,emoji:"📧"},{id:"th5-thu-dien-tu-02",type:"mc",q:"Trong địa chỉ thư điện tử, phần đứng trước kí hiệu a còng là gì?",explain:"Đứng trước a còng là tên hộp thư, đứng sau là tên miền.",options:["Tên miền","Mật khẩu","Tên hộp thư"],answer:2},{id:"th5-thu-dien-tu-03",type:"mc",q:"Phần nào của bức thư cho biết ngắn gọn thư nói về việc gì?",explain:"Tiêu đề là tên ngắn gọn cho biết nội dung thư.",options:["Tiêu đề","Tệp đính kèm","Người nhận"],answer:0,emoji:"📝"},{id:"th5-thu-dien-tu-04",type:"tf",q:"Em nên cho bạn thân biết mật khẩu hộp thư của mình.",explain:"Sai. Mật khẩu phải giữ bí mật, chỉ cha mẹ có thể cùng giữ giúp em.",answer:!1,emoji:"🔒"},{id:"th5-thu-dien-tu-05",type:"match",q:"Ghép phần của bức thư với điều ghi vào.",explain:"Mỗi phần của bức thư có một việc riêng.",pairs:[["Người nhận","Địa chỉ thư của người được gửi"],["Tiêu đề","Tên ngắn gọn của bức thư"],["Nội dung","Lời em muốn viết"],["Tệp đính kèm","Ảnh hoặc tệp gửi kèm"]]},{id:"th5-thu-dien-tu-06",type:"fill",q:"Điền từ còn thiếu: Kí hiệu luôn có trong mọi địa chỉ thư điện tử thường được đọc là a … .",explain:"Kí hiệu @ thường được đọc là a còng.",answer:["còng"]},{id:"th5-thu-dien-tu-07",type:"multi",q:"Thư điện tử có những ưu điểm nào?",explain:"Thư điện tử nhanh, gửi kèm được tệp và gửi được cho nhiều người. Thư điện tử không cần tem.",options:["Đến nơi rất nhanh","Gửi kèm được ảnh và tệp","Phải dán tem mới gửi được","Gửi cho nhiều người cùng lúc"],answers:[0,1,3]},{id:"th5-thu-dien-tu-08",type:"mc",q:"Địa chỉ nào viết đúng dạng địa chỉ thư điện tử?",explain:"Địa chỉ thư điện tử có tên hộp thư, kí hiệu a còng rồi tới tên miền, không có dấu cách.",options:["an.nguyen#thuhoc.vn","an.nguyen@thuhoc.vn","an nguyen thuhoc vn"],answer:1},{id:"th5-thu-dien-tu-09",type:"tf",q:"Gặp thư lạ có tệp đính kèm, em nên mở ngay để xem.",explain:"Sai. Tệp trong thư lạ có thể chứa phần mềm độc hại, em nên hỏi người lớn.",answer:!1,emoji:"⚠️"}]},{questions:[{id:"th5-thu-dien-tu-10",type:"mc",q:"Nút Trả lời dùng để làm gì?",explain:"Trả lời là viết thư đáp lại người đã gửi cho em.",options:["Xoá bức thư khỏi hộp thư","Gửi tiếp thư cho người khác","Viết thư đáp lại người gửi"],answer:2,emoji:"↩️"},{id:"th5-thu-dien-tu-11",type:"mc",q:"Chuyển tiếp thư là gì?",explain:"Chuyển tiếp là gửi tiếp bức thư em nhận được cho người khác.",options:["Gửi thư đã nhận cho người khác","Viết thư đáp lại người gửi","Đánh dấu thư là đã đọc"],answer:0,emoji:"↪️"},{id:"th5-thu-dien-tu-12",type:"tf",q:"Mỗi bức thư điện tử chỉ gửi được cho đúng một người.",explain:"Sai. Một bức thư có thể gửi cho nhiều người cùng lúc.",answer:!1},{id:"th5-thu-dien-tu-13",type:"order",q:"Sắp xếp các bước gửi một thư điện tử.",explain:"Soạn thư mới, nhập người nhận, viết tiêu đề và nội dung rồi gửi.",items:["Nháy nút soạn thư mới","Nhập địa chỉ người nhận","Gõ tiêu đề và nội dung","Nháy nút Gửi"]},{id:"th5-thu-dien-tu-14",type:"multi",q:"Những việc nào giúp dùng thư điện tử an toàn?",explain:"Giữ mật khẩu, tránh liên kết lạ và đăng xuất giúp an toàn. Không bao giờ gửi mật khẩu cho người lạ.",options:["Giữ bí mật mật khẩu","Không mở liên kết trong thư lạ","Gửi mật khẩu cho người lạ hỏi","Đăng xuất khi dùng máy chung"],answers:[0,1,3]},{id:"th5-thu-dien-tu-15",type:"tf",q:"Thư điện tử không cần lời chào, cứ viết thật cộc lốc là lịch sự.",explain:"Sai. Thư lịch sự cần có lời chào, nội dung rõ ràng và lời cảm ơn.",answer:!1},{id:"th5-thu-dien-tu-16",type:"mc",q:"Vì sao nên viết tiêu đề thư rõ ràng?",explain:"Đọc tiêu đề, người nhận biết ngay thư nói về việc gì.",options:["Để thư có nhiều màu","Để người nhận biết nội dung","Để thư đến nơi nhanh hơn"],answer:1},{id:"th5-thu-dien-tu-17",type:"tf",q:"Địa chỉ thư điện tử của mỗi hộp thư là duy nhất, không trùng với hộp thư khác.",explain:"Đúng. Nhờ vậy thư gửi đến đúng hộp thư.",answer:!0},{id:"th5-thu-dien-tu-18",type:"mc",q:"Biểu tượng cái kẹp giấy trong thư điện tử thường cho biết điều gì?",explain:"Kẹp giấy là biểu tượng của tệp đính kèm.",options:["Thư đã bị xoá đi","Thư chưa có tiêu đề","Thư có tệp đính kèm"],answer:2,emoji:"📎"}]},{questions:[{id:"th5-thu-dien-tu-19",type:"mc",q:"Cô giáo gửi thư dặn nộp bài. Khoa muốn báo cô là đã nhận được thư. Khoa dùng nút nào?",explain:"Trả lời giúp Khoa viết thư đáp lại cô giáo.",options:["Trả lời","Xoá","Chuyển tiếp"],answer:0},{id:"th5-thu-dien-tu-20",type:"mc",q:"Ngọc nhận thư mời của câu lạc bộ, muốn gửi cho Thảo cùng đọc. Ngọc dùng nút nào?",explain:"Chuyển tiếp giúp gửi bức thư đã nhận cho Thảo.",options:["Trả lời","Chuyển tiếp","Xoá"],answer:1},{id:"th5-thu-dien-tu-21",type:"tf",q:"Vy nhận thư từ địa chỉ lạ báo trúng thưởng, kèm một liên kết. Vy nên hỏi người lớn và không nháy vào liên kết.",explain:"Đúng. Thư báo trúng thưởng từ người lạ thường là lừa đảo.",answer:!0,emoji:"🎁"},{id:"th5-thu-dien-tu-22",type:"mc",q:"Dũng muốn gửi bài trình chiếu cho cô giáo qua thư. Dũng cần làm gì thêm?",explain:"Muốn gửi tệp thì Dũng đính kèm tệp vào thư.",options:["Để trống ô người nhận thư","Viết thư thật dài, nhiều trang","Đính kèm tệp bài trình chiếu"],answer:2,emoji:"📎"},{id:"th5-thu-dien-tu-23",type:"multi",q:"Tùng viết thư hỏi bài cô giáo. Thư lịch sự cần có gì?",explain:"Thư lịch sự có lời chào, nội dung rõ ràng, lời cảm ơn. Viết toàn chữ in hoa giống như đang quát.",options:["Lời chào cô","Nội dung rõ ràng","Lời cảm ơn","Chữ viết toàn in hoa"],answers:[0,1,2]},{id:"th5-thu-dien-tu-24",type:"tf",q:"Phúc dùng máy tính ở thư viện để đọc thư. Xong việc, Phúc không cần đăng xuất.",explain:"Sai. Không đăng xuất thì người dùng sau có thể đọc thư của Phúc.",answer:!1},{id:"th5-thu-dien-tu-25",type:"match",q:"Ghép tình huống với việc nên làm.",explain:"Mỗi tình huống có cách dùng thư điện tử phù hợp.",pairs:[["Bạn gửi thư hỏi bài","Trả lời thư"],["Muốn gửi ảnh cho bà","Đính kèm ảnh"],["Thư lạ đòi mật khẩu","Không trả lời, báo người lớn"],["Muốn bạn khác đọc thư mời","Chuyển tiếp thư"]]},{id:"th5-thu-dien-tu-26",type:"tf",q:"Hà gửi một thư cho ba bạn cùng lúc bằng cách nhập địa chỉ của cả ba bạn vào ô người nhận.",explain:"Đúng. Ô người nhận có thể chứa nhiều địa chỉ.",answer:!0},{id:"th5-thu-dien-tu-27",type:"mc",q:"Bình gõ sai một chữ trong địa chỉ người nhận. Điều gì có thể xảy ra?",explain:"Mỗi địa chỉ là duy nhất, sai một chữ thì thư không đến đúng người cần gửi.",options:["Thư không đến được người nhận","Máy tự sửa lại cho đúng","Thư vẫn đến đúng người nhận"],answer:0}]}],challenge:{questions:[{id:"th5-thu-dien-tu-28",type:"multi",q:"Gặp những thư nào em không nên mở tệp đính kèm?",explain:"Thư lạ báo thưởng, đòi mật khẩu hay có tệp kì quặc đều đáng ngờ. Thư cô giáo đã hẹn là thư quen.",options:["Thư lạ báo trúng thưởng lớn","Thư lạ hối thúc nhập mật khẩu","Thư lạ có tệp tên kì quặc","Thư cô giáo gửi bài tập đã hẹn trước"],answers:[0,1,2]},{id:"th5-thu-dien-tu-29",type:"mc",q:"So với thư giấy, điểm khác biệt lớn của thư điện tử là gì?",explain:"Thư điện tử gửi qua Internet nên đến nơi rất nhanh, không cần tem.",options:["Phải mang thư ra bưu điện","Gửi qua Internet, đến nhanh","Phải dán tem lên phong bì"],answer:1},{id:"th5-thu-dien-tu-30",type:"tf",q:"Khi em chuyển tiếp một bức thư, người nhận mới sẽ đọc được nội dung thư đó.",explain:"Đúng. Vì vậy em cần nghĩ kĩ trước khi chuyển tiếp thư.",answer:!0},{id:"th5-thu-dien-tu-21",type:"tf",q:"Vy nhận thư từ địa chỉ lạ báo trúng thưởng, kèm một liên kết. Vy nên hỏi người lớn và không nháy vào liên kết.",explain:"Đúng. Thư báo trúng thưởng từ người lạ thường là lừa đảo.",answer:!0,emoji:"🎁"},{id:"th5-thu-dien-tu-22",type:"mc",q:"Dũng muốn gửi bài trình chiếu cho cô giáo qua thư. Dũng cần làm gì thêm?",explain:"Muốn gửi tệp thì Dũng đính kèm tệp vào thư.",options:["Để trống ô người nhận thư","Viết thư thật dài, nhiều trang","Đính kèm tệp bài trình chiếu"],answer:2,emoji:"📎"},{id:"th5-thu-dien-tu-25",type:"match",q:"Ghép tình huống với việc nên làm.",explain:"Mỗi tình huống có cách dùng thư điện tử phù hợp.",pairs:[["Bạn gửi thư hỏi bài","Trả lời thư"],["Muốn gửi ảnh cho bà","Đính kèm ảnh"],["Thư lạ đòi mật khẩu","Không trả lời, báo người lớn"],["Muốn bạn khác đọc thư mời","Chuyển tiếp thư"]]},{id:"th5-thu-dien-tu-27",type:"mc",q:"Bình gõ sai một chữ trong địa chỉ người nhận. Điều gì có thể xảy ra?",explain:"Mỗi địa chỉ là duy nhất, sai một chữ thì thư không đến đúng người cần gửi.",options:["Thư không đến được người nhận","Máy tự sửa lại cho đúng","Thư vẫn đến đúng người nhận"],answer:0}]},summary:["Thư điện tử gửi qua Internet; địa chỉ thư gồm tên hộp thư, kí hiệu a còng và tên miền.","Bức thư có người nhận, tiêu đề, nội dung, tệp đính kèm; em có thể gửi, trả lời và chuyển tiếp thư.","Giữ bí mật mật khẩu, không mở thư lạ, viết thư lịch sự và hỏi người lớn khi cần."]}]},{id:"dao-duc-phap-luat-moi-truong-so",title:"Đạo đức, pháp luật và văn hoá trong môi trường số",lessons:[{id:"th5-ban-quyen-noi-dung",title:"Bài 8: Tôn trọng bản quyền nội dung số",weeks:[14,15],learn:[{title:"Nội dung số đều có tác giả",text:"Ảnh, bài hát, video, truyện, bài viết trên mạng đều do ai đó làm ra. Người làm ra là tác giả và có bản quyền với sản phẩm đó.",example:"📷 🎵 🎬 📖 → © tác giả"},{title:"Xin phép và ghi nguồn",text:"Khi dùng sản phẩm của người khác cho bài học, em xem có được phép dùng không, xin phép khi cần và ghi rõ tên tác giả hoặc nơi lấy nội dung.",example:"📝 Ảnh: Trần Minh · Nguồn: trang web Chim Việt"},{title:"Không nhận là của mình",text:"Chép bài của người khác rồi ghi tên mình là không trung thực. Không chia sẻ trái phép phim, sách, bài hát phải trả tiền.",example:"🚫 đổi tên tác giả · 🚫 chia sẻ trái phép"},{title:"Sản phẩm của em cũng có bản quyền",text:"Bức tranh, bài văn, video em tự làm cũng có bản quyền. Người khác muốn dùng cũng cần hỏi ý em.",example:"🎨 Tác giả: chính em"}],practice:[{questions:[{id:"th5-ban-quyen-noi-dung-01",type:"tf",q:"Bức ảnh, bài hát, video đăng trên mạng đều có tác giả.",emoji:"📷",explain:"Đúng. Mỗi nội dung số đều do một người hoặc một nhóm người làm ra.",answer:!0},{id:"th5-ban-quyen-noi-dung-02",type:"mc",q:"Người làm ra một bức ảnh, một bài hát được gọi là gì?",emoji:"🎵",explain:"Người làm ra sản phẩm là tác giả của sản phẩm đó.",options:["Người xem","Tác giả","Người tải về","Người chia sẻ"],answer:1},{id:"th5-ban-quyen-noi-dung-03",type:"tf",q:"Ảnh tìm thấy trên mạng thì ai cũng được dùng tự do cho mọi việc.",explain:"Sai. Ảnh trên mạng vẫn có tác giả, em cần xem có được phép dùng không.",answer:!1},{id:"th5-ban-quyen-noi-dung-04",type:"mc",q:"Khi dùng ảnh của người khác cho bài thuyết trình, em cần ghi thêm điều gì?",emoji:"🖼️",explain:"Ghi tên tác giả hoặc nguồn là tôn trọng người làm ra bức ảnh.",options:["Tên tác giả hoặc nguồn","Ngày em mở máy tính","Tên phần mềm em dùng","Số trang em đã xem"],answer:0},{id:"th5-ban-quyen-noi-dung-05",type:"tf",q:"Bức tranh em tự vẽ trên máy tính cũng có bản quyền.",emoji:"🎨",explain:"Đúng. Em là tác giả nên bức tranh của em cũng có bản quyền.",answer:!0},{id:"th5-ban-quyen-noi-dung-06",type:"mc",q:"Việc nào là tôn trọng bản quyền?",explain:"Xin phép tác giả trước khi dùng là tôn trọng bản quyền.",options:["Xoá tên tác giả trên ảnh","Ghi tên mình lên bài của bạn","Đăng lại phim phải trả tiền","Xin phép trước khi dùng"],answer:3},{id:"th5-ban-quyen-noi-dung-07",type:"tf",q:"Chép bài văn trên mạng rồi ghi tên mình là tác giả là việc không trung thực.",explain:"Đúng. Đó là nhận công sức của người khác là của mình.",answer:!0},{id:"th5-ban-quyen-noi-dung-08",type:"mc",q:"Ghi nguồn có nghĩa là gì?",explain:"Ghi nguồn là ghi rõ em lấy nội dung từ đâu, của ai.",options:["Ghi số điện thoại của em","Ghi tên của lớp em học","Ghi nơi em lấy nội dung đó","Ghi giờ em làm xong bài"],answer:2},{id:"th5-ban-quyen-noi-dung-09",type:"tf",q:"Gửi miễn phí cho bạn bè một bộ phim phải trả tiền mới được xem là việc được phép.",emoji:"🎬",explain:"Sai. Chia sẻ trái phép nội dung phải trả tiền là vi phạm bản quyền.",answer:!1}]},{questions:[{id:"th5-ban-quyen-noi-dung-10",type:"match",q:"Ghép việc làm với tên gọi của việc đó.",explain:"Ghi tên tác giả, ghi nguồn, xin phép là tôn trọng bản quyền; ghi tên mình lên bài của bạn là không trung thực.",pairs:[["Ghi “Ảnh: Lan” dưới bức ảnh","Ghi tên tác giả"],["Ghi “Nguồn: trang web Vườn chim”","Ghi nguồn"],["Hỏi Bình trước khi dùng tranh Bình vẽ","Xin phép"],["Ghi tên mình lên bài của bạn","Không trung thực"]]},{id:"th5-ban-quyen-noi-dung-11",type:"multi",q:"Những việc nào tôn trọng bản quyền khi làm bài thuyết trình?",explain:"Chép nguyên bài viết rồi ghi tên mình là nhận bài của người khác.",options:["Ghi nguồn dưới mỗi ảnh lấy từ mạng","Xin phép bạn trước khi dùng ảnh bạn chụp","Chép nguyên bài viết rồi ghi tên mình","Ghi tên tác giả bài hát dùng làm nhạc nền"],answers:[0,1,3]},{id:"th5-ban-quyen-noi-dung-12",type:"mc",q:"Vì sao cần ghi tên tác giả khi dùng sản phẩm của người khác?",explain:"Tác giả đã bỏ công sức làm ra sản phẩm, ghi tên là tôn trọng họ.",options:["Để bài làm dài hơn","Để tôn trọng công sức tác giả","Để máy tính chạy nhanh hơn","Để không ai xem được bài"],answer:1},{id:"th5-ban-quyen-noi-dung-13",type:"tf",q:"Chỉ cần sửa vài chữ trong bài viết của người khác là bài đó thành của em.",explain:"Sai. Sửa vài chữ thì bài viết vẫn là công sức của tác giả.",answer:!1},{id:"th5-ban-quyen-noi-dung-14",type:"tf",q:"Nếu một trang web ghi rõ nội dung không được sao chép, em cần làm theo.",explain:"Đúng. Tác giả có quyền quyết định cách người khác dùng sản phẩm của mình.",answer:!0},{id:"th5-ban-quyen-noi-dung-15",type:"mc",q:"Nội dung nào dưới đây do chính em là tác giả?",explain:"Em tự viết bài văn nên em là tác giả của bài văn đó.",options:["Bài văn em tự viết ở lớp","Bài hát em nghe trên mạng","Video hoạt hình em vừa xem","Bức ảnh em tải từ trang web"],answer:0},{id:"th5-ban-quyen-noi-dung-16",type:"order",q:"Sắp xếp các việc khi muốn đưa bài thơ của bạn Chi vào tập san của lớp.",explain:"Phải hỏi và được Chi đồng ý rồi mới dùng, và luôn ghi tên Chi là tác giả.",items:["Đọc bài thơ và thấy rất hay","Hỏi Chi có đồng ý cho dùng không","Chi đồng ý","Đưa bài thơ kèm tên Chi vào tập san"]},{id:"th5-ban-quyen-noi-dung-17",type:"mc",q:"Dòng ghi nguồn nào rõ ràng nhất cho bức ảnh lấy từ mạng?",explain:"Dòng ghi nguồn tốt cho biết ai chụp ảnh và lấy từ trang nào.",options:["Ảnh: em tìm thấy trên mạng","Ảnh: không cần ghi là của ai","Ảnh: rất đẹp, em thích lắm","Ảnh: Minh, trang web Chim Việt"],answer:3},{id:"th5-ban-quyen-noi-dung-18",type:"fill",q:"Điền từ còn thiếu: Người làm ra bức tranh, bài hát, bài văn được gọi là … .",explain:"Người làm ra sản phẩm là tác giả của sản phẩm đó.",answer:["tác giả","tac gia"]}]},{questions:[{id:"th5-ban-quyen-noi-dung-19",type:"mc",q:"Lan dùng một bài hát trên mạng làm nhạc nền cho video giới thiệu lớp. Lan nên làm gì?",emoji:"🎶",explain:"Ghi tên bài hát và tác giả là tôn trọng người sáng tác.",options:["Nói bài hát do mình sáng tác","Cắt bớt để không ai nhận ra","Ghi tên bài hát và tác giả","Không ghi gì vì đã tải về"],answer:2},{id:"th5-ban-quyen-noi-dung-20",type:"tf",q:"Nam chép một đoạn văn trên mạng vào bài làm và ghi rõ nguồn. Nam đã tôn trọng tác giả.",explain:"Đúng. Ghi rõ nguồn cho người đọc biết đoạn văn đó không phải do Nam viết.",answer:!0},{id:"th5-ban-quyen-noi-dung-21",type:"mc",q:"Minh thấy một người đăng lại bức tranh của Hà và ghi là của mình vẽ. Minh nên làm gì?",explain:"Người đó đã nhận tranh của Hà là của mình, cần báo để Hà và người lớn xử lí.",options:["Bấm thích và chia sẻ tiếp","Báo cho Hà và người lớn biết","Chép bức tranh về máy mình","Im lặng vì không phải tranh mình"],answer:1},{id:"th5-ban-quyen-noi-dung-22",type:"tf",q:"Khoa mua một cuốn truyện tranh điện tử. Khoa được gửi bản đó cho cả lớp tải về.",emoji:"📚",explain:"Sai. Khoa mua để đọc, không được chia sẻ cho nhiều người khi chưa được phép.",answer:!1},{id:"th5-ban-quyen-noi-dung-23",type:"multi",q:"Vy làm báo tường điện tử về loài chim. Những việc nào Vy nên làm?",explain:"Ghi tên mình dưới ảnh của người khác là nhận công sức của họ.",options:["Ghi nguồn cho các ảnh lấy từ mạng","Tự viết lời giới thiệu bằng lời của mình","Ghi tên mình dưới ảnh của người khác","Xin phép bạn trước khi dùng ảnh bạn chụp"],answers:[0,1,3]},{id:"th5-ban-quyen-noi-dung-24",type:"mc",q:"Ngọc muốn đưa bài văn hay của Phúc lên trang của lớp. Việc đầu tiên Ngọc cần làm là gì?",explain:"Phúc là tác giả nên Ngọc cần hỏi Phúc trước.",options:["Hỏi xem Phúc có đồng ý không","Sửa bài cho hay hơn rồi đăng","Ghi tên Ngọc ở cuối bài văn","Đăng ngay vì là bạn cùng lớp"],answer:0},{id:"th5-ban-quyen-noi-dung-25",type:"match",q:"Ghép tình huống với cách làm đúng.",explain:"Mỗi tình huống đều cần tôn trọng người làm ra sản phẩm.",pairs:[["Muốn dùng ảnh do bạn chụp","Hỏi bạn trước"],["Trích một câu thơ trên mạng","Ghi tên tác giả"],["Được rủ tải phim chia sẻ trái phép","Từ chối"]]},{id:"th5-ban-quyen-noi-dung-26",type:"tf",q:"Phần mềm soạn thảo cho phép sao chép bài của người khác, nên việc chép đó luôn được phép.",explain:"Sai. Máy làm được không có nghĩa là được phép, em vẫn phải tôn trọng tác giả.",answer:!1},{id:"th5-ban-quyen-noi-dung-27",type:"mc",q:"Thảo đăng một video Thảo tự quay cảnh vườn nhà. Một bạn muốn dùng video đó. Bạn ấy cần làm gì?",emoji:"🎥",explain:"Thảo là tác giả video nên bạn cần được Thảo đồng ý.",options:["Tải về rồi ghi tên của mình","Dùng luôn vì video đã đăng","Cắt bớt rồi dùng tự do","Hỏi và được Thảo đồng ý"],answer:3}]}],challenge:{questions:[{id:"th5-ban-quyen-noi-dung-28",type:"mc",q:"Bình nói: “Video nào đăng công khai trên mạng thì ai cũng được dùng tự do.” Ý kiến này thế nào?",explain:"Được xem không có nghĩa là được dùng tự do, video vẫn có tác giả và bản quyền.",options:["Đúng, vì ai cũng xem được","Đúng, nếu video rất ngắn","Sai, vì video vẫn có tác giả","Đúng, nếu dùng cho bài học"],answer:2},{id:"th5-ban-quyen-noi-dung-21",type:"mc",q:"Minh thấy một người đăng lại bức tranh của Hà và ghi là của mình vẽ. Minh nên làm gì?",explain:"Người đó đã nhận tranh của Hà là của mình, cần báo để Hà và người lớn xử lí.",options:["Bấm thích và chia sẻ tiếp","Báo cho Hà và người lớn biết","Chép bức tranh về máy mình","Im lặng vì không phải tranh mình"],answer:1},{id:"th5-ban-quyen-noi-dung-29",type:"multi",q:"Những việc nào là vi phạm bản quyền?",explain:"Chia sẻ trái phép và đổi tên tác giả là vi phạm bản quyền.",options:["Chia sẻ trái phép sách điện tử phải trả tiền","Ghi tên tác giả khi trích một bài thơ","Đổi tên tác giả trên bức tranh của bạn","Dùng ảnh tự chụp cho bài làm của mình"],answers:[0,2]},{id:"th5-ban-quyen-noi-dung-23",type:"multi",q:"Vy làm báo tường điện tử về loài chim. Những việc nào Vy nên làm?",explain:"Ghi tên mình dưới ảnh của người khác là nhận công sức của họ.",options:["Ghi nguồn cho các ảnh lấy từ mạng","Tự viết lời giới thiệu bằng lời của mình","Ghi tên mình dưới ảnh của người khác","Xin phép bạn trước khi dùng ảnh bạn chụp"],answers:[0,1,3]},{id:"th5-ban-quyen-noi-dung-30",type:"mc",q:"Chi lấy ý từ một bài viết trên mạng nhưng viết lại bằng lời của mình. Chi nên làm thêm gì?",explain:"Ý tưởng lấy từ bài của người khác nên Chi vẫn cần ghi nguồn đã tham khảo.",options:["Xoá bài viết đó trên mạng đi","Ghi nguồn bài viết đã tham khảo","Nói là mình tự nghĩ ra hết","Không cần làm gì thêm nữa"],answer:1},{id:"th5-ban-quyen-noi-dung-26",type:"tf",q:"Phần mềm soạn thảo cho phép sao chép bài của người khác, nên việc chép đó luôn được phép.",explain:"Sai. Máy làm được không có nghĩa là được phép, em vẫn phải tôn trọng tác giả.",answer:!1},{id:"th5-ban-quyen-noi-dung-17",type:"mc",q:"Dòng ghi nguồn nào rõ ràng nhất cho bức ảnh lấy từ mạng?",explain:"Dòng ghi nguồn tốt cho biết ai chụp ảnh và lấy từ trang nào.",options:["Ảnh: em tìm thấy trên mạng","Ảnh: không cần ghi là của ai","Ảnh: rất đẹp, em thích lắm","Ảnh: Minh, trang web Chim Việt"],answer:3}]},summary:["Ảnh, bài hát, video, bài viết trên mạng đều có tác giả và có bản quyền.","Khi dùng sản phẩm của người khác, em xin phép khi cần và ghi rõ tác giả hoặc nguồn.","Không nhận bài của người khác là của mình, không chia sẻ trái phép nội dung phải trả tiền."]},{id:"th5-ung-xu-van-minh",title:"Bài 9: Ứng xử văn minh trên mạng",weeks:[16,17],learn:[{title:"Lời nói lịch sự",text:"Trên mạng, em vẫn nói chuyện như khi gặp mặt: chào hỏi, cảm ơn, xin lỗi. Không dùng lời chê bai, chế giễu làm người khác buồn.",example:"💬 Cảm ơn bạn! · 🙏 Xin lỗi bạn nhé!"},{title:"Khi bị bắt nạt trên mạng",text:"Nếu bị nhắn tin trêu chọc, đe doạ, em không đáp trả, giữ lại tin nhắn làm bằng chứng và kể ngay với bố mẹ, thầy cô.",example:"🙅 không đáp trả · 📸 giữ bằng chứng · 👨‍👩‍👧 kể người lớn"},{title:"Nghĩ trước khi đăng",text:"Trước khi đăng, hãy tự hỏi: điều này có đúng không, có làm ai buồn không? Không đăng ảnh, thông tin của người khác khi chưa được phép.",example:"🤔 Đúng không? · Tốt không? · Được phép chưa?"},{title:"Giữ an toàn",text:"Không cho người lạ biết địa chỉ nhà, trường học, số điện thoại, mật khẩu. Người quen trên mạng rủ gặp mặt thì phải nói ngay với bố mẹ.",example:"🔒 địa chỉ · số điện thoại · mật khẩu"}],practice:[{questions:[{id:"th5-ung-xu-van-minh-01",type:"tf",q:"Khi nhắn tin trên mạng, em vẫn cần nói lời cảm ơn và xin lỗi như khi gặp mặt.",emoji:"💬",explain:"Đúng. Lịch sự trên mạng cũng như lịch sự khi gặp nhau.",answer:!0},{id:"th5-ung-xu-van-minh-02",type:"mc",q:"Lời bình luận nào lịch sự dưới bức tranh của bạn?",emoji:"🎨",explain:"Lời khen chân thành làm bạn vui, các câu còn lại làm bạn buồn.",options:["Bạn vẽ màu đẹp quá!","Tranh xấu quá, vẽ lại đi!","Ai mà thèm xem tranh này!","Tranh gì mà khó hiểu thế?"],answer:0},{id:"th5-ung-xu-van-minh-03",type:"tf",q:"Gửi tin nhắn chế giễu bạn trên mạng chỉ là đùa vui, không làm ai buồn.",explain:"Sai. Lời chế giễu có thể làm bạn rất buồn, đó là bắt nạt trên mạng.",answer:!1},{id:"th5-ung-xu-van-minh-04",type:"mc",q:"Bị một người nhắn tin đe doạ, em nên làm gì?",explain:"Người lớn sẽ giúp em xử lí và bảo vệ em.",options:["Nhắn lại để doạ người đó","Xoá hết tin nhắn cho đỡ sợ","Giấu kín, không cho ai biết","Kể ngay với bố mẹ, thầy cô"],answer:3},{id:"th5-ung-xu-van-minh-05",type:"tf",q:"Mật khẩu của em có thể cho bạn thân biết để bạn giữ hộ.",emoji:"🔒",explain:"Sai. Mật khẩu phải giữ kín, chỉ bố mẹ được biết khi cần.",answer:!1},{id:"th5-ung-xu-van-minh-06",type:"mc",q:"Thông tin nào em không nên cho người lạ trên mạng biết?",emoji:"🏠",explain:"Địa chỉ nhà là thông tin cá nhân, người lạ biết có thể gây nguy hiểm.",options:["Màu sắc em thích","Con vật em yêu","Địa chỉ nhà em","Món ăn em thích"],answer:2},{id:"th5-ung-xu-van-minh-07",type:"tf",q:"Trước khi đăng ảnh có mặt bạn mình, em cần hỏi bạn có đồng ý không.",explain:"Đúng. Ảnh có mặt bạn là thông tin của bạn, cần bạn đồng ý.",answer:!0},{id:"th5-ung-xu-van-minh-08",type:"mc",q:"Việc nào là bắt nạt trên mạng?",explain:"Liên tục chê bai một bạn làm bạn buồn, sợ hãi, đó là bắt nạt.",options:["Gửi lời chúc mừng sinh nhật bạn","Liên tục nhắn tin chê bai một bạn","Hỏi bạn bài tập về nhà hôm nay","Gửi bạn ảnh con mèo đáng yêu"],answer:1},{id:"th5-ung-xu-van-minh-09",type:"tf",q:"Khi bị bắt nạt trên mạng, em nên giữ lại tin nhắn làm bằng chứng.",emoji:"📸",explain:"Đúng. Bằng chứng giúp người lớn biết chuyện gì đã xảy ra để giúp em.",answer:!0}]},{questions:[{id:"th5-ung-xu-van-minh-10",type:"match",q:"Ghép tình huống với cách ứng xử đúng.",explain:"Cảm ơn, xin lỗi đúng lúc và giữ kín thông tin là ứng xử văn minh.",pairs:[["Bạn gửi lời chúc mừng em","Cảm ơn bạn"],["Em lỡ gửi nhầm tin nhắn làm bạn buồn","Xin lỗi bạn"],["Người lạ hỏi địa chỉ nhà em","Không trả lời, báo bố mẹ"]]},{id:"th5-ung-xu-van-minh-11",type:"multi",q:"Những việc nào là ứng xử văn minh trên mạng?",explain:"Trêu chọc và hùa theo chê bai làm người khác buồn.",options:["Dùng lời lẽ lịch sự khi bình luận","Chia sẻ ảnh xấu của bạn để trêu","Góp ý nhẹ nhàng khi bạn làm sai","Hùa theo khi cả nhóm chê một bạn"],answers:[0,2]},{id:"th5-ung-xu-van-minh-12",type:"mc",q:"Vì sao không nên nhắn lại cho người bắt nạt mình trên mạng?",explain:"Đáp trả có thể làm người bắt nạt tiếp tục, chuyện càng tệ hơn.",options:["Vì nhắn lại dễ làm việc tệ hơn","Vì máy tính sẽ bị hỏng ngay","Vì tin nhắn sẽ tự biến mất","Vì mạng sẽ bị mất kết nối"],answer:0},{id:"th5-ung-xu-van-minh-13",type:"tf",q:"Đăng tin chưa biết đúng hay sai lên mạng có thể làm hại người khác.",explain:"Đúng. Tin sai lan nhanh trên mạng và có thể làm người khác bị hiểu lầm, lo sợ.",answer:!0},{id:"th5-ung-xu-van-minh-14",type:"tf",q:"Bạn trên mạng đã nói chuyện lâu ngày thì chắc chắn là người tốt.",explain:"Sai. Em không biết chắc người đó thật sự là ai, cần cẩn thận.",answer:!1},{id:"th5-ung-xu-van-minh-15",type:"mc",q:"Trước khi đăng một bình luận, em nên tự hỏi điều gì?",explain:"Nghĩ xem lời mình có làm ai buồn không giúp em ứng xử tử tế.",options:["Bình luận đã đủ dài chưa?","Có nhiều người thích không?","Đã có ai đăng trước chưa?","Lời đó có làm ai buồn không?"],answer:3},{id:"th5-ung-xu-van-minh-16",type:"order",q:"Sắp xếp các việc nên làm khi bị nhắn tin trêu chọc trên mạng.",explain:"Giữ bằng chứng trước, kể với người lớn, rồi người lớn giúp em chặn và báo cáo.",items:["Chụp lại tin nhắn làm bằng chứng","Kể với bố mẹ hoặc thầy cô","Cùng người lớn chặn và báo cáo tài khoản đó"]},{id:"th5-ung-xu-van-minh-17",type:"mc",q:"Hà muốn đăng ảnh cả nhóm đi tham quan. Hà nên làm gì trước?",emoji:"📸",explain:"Ảnh có mặt các bạn nên cần các bạn đồng ý trước khi đăng.",options:["Chọn ảnh mà mình đẹp nhất","Ghi rõ địa chỉ nhà từng bạn","Hỏi các bạn có đồng ý không","Đăng ngay cho thật nhanh"],answer:2},{id:"th5-ung-xu-van-minh-18",type:"fill",q:"Điền từ còn thiếu: Trước khi đăng ảnh có mặt bạn, em cần xin … bạn.",explain:"Xin phép bạn trước khi đăng là tôn trọng bạn.",answer:["phép"]}]},{questions:[{id:"th5-ung-xu-van-minh-19",type:"mc",q:"Minh thấy các bạn trong nhóm chat cùng chê bai một bạn. Minh nên làm gì?",explain:"Không hùa theo và báo người lớn là cách giúp bạn bị chê bai.",options:["Chê thêm cho vui cùng nhóm","Không hùa theo, báo thầy cô","Chụp ảnh bạn đó gửi đi tiếp","Rời nhóm và không kể với ai"],answer:1},{id:"th5-ung-xu-van-minh-20",type:"tf",q:"Một người quen trên mạng rủ Lan đi gặp mặt. Lan nên đi một mình để giữ bí mật.",explain:"Sai. Lan phải nói ngay với bố mẹ, không tự đi gặp người quen trên mạng.",answer:!1},{id:"th5-ung-xu-van-minh-21",type:"mc",q:"Khoa nhắn nhầm một câu làm bạn buồn trong nhóm chat của lớp. Khoa nên làm gì?",explain:"Biết nhận lỗi và xin lỗi là ứng xử văn minh.",options:["Xin lỗi bạn một cách chân thành","Rời khỏi nhóm chat cho xong","Giả vờ như không có chuyện gì","Đổ lỗi cho máy tính tự gõ"],answer:0},{id:"th5-ung-xu-van-minh-22",type:"tf",q:"Nam được nhờ chia sẻ một tin chưa rõ thật giả. Nam nên chưa chia sẻ và hỏi người lớn.",explain:"Đúng. Tin chưa rõ thật giả thì không nên chia sẻ vội.",answer:!0},{id:"th5-ung-xu-van-minh-23",type:"multi",q:"Một tài khoản lạ nhắn hỏi Chi học trường nào, nhà ở đâu. Chi nên làm gì?",explain:"Không cho người lạ biết thông tin cá nhân và báo ngay cho bố mẹ.",options:["Không trả lời các câu hỏi đó","Gửi ảnh cổng trường cho người đó","Kể với bố mẹ ngay","Hỏi lại số điện thoại của người đó"],answers:[0,2]},{id:"th5-ung-xu-van-minh-24",type:"mc",q:"Dũng chụp được ảnh một bạn ngủ gật trong lớp. Dũng nên làm gì?",explain:"Đăng ảnh làm bạn xấu hổ là trêu chọc, bạn sẽ buồn.",options:["Đăng lên mạng cho cả lớp cười","Gửi riêng cho vài bạn xem","Ghép thêm chữ trêu rồi đăng","Không đăng vì bạn sẽ buồn"],answer:3},{id:"th5-ung-xu-van-minh-25",type:"match",q:"Ghép tình huống với việc nên làm.",explain:"Mỗi việc làm đó đều thể hiện ứng xử văn minh trên mạng.",pairs:[["Được bạn khen bài vẽ","Nói lời cảm ơn"],["Thấy bạn bị chê bai trên mạng","Động viên bạn, báo người lớn"],["Thấy một tin chưa rõ thật giả","Không chia sẻ vội"],["Muốn đăng ảnh có mặt bạn","Xin phép bạn trước"]]},{id:"th5-ung-xu-van-minh-26",type:"tf",q:"Vy cho một người trên mạng biết mật khẩu vì người đó hứa tặng quà. Vy làm vậy là an toàn.",emoji:"🎁",explain:"Sai. Không bao giờ cho người khác biết mật khẩu, lời hứa tặng quà có thể là lừa đảo.",answer:!1},{id:"th5-ung-xu-van-minh-27",type:"mc",q:"Phúc nhận tin nhắn có lời lẽ xấu từ một tài khoản lạ. Việc nào Phúc không nên làm?",explain:"Đáp trả bằng lời lẽ xấu chỉ làm chuyện tệ hơn.",options:["Giữ lại tin nhắn làm bằng chứng","Kể với bố mẹ hoặc thầy cô","Nhắn lại lời lẽ xấu để đáp trả","Nhờ người lớn chặn tài khoản đó"],answer:2}]}],challenge:{questions:[{id:"th5-ung-xu-van-minh-28",type:"mc",q:"Tùng bị nhiều người bình luận chê bai dưới bài đăng. Em giúp Tùng thế nào là tốt nhất?",explain:"Động viên Tùng và cùng báo người lớn giúp Tùng bớt buồn, không làm chuyện tệ hơn.",options:["Bình luận chê lại những người đó","Nhắn hỏi thăm, động viên Tùng","Chia sẻ bài cho nhiều người xem","Không quan tâm vì không phải mình"],answer:1},{id:"th5-ung-xu-van-minh-19",type:"mc",q:"Minh thấy các bạn trong nhóm chat cùng chê bai một bạn. Minh nên làm gì?",explain:"Không hùa theo và báo người lớn là cách giúp bạn bị chê bai.",options:["Chê thêm cho vui cùng nhóm","Không hùa theo, báo thầy cô","Chụp ảnh bạn đó gửi đi tiếp","Rời nhóm và không kể với ai"],answer:1},{id:"th5-ung-xu-van-minh-29",type:"multi",q:"Trước khi đăng một bài lên mạng, những câu hỏi nào em nên tự hỏi?",explain:"Đúng sự thật, không làm ai buồn, không lộ thông tin riêng mới là điều quan trọng.",options:["Điều này có đúng sự thật không?","Điều này có làm ai buồn không?","Có lộ thông tin riêng của ai không?","Bài có được nhiều lượt thích không?"],answers:[0,1,2]},{id:"th5-ung-xu-van-minh-23",type:"multi",q:"Một tài khoản lạ nhắn hỏi Chi học trường nào, nhà ở đâu. Chi nên làm gì?",explain:"Không cho người lạ biết thông tin cá nhân và báo ngay cho bố mẹ.",options:["Không trả lời các câu hỏi đó","Gửi ảnh cổng trường cho người đó","Kể với bố mẹ ngay","Hỏi lại số điện thoại của người đó"],answers:[0,2]},{id:"th5-ung-xu-van-minh-30",type:"tf",q:"Tin nhắn trên mạng đã xoá thì chắc chắn không ai còn xem lại được.",explain:"Sai. Người khác có thể đã chụp lại hoặc lưu lại trước khi em xoá.",answer:!1},{id:"th5-ung-xu-van-minh-25",type:"match",q:"Ghép tình huống với việc nên làm.",explain:"Mỗi việc làm đó đều thể hiện ứng xử văn minh trên mạng.",pairs:[["Được bạn khen bài vẽ","Nói lời cảm ơn"],["Thấy bạn bị chê bai trên mạng","Động viên bạn, báo người lớn"],["Thấy một tin chưa rõ thật giả","Không chia sẻ vội"],["Muốn đăng ảnh có mặt bạn","Xin phép bạn trước"]]},{id:"th5-ung-xu-van-minh-27",type:"mc",q:"Phúc nhận tin nhắn có lời lẽ xấu từ một tài khoản lạ. Việc nào Phúc không nên làm?",explain:"Đáp trả bằng lời lẽ xấu chỉ làm chuyện tệ hơn.",options:["Giữ lại tin nhắn làm bằng chứng","Kể với bố mẹ hoặc thầy cô","Nhắn lại lời lẽ xấu để đáp trả","Nhờ người lớn chặn tài khoản đó"],answer:2}]},summary:["Trên mạng, em nói năng lịch sự, không chê bai, chế giễu người khác.","Bị bắt nạt trên mạng thì không đáp trả, giữ bằng chứng và kể với người lớn.","Nghĩ kĩ trước khi đăng, xin phép khi đăng ảnh của bạn và giữ kín thông tin cá nhân."]}]},{id:"ung-dung-tin-hoc",title:"Ứng dụng tin học",lessons:[{id:"th5-dinh-dang-ki-tu",title:"Bài 10: Định dạng kí tự và đoạn văn",weeks:[18,19],learn:[{title:"Chọn trước, định dạng sau",text:"Muốn định dạng phần chữ nào, em chọn (bôi đen) phần chữ đó trước, rồi mới chọn lệnh định dạng.",example:"🖱️ kéo chọn chữ → chọn lệnh"},{title:"Định dạng kí tự",text:"Em có thể đổi phông chữ, cỡ chữ, màu chữ và làm chữ in đậm, in nghiêng, gạch chân. Cỡ chữ càng lớn thì chữ càng to.",example:"Đậm · Nghiêng · Gạch chân · cỡ 14 < cỡ 20"},{title:"Căn lề đoạn văn",text:"Căn lề áp dụng cho cả đoạn văn: căn trái, căn giữa, căn phải, căn đều hai bên. Tên bài thường căn giữa. Căn đều hai bên làm hai mép đoạn văn thẳng hàng.",example:"⬅️ trái · ↔️ giữa · ➡️ phải · ▤ đều hai bên"},{title:"Định dạng vừa phải",text:"In đậm để làm nổi bật từ quan trọng, không nên in đậm cả bài. Chỉ dùng ít phông, ít màu và chọn màu dễ đọc.",example:"✅ tên bài nổi bật · ❌ mỗi dòng một màu"}],practice:[{questions:[{id:"th5-dinh-dang-ki-tu-01",type:"tf",q:"Muốn định dạng một phần chữ, em cần chọn phần chữ đó trước.",emoji:"🖱️",explain:"Đúng. Phần mềm chỉ định dạng phần chữ đang được chọn.",answer:!0},{id:"th5-dinh-dang-ki-tu-02",type:"mc",q:"Cỡ chữ 20 so với cỡ chữ 12 thì chữ như thế nào?",explain:"Cỡ chữ càng lớn thì chữ càng to.",options:["To hơn","Nhỏ hơn","Bằng nhau","Nghiêng hơn"],answer:0},{id:"th5-dinh-dang-ki-tu-03",type:"mc",q:"Định dạng nào làm chữ nghiêng sang một bên?",explain:"In nghiêng làm chữ nghiêng sang một bên.",options:["In đậm","Gạch chân","Căn giữa","In nghiêng"],answer:3},{id:"th5-dinh-dang-ki-tu-04",type:"tf",q:"Căn lề là cách định dạng cho cả đoạn văn.",explain:"Đúng. Căn lề làm cả đoạn văn nằm bên trái, giữa, bên phải hoặc đều hai bên.",answer:!0},{id:"th5-dinh-dang-ki-tu-05",type:"number",q:"Kể cả căn đều hai bên, phần mềm soạn thảo văn bản có mấy cách căn lề đoạn văn?",explain:"Có 4 cách: căn trái, căn giữa, căn phải và căn đều hai bên.",answer:4,unit:"cách"},{id:"th5-dinh-dang-ki-tu-06",type:"tf",q:"Đổi màu chữ sẽ làm thay đổi nội dung của câu văn.",emoji:"🎨",explain:"Sai. Đổi màu chỉ thay đổi cách chữ hiện ra, nội dung câu vẫn giữ nguyên.",answer:!1},{id:"th5-dinh-dang-ki-tu-07",type:"mc",q:"Căn đều hai bên làm cho đoạn văn như thế nào?",explain:"Căn đều hai bên làm cả mép trái và mép phải của đoạn văn thẳng hàng.",options:["Chữ to hơn bình thường","Chữ đổi sang màu đỏ","Hai mép đoạn văn đều thẳng","Chữ nằm sát mép phải"],answer:2},{id:"th5-dinh-dang-ki-tu-08",type:"match",q:"Ghép định dạng với điều nó thay đổi.",explain:"Cỡ chữ đổi độ to, màu chữ đổi màu, phông chữ đổi kiểu dáng nét chữ.",pairs:[["Cỡ chữ","Chữ to hay nhỏ"],["Màu chữ","Chữ đỏ, xanh hay đen"],["Phông chữ","Kiểu dáng nét chữ"]]},{id:"th5-dinh-dang-ki-tu-09",type:"tf",q:"Muốn đoạn văn nằm sát lề phải, em chọn căn trái.",explain:"Sai. Muốn đoạn văn nằm sát lề phải thì chọn căn phải.",answer:!1}]},{questions:[{id:"th5-dinh-dang-ki-tu-10",type:"multi",q:"Những định dạng nào là định dạng kí tự?",explain:"Căn giữa và căn đều hai bên là định dạng đoạn văn.",options:["In đậm","Đổi cỡ chữ","Căn giữa","Đổi màu chữ","Căn đều hai bên"],answers:[0,1,3]},{id:"th5-dinh-dang-ki-tu-11",type:"mc",q:"Vì sao không nên in đậm cả bài văn?",explain:"In đậm dùng để làm nổi bật, in đậm hết thì không còn chỗ nào nổi bật.",options:["Vì máy in sẽ bị hỏng","Vì khó thấy chỗ quan trọng","Vì chữ đậm không đọc được","Vì bài văn sẽ bị xoá mất"],answer:1},{id:"th5-dinh-dang-ki-tu-12",type:"tf",q:"Để căn giữa một đoạn văn, em có thể đặt con trỏ soạn thảo vào trong đoạn đó rồi chọn căn giữa.",explain:"Đúng. Căn lề áp dụng cho cả đoạn văn có con trỏ soạn thảo.",answer:!0},{id:"th5-dinh-dang-ki-tu-13",type:"mc",q:"Lan bôi đen chữ “Mùa xuân” rồi chọn cỡ chữ 24. Điều gì xảy ra?",emoji:"🌸",explain:"Chỉ phần chữ được chọn mới đổi cỡ.",options:["Chỉ chữ “Mùa xuân” đổi cỡ","Cả bài đổi sang cỡ 24","Chữ “Mùa xuân” bị xoá đi","Chữ “Mùa xuân” in nghiêng"],answer:0},{id:"th5-dinh-dang-ki-tu-14",type:"mc",q:"Màu chữ nào dễ đọc nhất trên nền giấy trắng?",explain:"Màu đậm nổi rõ trên nền trắng, màu nhạt rất khó đọc.",options:["Vàng nhạt","Trắng","Hồng nhạt","Xanh đậm"],answer:3},{id:"th5-dinh-dang-ki-tu-15",type:"tf",q:"Bình chọn một phông chữ khác nhau cho mỗi dòng để bài đẹp hơn. Đó là cách trình bày tốt.",explain:"Sai. Dùng quá nhiều phông chữ làm bài rối mắt, khó đọc.",answer:!1},{id:"th5-dinh-dang-ki-tu-16",type:"order",q:"Sắp xếp các bước làm cho tên bài “Quê em” có màu đỏ.",explain:"Gõ chữ, chọn chữ, rồi mới chọn màu.",items:["Gõ chữ “Quê em”","Bôi đen chữ “Quê em”","Chọn màu đỏ cho chữ","Nháy chuột ra chỗ khác để xem kết quả"]},{id:"th5-dinh-dang-ki-tu-17",type:"match",q:"Ghép phần văn bản với cách căn lề thường dùng.",explain:"Tên bài căn giữa, dòng ngày tháng đầu thư căn phải, thân bài căn đều hai bên cho gọn.",pairs:[["Tên bài văn","Căn giữa"],["Dòng địa điểm, ngày tháng ở đầu thư","Căn phải"],["Đoạn văn trong thân bài","Căn đều hai bên"]]},{id:"th5-dinh-dang-ki-tu-18",type:"fill",q:"Điền từ còn thiếu: Muốn định dạng một từ, em phải … từ đó trước.",explain:"Phải chọn phần chữ trước rồi mới định dạng.",answer:["chọn","bôi đen","bôi"]}]},{questions:[{id:"th5-dinh-dang-ki-tu-19",type:"mc",q:"Chi làm thiệp mời và muốn dòng “Thân mời các bạn” nổi bật. Cách nào hợp lí?",emoji:"💌",explain:"Chữ đậm và to hơn sẽ nổi bật hơn các dòng khác.",options:["Đổi sang màu trắng","Giảm cỡ chữ thật nhỏ","In đậm và tăng cỡ chữ","Xoá bớt chữ “các bạn”"],answer:2},{id:"th5-dinh-dang-ki-tu-20",type:"tf",q:"Minh chọn cả đoạn văn rồi chọn gạch chân. Chỉ từ đầu tiên của đoạn được gạch chân.",explain:"Sai. Cả phần chữ được chọn đều được gạch chân.",answer:!1},{id:"th5-dinh-dang-ki-tu-21",type:"mc",q:"Hà gõ xong lá thư. Dòng “Hà Nội, ngày 20 tháng 11” ở đầu thư nên căn lề thế nào?",emoji:"✉️",explain:"Dòng địa điểm, ngày tháng ở đầu thư thường căn phải.",options:["Căn trái","Căn phải","Căn giữa","Căn đều hai bên"],answer:1},{id:"th5-dinh-dang-ki-tu-22",type:"tf",q:"Dũng muốn in nghiêng tên một cuốn sách trong câu. Dũng chỉ chọn tên sách rồi chọn in nghiêng.",explain:"Đúng. Chỉ phần được chọn mới in nghiêng, các chữ khác giữ nguyên.",answer:!0},{id:"th5-dinh-dang-ki-tu-23",type:"multi",q:"Nam trình bày bài “Giới thiệu về em”. Những việc nào giúp bài dễ đọc?",explain:"Quá nhiều màu hoặc chữ quá nhỏ làm bài khó đọc.",options:["Tên bài căn giữa, chữ to hơn","Dùng một phông chữ rõ ràng","Mỗi dòng một màu sặc sỡ","In đậm vài từ quan trọng","Cỡ chữ thật nhỏ để vừa trang"],answers:[0,1,3]},{id:"th5-dinh-dang-ki-tu-24",type:"mc",q:"Khoa chọn cỡ chữ 30 nhưng chữ đã gõ trong bài không đổi. Lí do có thể là gì?",explain:"Chưa chọn phần chữ thì chữ đã gõ sẽ không đổi định dạng.",options:["Khoa chưa chọn phần chữ","Máy tính đang mất điện","Bàn phím bị hỏng phím","Cỡ chữ 30 quá nhỏ"],answer:0},{id:"th5-dinh-dang-ki-tu-25",type:"match",q:"Ghép điều muốn làm với cách định dạng.",explain:"Mỗi cách định dạng giúp trình bày một điều khác nhau.",pairs:[["Tên bài nằm giữa dòng","Căn giữa"],["Từ quan trọng nổi bật","In đậm"],["Chữ to, dễ nhìn hơn","Tăng cỡ chữ"],["Hai mép đoạn văn thẳng hàng","Căn đều hai bên"]]},{id:"th5-dinh-dang-ki-tu-26",type:"tf",q:"Ngọc in đậm tên bài rồi căn giữa. Nếu căn giữa trước rồi mới in đậm thì kết quả vẫn như nhau.",explain:"Đúng. In đậm và căn giữa là hai việc riêng, làm việc nào trước cũng được.",answer:!0},{id:"th5-dinh-dang-ki-tu-27",type:"mc",q:"Phúc muốn cả đoạn thơ nằm giữa trang. Phúc nên làm gì?",explain:"Căn giữa đưa các dòng thơ vào giữa trang một cách gọn gàng.",options:["Nhấn phím cách nhiều lần","Chọn đoạn thơ rồi in đậm","Tăng cỡ chữ của đoạn thơ","Chọn đoạn thơ rồi căn giữa"],answer:3}]}],challenge:{questions:[{id:"th5-dinh-dang-ki-tu-28",type:"mc",q:"Tùng chọn chữ “Bé” đang in đậm rồi chọn lệnh in đậm thêm lần nữa. Chữ “Bé” sẽ thế nào?",explain:"Chọn lệnh in đậm cho chữ đang in đậm sẽ bỏ in đậm.",options:["Đậm gấp đôi","Bị xoá mất","Hết in đậm","Đổi sang màu đỏ"],answer:2},{id:"th5-dinh-dang-ki-tu-24",type:"mc",q:"Khoa chọn cỡ chữ 30 nhưng chữ đã gõ trong bài không đổi. Lí do có thể là gì?",explain:"Chưa chọn phần chữ thì chữ đã gõ sẽ không đổi định dạng.",options:["Khoa chưa chọn phần chữ","Máy tính đang mất điện","Bàn phím bị hỏng phím","Cỡ chữ 30 quá nhỏ"],answer:0},{id:"th5-dinh-dang-ki-tu-29",type:"multi",q:"Thảo đã chọn một từ trong đoạn văn. Những lệnh nào chỉ đổi riêng từ đó?",explain:"Căn lề luôn áp dụng cho cả đoạn văn, còn định dạng kí tự chỉ đổi phần được chọn.",options:["In nghiêng","Đổi màu chữ","Căn phải","Đổi cỡ chữ","Căn giữa"],answers:[0,1,3]},{id:"th5-dinh-dang-ki-tu-20",type:"tf",q:"Minh chọn cả đoạn văn rồi chọn gạch chân. Chỉ từ đầu tiên của đoạn được gạch chân.",explain:"Sai. Cả phần chữ được chọn đều được gạch chân.",answer:!1},{id:"th5-dinh-dang-ki-tu-30",type:"mc",q:"Vy muốn đoạn giới thiệu có hai mép thẳng hàng và tên riêng in đậm. Vy cần dùng những gì?",explain:"Căn đều hai bên làm hai mép thẳng hàng, in đậm làm nổi bật tên riêng.",options:["Căn giữa và gạch chân","Căn đều hai bên và in đậm","Căn phải và in nghiêng","Căn trái và đổi màu"],answer:1},{id:"th5-dinh-dang-ki-tu-23",type:"multi",q:"Nam trình bày bài “Giới thiệu về em”. Những việc nào giúp bài dễ đọc?",explain:"Quá nhiều màu hoặc chữ quá nhỏ làm bài khó đọc.",options:["Tên bài căn giữa, chữ to hơn","Dùng một phông chữ rõ ràng","Mỗi dòng một màu sặc sỡ","In đậm vài từ quan trọng","Cỡ chữ thật nhỏ để vừa trang"],answers:[0,1,3]},{id:"th5-dinh-dang-ki-tu-26",type:"tf",q:"Ngọc in đậm tên bài rồi căn giữa. Nếu căn giữa trước rồi mới in đậm thì kết quả vẫn như nhau.",explain:"Đúng. In đậm và căn giữa là hai việc riêng, làm việc nào trước cũng được.",answer:!0}]},summary:["Muốn định dạng phần chữ nào, em chọn phần chữ đó trước rồi mới chọn lệnh.","Định dạng kí tự gồm phông chữ, cỡ chữ, màu chữ, in đậm, in nghiêng, gạch chân.","Căn lề áp dụng cho cả đoạn văn: căn trái, căn giữa, căn phải, căn đều hai bên."]},{id:"th5-chen-bang-hinh",title:"Bài 11: Chèn hình ảnh và bảng vào văn bản",weeks:[20,21],learn:[{title:"Chèn hình ảnh",text:"Em đặt con trỏ soạn thảo ở chỗ muốn có ảnh, chọn lệnh chèn ảnh rồi chọn tệp ảnh trong máy.",example:"📍 con trỏ → 🖼️ chèn ảnh → 📁 chọn tệp"},{title:"Chỉnh kích thước và vị trí ảnh",text:"Nháy chọn ảnh, các nút nhỏ hiện ở góc và cạnh ảnh. Kéo nút ở góc để ảnh to nhỏ mà không bị méo. Em có thể chọn cho chữ bao quanh ảnh và kéo ảnh sang chỗ khác.",example:"↘️ kéo góc: giữ tỉ lệ · ↔️ kéo cạnh: dễ méo"},{title:"Bảng gồm hàng, cột và ô",text:"Bảng có các hàng nằm ngang và các cột nằm dọc. Chỗ một hàng gặp một cột là một ô. Số ô bằng số hàng nhân số cột.",example:"3 hàng × 4 cột = 12 ô"},{title:"Khi nào dùng bảng",text:"Bảng giúp trình bày thời khoá biểu, danh sách, kết quả gọn gàng, dễ đọc. Khi cần, em có thể thêm hoặc xoá hàng, cột.",example:"📅 thời khoá biểu · 📋 danh sách tổ"}],practice:[{questions:[{id:"th5-chen-bang-hinh-01",type:"tf",q:"Trong bảng, chỗ một hàng gặp một cột gọi là một ô.",explain:"Đúng. Mỗi ô nằm ở chỗ một hàng gặp một cột.",answer:!0},{id:"th5-chen-bang-hinh-02",type:"mc",q:"Trong bảng, các ô xếp theo chiều ngang tạo thành gì?",explain:"Các ô xếp ngang tạo thành một hàng.",options:["Một hàng","Một cột","Một trang","Một tệp"],answer:0},{id:"th5-chen-bang-hinh-03",type:"mc",q:"Trong bảng, các ô xếp theo chiều dọc tạo thành gì?",explain:"Các ô xếp dọc tạo thành một cột.",options:["Một hình ảnh","Một hàng","Một đoạn văn","Một cột"],answer:3},{id:"th5-chen-bang-hinh-04",type:"tf",q:"Muốn ảnh to lên mà không bị méo, em nên kéo nút ở góc ảnh.",emoji:"🖼️",explain:"Đúng. Kéo nút ở góc giúp ảnh giữ đúng tỉ lệ.",answer:!0},{id:"th5-chen-bang-hinh-05",type:"number",q:"Một bảng có 3 hàng và 4 cột. Bảng đó có bao nhiêu ô?",explain:"Số ô bằng số hàng nhân số cột: 3 nhân 4 bằng 12.",answer:12,unit:"ô"},{id:"th5-chen-bang-hinh-06",type:"mc",q:"Trước khi chèn ảnh, em nên đặt con trỏ soạn thảo ở đâu?",explain:"Ảnh sẽ được chèn vào đúng chỗ có con trỏ soạn thảo.",options:["Ở cuối tên tệp ảnh","Ở trên thanh cuộn","Ở chỗ muốn đặt ảnh","Ở góc màn hình"],answer:2},{id:"th5-chen-bang-hinh-07",type:"tf",q:"Văn bản chỉ có thể chứa chữ, không thể chèn hình ảnh.",explain:"Sai. Em có thể chèn hình ảnh vào văn bản cho sinh động.",answer:!1},{id:"th5-chen-bang-hinh-08",type:"mc",q:"Nội dung nào nên trình bày bằng bảng?",emoji:"📅",explain:"Thời khoá biểu có ngày và tiết học, xếp vào hàng và cột sẽ dễ xem.",options:["Một bài thơ ngắn","Thời khoá biểu của lớp","Lời chúc mừng sinh nhật","Tên của một bài văn"],answer:1},{id:"th5-chen-bang-hinh-09",type:"tf",q:"Sau khi chèn, ảnh không thể đổi kích thước được nữa.",explain:"Sai. Em chọn ảnh rồi kéo các nút ở góc để đổi kích thước.",answer:!1}]},{questions:[{id:"th5-chen-bang-hinh-10",type:"match",q:"Ghép từ với ý nghĩa của nó trong bảng.",explain:"Hàng nằm ngang, cột nằm dọc, ô là chỗ hàng gặp cột.",pairs:[["Hàng","Các ô xếp theo chiều ngang"],["Cột","Các ô xếp theo chiều dọc"],["Ô","Chỗ hàng và cột gặp nhau"]]},{id:"th5-chen-bang-hinh-11",type:"number",q:"Bảng thời khoá biểu có 6 hàng và 6 cột. Bảng có bao nhiêu ô?",explain:"Số ô bằng 6 nhân 6, bằng 36.",answer:36,unit:"ô"},{id:"th5-chen-bang-hinh-12",type:"mc",q:"Vì sao nên kéo nút ở góc khi đổi kích thước ảnh?",explain:"Kéo nút ở góc làm ảnh to nhỏ đều cả hai chiều nên không bị méo.",options:["Để ảnh giữ đúng tỉ lệ","Để ảnh đổi sang màu khác","Để ảnh bị xoá khỏi bài","Để chữ trong bài to hơn"],answer:0},{id:"th5-chen-bang-hinh-13",type:"tf",q:"Bảng 2 hàng, 5 cột có nhiều ô hơn bảng 3 hàng, 3 cột.",explain:"Đúng. Bảng thứ nhất có 10 ô, bảng thứ hai có 9 ô.",answer:!0},{id:"th5-chen-bang-hinh-14",type:"mc",q:"Muốn chữ nằm vòng quanh bức ảnh, em cần chọn gì cho ảnh?",explain:"Chọn cách bố trí cho chữ bao quanh ảnh thì chữ sẽ nằm vòng quanh ảnh.",options:["Cỡ chữ to hơn cho bài","Màu đậm hơn cho chữ","Một phông chữ khác hẳn","Cách bố trí chữ bao quanh"],answer:3},{id:"th5-chen-bang-hinh-15",type:"tf",q:"Xoá một cột của bảng 4 hàng, 3 cột thì bảng còn 9 ô.",explain:"Sai. Bảng còn 4 hàng, 2 cột nên có 8 ô.",answer:!1},{id:"th5-chen-bang-hinh-16",type:"order",q:"Sắp xếp các bước chèn ảnh con mèo vào bài văn.",explain:"Đặt con trỏ, chèn ảnh, chọn tệp, rồi mới chỉnh kích thước.",items:["Đặt con trỏ ở chỗ muốn có ảnh","Chọn lệnh chèn ảnh","Tìm và chọn tệp ảnh con mèo","Kéo nút ở góc để chỉnh ảnh vừa ý"]},{id:"th5-chen-bang-hinh-17",type:"multi",q:"Những nội dung nào trình bày bằng bảng sẽ rõ ràng hơn?",explain:"Nội dung có nhiều mục xếp theo hàng, cột thì nên dùng bảng.",options:["Thời khoá biểu của lớp","Kết quả các trận cờ của lớp","Một bài thơ bốn câu","Danh sách tổ và việc trực nhật","Lời mời dự sinh nhật"],answers:[0,1,3]},{id:"th5-chen-bang-hinh-18",type:"fill",q:"Điền từ còn thiếu: Muốn ảnh không bị méo khi to nhỏ, em kéo nút ở … ảnh.",explain:"Kéo nút ở góc giúp ảnh giữ đúng tỉ lệ.",answer:["góc"]}]},{questions:[{id:"th5-chen-bang-hinh-19",type:"number",q:"An lập bảng có một hàng tiêu đề và mỗi bạn trong tổ một hàng. Tổ có 5 bạn. Bảng có bao nhiêu hàng?",explain:"Có 5 hàng cho 5 bạn và 1 hàng tiêu đề, tất cả là 6 hàng.",answer:6,unit:"hàng"},{id:"th5-chen-bang-hinh-20",type:"tf",q:"Bình kéo nút ở cạnh bên của ảnh ra thật xa. Ảnh có thể bị kéo dài, trông méo đi.",explain:"Đúng. Kéo nút ở cạnh chỉ làm ảnh dài ra một chiều nên dễ bị méo.",answer:!0},{id:"th5-chen-bang-hinh-21",type:"mc",q:"Bảng danh sách của Chi mỗi bạn ghi một hàng. Lớp có thêm một bạn mới. Chi nên làm gì?",explain:"Thêm một hàng để ghi tên bạn mới, bảng vẫn gọn gàng.",options:["Xoá bảng rồi vẽ lại","Gõ tên bạn ra ngoài bảng","Thêm một hàng vào bảng","Chèn thêm một bức ảnh"],answer:2},{id:"th5-chen-bang-hinh-22",type:"tf",q:"Minh muốn bảng có 20 ô. Bảng 4 hàng, 6 cột là vừa đủ.",explain:"Sai. Bảng 4 hàng, 6 cột có 24 ô; bảng 4 hàng, 5 cột mới có 20 ô.",answer:!1},{id:"th5-chen-bang-hinh-23",type:"multi",q:"Hà làm bài giới thiệu loài hoa có ảnh. Những việc nào giúp bài đẹp, dễ đọc?",explain:"Ảnh vừa phải, đúng chỗ và có ghi nguồn giúp bài đẹp và đúng mực.",options:["Chỉnh ảnh vừa phải bằng nút ở góc","Kéo méo ảnh cho thật lạ mắt","Đặt ảnh gần đoạn nói về hoa đó","Chèn thật nhiều ảnh giống nhau","Ghi nguồn nếu ảnh lấy từ mạng"],answers:[0,2,4]},{id:"th5-chen-bang-hinh-24",type:"mc",q:"Dũng chèn ảnh nhưng ảnh to quá, chiếm gần hết trang. Dũng nên làm gì?",explain:"Kéo nút ở góc vào trong để ảnh nhỏ lại mà không méo.",options:["Xoá hết chữ trong bài","Kéo nút ở góc để thu nhỏ","Kéo nút ở cạnh cho bẹp","Đổi màu chữ cho nổi bật"],answer:1},{id:"th5-chen-bang-hinh-25",type:"match",q:"Ghép điều cần làm với cách làm.",explain:"Mỗi việc cần một cách làm phù hợp.",pairs:[["Ảnh nhỏ quá","Kéo nút ở góc ra ngoài"],["Bảng thiếu một hàng","Thêm hàng"],["Bảng thừa một cột","Xoá cột"],["Muốn chữ bao quanh ảnh","Chọn cách bố trí chữ"]]},{id:"th5-chen-bang-hinh-26",type:"tf",q:"Khoa chèn ảnh xong vẫn có thể kéo ảnh sang vị trí khác trong bài.",explain:"Đúng. Em có thể chọn ảnh rồi kéo sang chỗ khác.",answer:!0},{id:"th5-chen-bang-hinh-27",type:"number",q:"Bảng của Ngọc có 4 hàng, 5 cột. Ngọc thêm 1 hàng nữa. Bảng mới có bao nhiêu ô?",explain:"Bảng mới có 5 hàng, 5 cột: 5 nhân 5 bằng 25 ô.",answer:25,unit:"ô"}]}],challenge:{questions:[{id:"th5-chen-bang-hinh-28",type:"number",q:"Thảo lập bảng điểm 3 môn của 8 bạn, có thêm một hàng tiêu đề và một cột ghi tên. Bảng có bao nhiêu ô?",explain:"Bảng có 9 hàng và 4 cột, nên có 9 nhân 4 bằng 36 ô.",answer:36,unit:"ô"},{id:"th5-chen-bang-hinh-21",type:"mc",q:"Bảng danh sách của Chi mỗi bạn ghi một hàng. Lớp có thêm một bạn mới. Chi nên làm gì?",explain:"Thêm một hàng để ghi tên bạn mới, bảng vẫn gọn gàng.",options:["Xoá bảng rồi vẽ lại","Gõ tên bạn ra ngoài bảng","Thêm một hàng vào bảng","Chèn thêm một bức ảnh"],answer:2},{id:"th5-chen-bang-hinh-29",type:"mc",q:"Phúc kéo nút ở cạnh trên của ảnh lên cao. Điều gì dễ xảy ra?",explain:"Kéo nút ở cạnh chỉ kéo ảnh theo một chiều nên ảnh dễ bị méo.",options:["Ảnh bị kéo dài, méo đi","Ảnh giữ nguyên tỉ lệ","Ảnh tự chuyển thành bảng","Chữ trong bài bị xoá"],answer:0},{id:"th5-chen-bang-hinh-23",type:"multi",q:"Hà làm bài giới thiệu loài hoa có ảnh. Những việc nào giúp bài đẹp, dễ đọc?",explain:"Ảnh vừa phải, đúng chỗ và có ghi nguồn giúp bài đẹp và đúng mực.",options:["Chỉnh ảnh vừa phải bằng nút ở góc","Kéo méo ảnh cho thật lạ mắt","Đặt ảnh gần đoạn nói về hoa đó","Chèn thật nhiều ảnh giống nhau","Ghi nguồn nếu ảnh lấy từ mạng"],answers:[0,2,4]},{id:"th5-chen-bang-hinh-30",type:"number",q:"Vy có bảng 5 hàng, 4 cột. Vy xoá 1 hàng và thêm 1 cột. Bảng mới có bao nhiêu ô?",explain:"Bảng mới có 4 hàng, 5 cột: 4 nhân 5 bằng 20 ô.",answer:20,unit:"ô"},{id:"th5-chen-bang-hinh-25",type:"match",q:"Ghép điều cần làm với cách làm.",explain:"Mỗi việc cần một cách làm phù hợp.",pairs:[["Ảnh nhỏ quá","Kéo nút ở góc ra ngoài"],["Bảng thiếu một hàng","Thêm hàng"],["Bảng thừa một cột","Xoá cột"],["Muốn chữ bao quanh ảnh","Chọn cách bố trí chữ"]]},{id:"th5-chen-bang-hinh-22",type:"tf",q:"Minh muốn bảng có 20 ô. Bảng 4 hàng, 6 cột là vừa đủ.",explain:"Sai. Bảng 4 hàng, 6 cột có 24 ô; bảng 4 hàng, 5 cột mới có 20 ô.",answer:!1}]},summary:["Chèn ảnh: đặt con trỏ ở chỗ muốn có ảnh rồi chọn tệp ảnh; kéo nút ở góc để ảnh không bị méo.","Bảng gồm hàng và cột; chỗ hàng gặp cột là một ô, số ô bằng số hàng nhân số cột.","Bảng giúp trình bày thời khoá biểu, danh sách gọn gàng, dễ đọc."]},{id:"th5-sao-chep-di-chuyen-doan",title:"Bài 12: Sao chép, di chuyển và tìm kiếm trong văn bản",weeks:[22,23],learn:[{title:"Sao chép",text:"Chọn phần văn bản, nhấn Ctrl + C để sao chép, đặt con trỏ ở chỗ mới rồi nhấn Ctrl + V để dán. Phần văn bản ở chỗ cũ vẫn còn.",example:"Ctrl + C → Ctrl + V · 📄 → 📄📄"},{title:"Di chuyển",text:"Chọn phần văn bản, nhấn Ctrl + X để cắt, đặt con trỏ ở chỗ mới rồi nhấn Ctrl + V. Phần đó rời chỗ cũ, sang chỗ mới.",example:"Ctrl + X → Ctrl + V · 📄 ➡️ 📄"},{title:"Hoàn tác",text:"Lỡ làm sai, em nhấn Ctrl + Z để quay lại bước vừa làm.",example:"Ctrl + Z ↩️"},{title:"Tìm và thay thế",text:"Lệnh tìm kiếm giúp tìm nhanh một từ trong bài. Lệnh thay thế giúp đổi một từ thành từ khác, có thể đổi ở mọi chỗ cùng lúc.",example:"🔍 tìm “mèo” · 🔁 “mèo” → “thỏ”"}],practice:[{questions:[{id:"th5-sao-chep-di-chuyen-doan-01",type:"mc",q:"Tổ hợp phím nào dùng để sao chép phần văn bản đã chọn?",emoji:"📄",explain:"Ctrl + C dùng để sao chép.",options:["Ctrl + X","Ctrl + V","Ctrl + Z","Ctrl + C"],answer:3},{id:"th5-sao-chep-di-chuyen-doan-02",type:"mc",q:"Tổ hợp phím nào dùng để dán phần văn bản đã sao chép hoặc đã cắt?",explain:"Ctrl + V dùng để dán.",options:["Ctrl + Z","Ctrl + C","Ctrl + V","Ctrl + X"],answer:2},{id:"th5-sao-chep-di-chuyen-doan-03",type:"tf",q:"Nhấn Ctrl + X sẽ cắt phần văn bản đã chọn ra khỏi chỗ cũ.",emoji:"✂️",explain:"Đúng. Ctrl + X cắt phần đã chọn, sau đó em dán ở chỗ mới.",answer:!0},{id:"th5-sao-chep-di-chuyen-doan-04",type:"tf",q:"Sau khi sao chép bằng Ctrl + C, phần văn bản ở chỗ cũ sẽ bị mất.",explain:"Sai. Sao chép thì phần ở chỗ cũ vẫn còn nguyên.",answer:!1},{id:"th5-sao-chep-di-chuyen-doan-05",type:"mc",q:"Lỡ xoá nhầm một câu, em nhấn tổ hợp phím nào để lấy lại?",explain:"Ctrl + Z hoàn tác, đưa câu vừa xoá trở lại.",options:["Ctrl + V","Ctrl + Z","Ctrl + C","Ctrl + X"],answer:1},{id:"th5-sao-chep-di-chuyen-doan-06",type:"match",q:"Ghép tổ hợp phím với công việc.",explain:"Đây là các tổ hợp phím thường dùng khi soạn thảo văn bản.",pairs:[["Ctrl + C","Sao chép"],["Ctrl + X","Cắt"],["Ctrl + V","Dán"],["Ctrl + Z","Hoàn tác"]]},{id:"th5-sao-chep-di-chuyen-doan-07",type:"tf",q:"Muốn sao chép hay di chuyển một đoạn văn, em phải chọn đoạn văn đó trước.",explain:"Đúng. Phần mềm chỉ sao chép hoặc cắt phần đang được chọn.",answer:!0},{id:"th5-sao-chep-di-chuyen-doan-08",type:"mc",q:"Lệnh nào giúp em tìm nhanh một từ trong bài văn dài?",emoji:"🔍",explain:"Lệnh tìm kiếm chỉ ra những chỗ có từ em cần tìm.",options:["Lệnh tìm kiếm","Lệnh in đậm","Lệnh chèn ảnh","Lệnh căn giữa"],answer:0},{id:"th5-sao-chep-di-chuyen-doan-09",type:"tf",q:"Lệnh tìm kiếm sẽ tự sửa hết lỗi chính tả trong bài.",explain:"Sai. Lệnh tìm kiếm chỉ giúp tìm từ, không tự sửa bài.",answer:!1}]},{questions:[{id:"th5-sao-chep-di-chuyen-doan-10",type:"mc",q:"Sao chép và di chuyển một đoạn văn khác nhau ở điểm nào?",explain:"Sao chép thì chỗ cũ vẫn còn, di chuyển thì đoạn văn rời khỏi chỗ cũ.",options:["Di chuyển giữ lại đoạn ở chỗ cũ","Sao chép xoá đoạn ở chỗ cũ","Hai việc này hoàn toàn giống nhau","Sao chép giữ lại đoạn ở chỗ cũ"],answer:3},{id:"th5-sao-chep-di-chuyen-doan-11",type:"order",q:"Sắp xếp các bước di chuyển một câu sang đoạn khác.",explain:"Chọn, cắt, đặt con trỏ ở chỗ mới rồi dán.",items:["Chọn câu cần di chuyển","Nhấn Ctrl + X","Đặt con trỏ ở chỗ mới","Nhấn Ctrl + V"]},{id:"th5-sao-chep-di-chuyen-doan-12",type:"tf",q:"Sau khi nhấn Ctrl + C, em có thể nhấn Ctrl + V nhiều lần để dán ở nhiều chỗ.",explain:"Đúng. Phần đã sao chép có thể dán nhiều lần.",answer:!0},{id:"th5-sao-chep-di-chuyen-doan-13",type:"mc",q:"Muốn đưa một câu từ đầu bài xuống cuối bài, không giữ ở chỗ cũ, em dùng cách nào?",explain:"Cắt rồi dán là di chuyển, câu không còn ở chỗ cũ.",options:["Sao chép rồi dán","Tìm kiếm","Cắt rồi dán","Hoàn tác"],answer:2},{id:"th5-sao-chep-di-chuyen-doan-14",type:"mc",q:"Lan dùng lệnh thay thế, đổi “bạn Nam” thành “bạn Minh” ở tất cả các chỗ. Kết quả là gì?",explain:"Thay thế tất cả sẽ đổi mọi chỗ có “bạn Nam” thành “bạn Minh”.",options:["Chỉ chỗ đầu tiên được đổi","Mọi chỗ “bạn Nam” đều đổi","Bài văn bị xoá hết chữ","Chữ “bạn Nam” in đậm lên"],answer:1},{id:"th5-sao-chep-di-chuyen-doan-15",type:"tf",q:"Lệnh tìm kiếm chỉ giúp tìm từ, không làm thay đổi chữ trong bài.",explain:"Đúng. Muốn đổi chữ thì dùng lệnh thay thế.",answer:!0},{id:"th5-sao-chep-di-chuyen-doan-16",type:"multi",q:"Những việc nào cần chọn phần văn bản trước khi làm?",explain:"Hoàn tác chỉ quay lại bước vừa làm nên không cần chọn trước.",options:["Sao chép bằng Ctrl + C","Cắt bằng Ctrl + X","Hoàn tác bằng Ctrl + Z","In đậm một từ"],answers:[0,1,3]},{id:"th5-sao-chep-di-chuyen-doan-17",type:"tf",q:"Cắt một đoạn văn bằng Ctrl + X rồi dán ở chỗ mới thì đoạn văn có ở cả chỗ cũ và chỗ mới.",explain:"Sai. Cắt rồi dán là di chuyển, đoạn văn chỉ còn ở chỗ mới.",answer:!1},{id:"th5-sao-chep-di-chuyen-doan-18",type:"fill",q:"Điền từ còn thiếu: Ctrl + C để sao chép, còn Ctrl + V để … .",explain:"Ctrl + V dùng để dán phần đã sao chép hoặc đã cắt.",answer:["dán"]}]},{questions:[{id:"th5-sao-chep-di-chuyen-doan-19",type:"mc",q:"Bình gõ bài thơ 4 khổ, khổ nào cũng có câu “Quê hương ơi!”. Cách nhanh nhất để có câu này ở mỗi khổ là gì?",explain:"Sao chép một lần rồi dán nhiều lần nhanh hơn gõ lại.",options:["Gõ một lần rồi sao chép, dán","Gõ lại từng chữ ở mỗi khổ","Cắt câu đó rồi dán ở khổ cuối","Tìm kiếm câu đó trên mạng"],answer:0},{id:"th5-sao-chep-di-chuyen-doan-20",type:"tf",q:"Chi lỡ cắt mất một đoạn văn. Chi nhấn Ctrl + Z thì đoạn văn quay lại chỗ cũ.",explain:"Đúng. Ctrl + Z hoàn tác việc cắt vừa làm.",answer:!0},{id:"th5-sao-chep-di-chuyen-doan-21",type:"mc",q:"Minh gõ nhầm tên “Ngọc Anh” thành “Ngọc An” ở 10 chỗ. Cách sửa nhanh nhất là gì?",explain:"Thay thế tất cả sửa cả 10 chỗ cùng một lúc.",options:["Xoá cả bài rồi gõ lại","Tìm từng chỗ để in đậm","Sao chép tên đúng 1 lần","Dùng lệnh thay thế tất cả"],answer:3},{id:"th5-sao-chep-di-chuyen-doan-22",type:"tf",q:"Dũng muốn chuyển đoạn kết lên đầu bài. Dũng chỉ dùng Ctrl + C rồi Ctrl + V là xong.",explain:"Sai. Sao chép sẽ làm đoạn kết có ở hai chỗ; Dũng cần cắt bằng Ctrl + X rồi dán.",answer:!1},{id:"th5-sao-chep-di-chuyen-doan-23",type:"multi",q:"Khoa muốn chuyển đoạn 3 lên trước đoạn 2 theo cách gọn nhất. Khoa dùng những tổ hợp phím nào?",explain:"Cắt đoạn 3 bằng Ctrl + X rồi dán trước đoạn 2 bằng Ctrl + V.",options:["Ctrl + X","Ctrl + V","Ctrl + Z","Ctrl + C"],answers:[0,1]},{id:"th5-sao-chep-di-chuyen-doan-24",type:"mc",q:"Hà sao chép một câu nhưng dán nhầm chỗ. Hà nên làm gì trước tiên?",explain:"Ctrl + Z bỏ lần dán nhầm, rồi Hà dán lại đúng chỗ.",options:["Tắt máy tính rồi bật lại","Xoá toàn bộ bài văn","Nhấn Ctrl + Z để hoàn tác","Nhấn Ctrl + C lần nữa"],answer:2},{id:"th5-sao-chep-di-chuyen-doan-25",type:"match",q:"Ghép tình huống với cách làm phù hợp.",explain:"Mỗi tình huống cần một lệnh phù hợp.",pairs:[["Câu cần có ở nhiều chỗ","Sao chép rồi dán"],["Câu đặt sai vị trí","Cắt rồi dán"],["Lỡ xoá nhầm","Hoàn tác"],["Muốn biết từ “sông” ở đâu","Tìm kiếm"]]},{id:"th5-sao-chep-di-chuyen-doan-26",type:"tf",q:"Ngọc dùng lệnh tìm kiếm từ “mưa”. Phần mềm sẽ chỉ ra những chỗ có từ “mưa” trong bài.",emoji:"🌧️",explain:"Đúng. Lệnh tìm kiếm giúp tìm nhanh các chỗ có từ cần tìm.",answer:!0},{id:"th5-sao-chep-di-chuyen-doan-27",type:"number",q:"Bài văn có 3 chỗ ghi “hoa hồng”. Nam sao chép một câu trong bài chứa đúng một chỗ “hoa hồng” rồi dán thêm 2 lần. Bài có bao nhiêu chỗ “hoa hồng”?",explain:"Sao chép không làm mất chỗ cũ, dán 2 lần thêm 2 chỗ: 3 cộng 2 bằng 5.",answer:5,unit:"chỗ"}]}],challenge:{questions:[{id:"th5-sao-chep-di-chuyen-doan-28",type:"number",q:"Bài có 4 chỗ ghi “con cò”. Thảo cắt một câu chứa đúng một chỗ “con cò” rồi dán xuống cuối bài. Bài còn bao nhiêu chỗ “con cò”?",explain:"Cắt rồi dán chỉ đổi vị trí câu, số chỗ “con cò” vẫn là 4.",answer:4,unit:"chỗ"},{id:"th5-sao-chep-di-chuyen-doan-21",type:"mc",q:"Minh gõ nhầm tên “Ngọc Anh” thành “Ngọc An” ở 10 chỗ. Cách sửa nhanh nhất là gì?",explain:"Thay thế tất cả sửa cả 10 chỗ cùng một lúc.",options:["Xoá cả bài rồi gõ lại","Tìm từng chỗ để in đậm","Sao chép tên đúng 1 lần","Dùng lệnh thay thế tất cả"],answer:3},{id:"th5-sao-chep-di-chuyen-doan-29",type:"mc",q:"Tùng dùng thay thế tất cả để đổi “sông” thành “suối”, nhưng chỉ cần đổi một chỗ. Tùng nên làm gì ngay?",explain:"Ctrl + Z hoàn tác lần thay thế, rồi Tùng chỉ sửa đúng một chỗ.",options:["Gõ lại cả bài từ đầu","Nhấn Ctrl + Z để hoàn tác","Nhấn Ctrl + V nhiều lần","Lưu bài rồi tắt máy"],answer:1},{id:"th5-sao-chep-di-chuyen-doan-22",type:"tf",q:"Dũng muốn chuyển đoạn kết lên đầu bài. Dũng chỉ dùng Ctrl + C rồi Ctrl + V là xong.",explain:"Sai. Sao chép sẽ làm đoạn kết có ở hai chỗ; Dũng cần cắt bằng Ctrl + X rồi dán.",answer:!1},{id:"th5-sao-chep-di-chuyen-doan-30",type:"order",q:"Sắp xếp các bước sao chép câu “Em yêu trường em.” xuống cuối bài.",explain:"Chọn câu, sao chép, đặt con trỏ ở chỗ mới rồi dán.",items:["Chọn câu “Em yêu trường em.”","Nhấn Ctrl + C","Đặt con trỏ ở cuối bài","Nhấn Ctrl + V"]},{id:"th5-sao-chep-di-chuyen-doan-23",type:"multi",q:"Khoa muốn chuyển đoạn 3 lên trước đoạn 2 theo cách gọn nhất. Khoa dùng những tổ hợp phím nào?",explain:"Cắt đoạn 3 bằng Ctrl + X rồi dán trước đoạn 2 bằng Ctrl + V.",options:["Ctrl + X","Ctrl + V","Ctrl + Z","Ctrl + C"],answers:[0,1]},{id:"th5-sao-chep-di-chuyen-doan-25",type:"match",q:"Ghép tình huống với cách làm phù hợp.",explain:"Mỗi tình huống cần một lệnh phù hợp.",pairs:[["Câu cần có ở nhiều chỗ","Sao chép rồi dán"],["Câu đặt sai vị trí","Cắt rồi dán"],["Lỡ xoá nhầm","Hoàn tác"],["Muốn biết từ “sông” ở đâu","Tìm kiếm"]]}]},summary:["Sao chép: Ctrl + C rồi Ctrl + V, chỗ cũ vẫn còn. Di chuyển: Ctrl + X rồi Ctrl + V, chỗ cũ không còn.","Lỡ làm sai, em nhấn Ctrl + Z để hoàn tác.","Lệnh tìm kiếm giúp tìm nhanh một từ, lệnh thay thế giúp đổi từ đó ở nhiều chỗ cùng lúc."]}]},{id:"lap-trinh-khoi-lenh",title:"Giải quyết vấn đề với sự trợ giúp của máy tính",lessons:[{id:"th5-bien",title:"Bài 13: Biến trong chương trình",weeks:[24,26],learn:[{title:"Biến là gì?",text:"Biến giống như một chiếc hộp có tên, dùng để lưu một giá trị. Giá trị trong hộp có thể thay đổi khi chương trình chạy.",example:"📦 điểm = 0"},{title:"Tạo biến và đặt giá trị",text:"Em tạo biến và đặt tên dễ hiểu, như “điểm”. Khối “đặt điểm thành 0” cho biến điểm giá trị 0, thường dùng lúc bắt đầu chương trình.",example:"📦 điểm ← 0"},{title:"Thay đổi giá trị",text:"Khối “thay đổi điểm một lượng 1” cộng thêm 1 vào giá trị đang có. Nếu điểm đang là 3 thì sau khối này điểm bằng 4.",example:"3 ➕ 1 = 4"},{title:"Hiện biến trên sân khấu",text:"Khối “hiện biến điểm” cho giá trị của biến xuất hiện trên sân khấu. Biến thường dùng để tính điểm, đếm số lần hoặc đếm thời gian.",example:"🏆 điểm: 5"}],practice:[{questions:[{id:"th5-bien-01",type:"mc",q:"Trong chương trình, biến giống như vật gì?",emoji:"📦",explain:"Biến giống một chiếc hộp có tên, dùng để lưu một giá trị có thể thay đổi.",options:["Một nhân vật đứng trên sân khấu","Một phông nền phía sau sân khấu","Một chiếc hộp có tên để lưu giá trị","Một nút bấm để dừng chương trình"],answer:2},{id:"th5-bien-02",type:"tf",q:"Giá trị của biến có thể thay đổi khi chương trình chạy.",explain:"Đúng. Ví dụ biến điểm tăng dần mỗi khi người chơi ghi điểm.",answer:!0},{id:"th5-bien-03",type:"mc",q:"Khối nào làm cho biến điểm có giá trị bằng 0?",explain:"Khối “đặt điểm thành 0” cho biến điểm giá trị 0.",options:["“đặt điểm thành 0”","“thay đổi điểm một lượng 1”","“hiện biến điểm”","“di chuyển 0 bước”"],answer:0},{id:"th5-bien-04",type:"tf",q:"Khối “thay đổi điểm một lượng 1” làm điểm luôn trở về 1.",explain:"Sai. Khối này cộng thêm 1 vào giá trị đang có của điểm.",answer:!1},{id:"th5-bien-05",type:"mc",q:"Khối “hiện biến điểm” dùng để làm gì?",emoji:"🏆",explain:"Khối này cho giá trị của biến điểm hiện lên sân khấu.",options:["Xóa biến điểm khỏi chương trình","Cho điểm hiện lên sân khấu","Đổi tên biến điểm thành tên khác"],answer:1},{id:"th5-bien-06",type:"fill",q:"Điền một từ: Mỗi biến có một … riêng để phân biệt với các biến khác.",explain:"Mỗi biến có một tên riêng; nhờ có tên, chương trình biết đang dùng biến nào.",answer:["tên"]},{id:"th5-bien-07",type:"mc",q:"Tên biến nào dễ hiểu nhất để lưu số điểm của trò chơi?",explain:"Tên “điểm” cho biết ngay biến dùng để lưu điểm.",options:["x1","abc","điểm","biến 1"],answer:2},{id:"th5-bien-08",type:"tf",q:"Biến chỉ dùng để lưu điểm, không thể dùng để đếm số lần.",explain:"Sai. Biến có thể lưu điểm, đếm số lần, đếm thời gian và nhiều việc khác.",answer:!1},{id:"th5-bien-09",type:"match",q:"Ghép khối lệnh với việc nó làm.",explain:"Mỗi khối lệnh về biến có một tác dụng riêng.",pairs:[["đặt điểm thành 0","Cho điểm bằng 0"],["thay đổi điểm một lượng 1","Cộng thêm 1 vào điểm"],["hiện biến điểm","Điểm hiện trên sân khấu"],["ẩn biến điểm","Điểm không hiện trên sân khấu"]]}]},{questions:[{id:"th5-bien-10",type:"number",q:"Điểm đang bằng 3. Chương trình chạy khối “thay đổi điểm một lượng 1”. Điểm bằng bao nhiêu?",explain:"Cộng thêm 1 vào điểm đang có: 3 + 1 = 4.",answer:4},{id:"th5-bien-11",type:"number",q:"Điểm đang bằng 7. Chương trình chạy khối “đặt điểm thành 0”. Điểm bằng bao nhiêu?",explain:"Khối “đặt … thành 0” thay giá trị cũ bằng 0, nên điểm bằng 0.",answer:0},{id:"th5-bien-12",type:"tf",q:"Khối “đặt điểm thành 5” và khối “thay đổi điểm một lượng 5” luôn cho cùng một kết quả.",explain:"Sai. Khối “đặt” làm điểm bằng 5, còn khối “thay đổi” cộng thêm 5 vào điểm đang có.",answer:!1},{id:"th5-bien-13",type:"mc",q:"Vì sao đầu chương trình trò chơi thường có khối “đặt điểm thành 0”?",explain:"Đặt điểm thành 0 lúc bắt đầu để mỗi lần chơi đều tính điểm lại từ đầu.",options:["Để nhân vật chạy nhanh hơn lúc đầu","Để mỗi lần chơi, điểm bắt đầu từ 0","Để phông nền đổi sang màu khác","Để tắt âm thanh khi bắt đầu chơi"],answer:1},{id:"th5-bien-14",type:"number",q:"Chương trình: “đặt điểm thành 2”, rồi “thay đổi điểm một lượng 3”. Điểm bằng bao nhiêu?",explain:"Điểm bắt đầu là 2, cộng thêm 3: 2 + 3 = 5.",answer:5},{id:"th5-bien-15",type:"order",q:"Sắp xếp các bước dùng biến để đếm số lần nhân vật nhảy.",explain:"Tạo biến trước, đặt về 0 khi bắt đầu, mỗi lần nhảy cộng 1, rồi xem kết quả.",items:["Tạo biến mới tên là “số lần”","Đặt số lần thành 0 khi bắt đầu","Mỗi lần nhảy, thay đổi số lần một lượng 1","Xem giá trị số lần trên sân khấu"]},{id:"th5-bien-16",type:"tf",q:"Đặt tên biến là “điểm” dễ hiểu hơn đặt tên là “a”.",explain:"Đúng. Tên rõ nghĩa giúp em và bạn đọc chương trình dễ hơn.",answer:!0},{id:"th5-bien-17",type:"multi",q:"Những việc nào nên dùng biến?",emoji:"🍎",explain:"Đếm táo, lưu điểm, đếm giây đều cần lưu một giá trị thay đổi; bấm lá cờ xanh thì không cần biến.",options:["Đếm số quả táo nhân vật ăn được","Lưu số điểm của người chơi","Đếm số giây còn lại của lượt chơi","Bấm lá cờ xanh để chạy chương trình"],answers:[0,1,2]},{id:"th5-bien-18",type:"number",q:"Chương trình: “đặt điểm thành 0”, rồi chạy ba lần khối “thay đổi điểm một lượng 1”. Điểm bằng bao nhiêu?",explain:"Mỗi lần cộng 1: 0 + 1 + 1 + 1 = 3.",answer:3}]},{questions:[{id:"th5-bien-19",type:"number",q:"Chương trình: “đặt điểm thành 0”; “lặp lại 3 lần”: “thay đổi điểm một lượng 2”. Điểm bằng bao nhiêu?",explain:"Lặp 3 lần, mỗi lần cộng 2: 0 + 3 × 2 = 6.",answer:6},{id:"th5-bien-20",type:"number",q:"Chương trình: “đặt điểm thành 10”; “lặp lại 4 lần”: “thay đổi điểm một lượng 5”. Điểm bằng bao nhiêu?",explain:"Bắt đầu từ 10, cộng 4 lần 5: 10 + 4 × 5 = 30.",answer:30},{id:"th5-bien-21",type:"mc",q:"An làm trò chơi bắt táo. Mỗi lần mèo chạm quả táo, An muốn điểm tăng thêm 1. An dùng khối nào?",emoji:"🍎",explain:"Khối “thay đổi điểm một lượng 1” cộng thêm 1 vào điểm mỗi lần chạm táo.",options:["“thay đổi điểm một lượng 10”","“đặt điểm thành 1”","“thay đổi điểm một lượng 1”","“đặt điểm thành 10”"],answer:2},{id:"th5-bien-22",type:"tf",q:"Bình quên khối “đặt điểm thành 0” ở đầu chương trình. Khi chơi lại, điểm có thể cộng tiếp từ điểm của lần chơi trước.",explain:"Đúng. Biến vẫn giữ giá trị cũ nếu không được đặt lại về 0.",answer:!0},{id:"th5-bien-23",type:"number",q:"Chương trình: “đặt quãng đường thành 0”; “lặp lại 5 lần”: “di chuyển 10 bước”, “thay đổi quãng đường một lượng 10”. Biến quãng đường bằng bao nhiêu?",explain:"Mỗi lần lặp cộng 10, lặp 5 lần: 5 × 10 = 50.",answer:50},{id:"th5-bien-24",type:"mc",q:"Trò chơi đố vui: mỗi câu trả lời đúng được cộng 2 điểm. Dũng bắt đầu từ 0 điểm và trả lời đúng 4 câu. Điểm cuối cùng của Dũng là bao nhiêu?",explain:"Bốn câu đúng, mỗi câu 2 điểm: 4 × 2 = 8 điểm.",options:["4 điểm","6 điểm","8 điểm","2 điểm"],answer:2},{id:"th5-bien-25",type:"order",q:"Sắp xếp chương trình để điểm bắt đầu từ 0, rồi tăng 3 lần, mỗi lần 1 điểm.",explain:"Khối sự kiện ở trên cùng, đặt điểm về 0, rồi khối lặp chứa lệnh cộng điểm.",items:["khi bấm vào lá cờ xanh","đặt điểm thành 0","lặp lại 3 lần","thay đổi điểm một lượng 1 (trong khối lặp)"]},{id:"th5-bien-26",type:"tf",q:"Chương trình: “đặt điểm thành 0”; “lặp lại 2 lần”: “thay đổi điểm một lượng 4”. Sau khi chạy, điểm bằng 6.",explain:"Sai. Hai lần cộng 4: 2 × 4 = 8, nên điểm bằng 8.",answer:!1},{id:"th5-bien-27",type:"multi",q:"Điểm đang bằng 0. Những cách nào làm điểm bằng 3?",explain:"Ba cách đầu đều cho điểm bằng 3; cách cuối cho 3 × 3 = 9.",options:["đặt điểm thành 3","thay đổi điểm một lượng 3","lặp lại 3 lần: thay đổi điểm một lượng 1","lặp lại 3 lần: thay đổi điểm một lượng 3"],answers:[0,1,2]}]}],challenge:{questions:[{id:"th5-bien-19",type:"number",q:"Chương trình: “đặt điểm thành 0”; “lặp lại 3 lần”: “thay đổi điểm một lượng 2”. Điểm bằng bao nhiêu?",explain:"Lặp 3 lần, mỗi lần cộng 2: 0 + 3 × 2 = 6.",answer:6},{id:"th5-bien-22",type:"tf",q:"Bình quên khối “đặt điểm thành 0” ở đầu chương trình. Khi chơi lại, điểm có thể cộng tiếp từ điểm của lần chơi trước.",explain:"Đúng. Biến vẫn giữ giá trị cũ nếu không được đặt lại về 0.",answer:!0},{id:"th5-bien-26",type:"tf",q:"Chương trình: “đặt điểm thành 0”; “lặp lại 2 lần”: “thay đổi điểm một lượng 4”. Sau khi chạy, điểm bằng 6.",explain:"Sai. Hai lần cộng 4: 2 × 4 = 8, nên điểm bằng 8.",answer:!1},{id:"th5-bien-27",type:"multi",q:"Điểm đang bằng 0. Những cách nào làm điểm bằng 3?",explain:"Ba cách đầu đều cho điểm bằng 3; cách cuối cho 3 × 3 = 9.",options:["đặt điểm thành 3","thay đổi điểm một lượng 3","lặp lại 3 lần: thay đổi điểm một lượng 1","lặp lại 3 lần: thay đổi điểm một lượng 3"],answers:[0,1,2]},{id:"th5-bien-28",type:"number",q:"Chương trình: “đặt điểm thành 5”; “lặp lại 3 lần”: “thay đổi điểm một lượng 2”; sau đó “đặt điểm thành 1”; rồi “thay đổi điểm một lượng 4”. Điểm cuối cùng bằng bao nhiêu?",explain:"Sau khối lặp điểm là 5 + 6 = 11, nhưng khối “đặt điểm thành 1” làm điểm về 1, cộng 4 được 5.",answer:5},{id:"th5-bien-29",type:"number",q:"Chương trình: “đặt điểm thành 0”; “lặp lại 4 lần”: “thay đổi điểm một lượng 3”; sau khối lặp có thêm “thay đổi điểm một lượng 2”. Điểm bằng bao nhiêu?",explain:"Khối lặp cộng 4 × 3 = 12, thêm 2 nữa: 12 + 2 = 14.",answer:14},{id:"th5-bien-30",type:"number",q:"Chương trình: “lặp lại 5 lần”, bên trong có “đặt điểm thành 0” rồi “thay đổi điểm một lượng 1”. Sau khi chạy, điểm bằng bao nhiêu?",explain:"Mỗi lần lặp, điểm bị đặt lại thành 0 rồi mới cộng 1, nên cuối cùng điểm chỉ bằng 1.",answer:1}]},summary:["Biến là chiếc hộp có tên, lưu một giá trị có thể thay đổi khi chương trình chạy.","Khối “đặt … thành” thay giá trị mới, khối “thay đổi … một lượng” cộng thêm vào giá trị đang có.","Nên đặt biến về 0 khi bắt đầu và đặt tên biến dễ hiểu."]},{id:"th5-lap",title:"Bài 14: Cấu trúc lặp",weeks:[27,29],learn:[{title:"Lặp với số lần biết trước",text:"Khối “lặp lại 10 lần” chạy các lệnh bên trong đúng 10 lần. Em dùng khối này khi biết trước cần làm bao nhiêu lần.",example:"🔁 × 10"},{title:"Lặp liên tục",text:"Khối “liên tục” chạy các lệnh bên trong mãi mãi, cho đến khi em bấm nút đỏ để dừng. Khối này dùng cho việc cần làm suốt trò chơi.",example:"♾️ liên tục"},{title:"Lặp đến khi có điều kiện",text:"Khối “lặp lại cho đến khi …” chạy các lệnh bên trong cho đến khi điều kiện đúng thì thôi. Ví dụ: lặp lại cho đến khi chạm vào cạnh.",example:"🔁 … cho đến khi 🧱"},{title:"Vẽ hình bằng lệnh lặp",text:"Hình vuông: lặp lại 4 lần, mỗi lần đi rồi xoay 90 độ. Hình tam giác đều: lặp lại 3 lần, mỗi lần đi rồi xoay 120 độ. Khi vẽ xong một hình, tổng các góc xoay là 360 độ.",example:"⬜ 4 × 90° · 🔺 3 × 120°"}],practice:[{questions:[{id:"th5-lap-01",type:"mc",q:"Khối nào chạy các lệnh bên trong mãi mãi, cho đến khi em bấm nút đỏ?",emoji:"♾️",explain:"Khối “liên tục” lặp mãi, chỉ dừng khi em dừng chương trình.",options:["“lặp lại 10 lần”","“liên tục”","“lặp lại 100 lần”","“đợi 1 giây”"],answer:1},{id:"th5-lap-02",type:"tf",q:"Khối “lặp lại 5 lần” chạy các lệnh bên trong đúng 5 lần.",explain:"Đúng. Số trong khối cho biết các lệnh bên trong chạy mấy lần.",answer:!0},{id:"th5-lap-03",type:"tf",q:"Khối “liên tục” tự dừng lại sau 10 lần lặp.",explain:"Sai. Khối “liên tục” lặp mãi cho đến khi chương trình bị dừng.",answer:!1},{id:"th5-lap-04",type:"mc",q:"Khối “lặp lại cho đến khi chạm vào cạnh” dừng lặp khi nào?",emoji:"🧱",explain:"Khối này lặp cho đến khi điều kiện “chạm vào cạnh” đúng thì thôi.",options:["Khi nhân vật chạm vào cạnh","Khi đã lặp đúng 10 lần","Khi nhân vật nói xong","Ngay sau lần lặp đầu tiên"],answer:0},{id:"th5-lap-05",type:"fill",q:"Điền số: Khi vẽ hình vuông bằng lệnh lặp, mỗi lần lặp nhân vật xoay … độ.",emoji:"⬜",explain:"Hình vuông có 4 góc vuông, mỗi lần xoay 90 độ: 4 × 90 = 360 độ.",answer:["90"]},{id:"th5-lap-06",type:"tf",q:"Lệnh nằm bên trong khối “lặp lại 3 lần” được lặp lại, còn lệnh nằm sau khối đó chỉ chạy một lần.",explain:"Đúng. Chỉ các lệnh bên trong khối lặp mới chạy nhiều lần.",answer:!0},{id:"th5-lap-07",type:"match",q:"Ghép mỗi khối lặp với lúc nên dùng.",explain:"Biết trước số lần thì dùng “lặp lại … lần”, lặp suốt trò chơi thì dùng “liên tục”, chờ một điều kiện thì dùng “lặp lại cho đến khi”.",pairs:[["lặp lại 4 lần","Biết trước số lần cần lặp"],["liên tục","Lặp mãi trong suốt trò chơi"],["lặp lại cho đến khi …","Lặp đến khi điều kiện đúng"]]},{id:"th5-lap-08",type:"mc",q:"Để vẽ hình tam giác đều bằng lệnh lặp, em lặp lại mấy lần?",emoji:"🔺",explain:"Tam giác có 3 cạnh nên lặp lại 3 lần, mỗi lần vẽ một cạnh.",options:["3 lần","4 lần","5 lần","6 lần"],answer:0},{id:"th5-lap-09",type:"tf",q:"Có thể ghép thêm khối lệnh ở ngay bên dưới khối “liên tục” để chạy tiếp sau khi lặp xong.",explain:"Sai. Khối “liên tục” không bao giờ kết thúc nên không ghép được lệnh nào bên dưới nó.",answer:!1}]},{questions:[{id:"th5-lap-10",type:"number",q:"Chương trình: “lặp lại 6 lần”: “di chuyển 15 bước”. Nhân vật đi tất cả bao nhiêu bước?",explain:"Sáu lần, mỗi lần 15 bước: 6 × 15 = 90 bước.",answer:90,unit:"bước"},{id:"th5-lap-11",type:"number",q:"Để vẽ hình tam giác đều, mỗi lần lặp nhân vật cần xoay bao nhiêu độ?",emoji:"🔺",explain:"Ba lần xoay phải đủ một vòng: 360 : 3 = 120 độ.",answer:120,unit:"độ"},{id:"th5-lap-12",type:"mc",q:"Chương trình: “lặp lại 6 lần”: “di chuyển 50 bước”, “xoay 60 độ”. Nhân vật vẽ được hình gì?",explain:"Lặp 6 lần, mỗi lần một cạnh 50 bước, và 6 × 60 = 360 độ nên hình khép kín, có 6 cạnh bằng nhau.",options:["Hình có 3 cạnh","Hình có 4 cạnh","Hình có 6 cạnh","Hình có 60 cạnh"],answer:2},{id:"th5-lap-13",type:"mc",q:"Nhân vật cần đi qua đi lại suốt trò chơi. Em chọn khối lặp nào?",explain:"Việc làm suốt trò chơi thì dùng khối “liên tục”.",options:["“lặp lại 2 lần”","“lặp lại 10 lần”","“liên tục”"],answer:2},{id:"th5-lap-14",type:"tf",q:"Chương trình: “lặp lại 3 lần”: “di chuyển 100 bước”, “xoay 90 độ”. Nhân vật vẽ đủ một hình vuông.",explain:"Sai. Lặp 3 lần chỉ vẽ được 3 cạnh; hình vuông cần lặp 4 lần.",answer:!1},{id:"th5-lap-15",type:"number",q:"Chương trình: “lặp lại 3 lần”: “di chuyển 40 bước”, “xoay 120 độ”. Nhân vật đã xoay tất cả bao nhiêu độ?",explain:"Ba lần, mỗi lần 120 độ: 3 × 120 = 360 độ, đúng một vòng.",answer:360,unit:"độ"},{id:"th5-lap-16",type:"order",q:"Sắp xếp chương trình: nhân vật đi đến khi chạm cạnh rồi nói “Tới nơi!”.",explain:"Khối sự kiện trên cùng, khối lặp chứa lệnh đi, lệnh nói nằm sau khối lặp.",items:["khi bấm vào lá cờ xanh","lặp lại cho đến khi chạm vào cạnh","di chuyển 5 bước (trong khối lặp)","nói “Tới nơi!” (sau khối lặp)"]},{id:"th5-lap-17",type:"multi",q:"Những việc nào nên dùng khối “lặp lại … lần”?",explain:"Vẽ hình vuông và nhảy 5 lần đều biết trước số lần; hai việc còn lại không biết trước số lần.",options:["Vẽ một hình vuông","Cho nhân vật nhảy đúng 5 lần","Cho nhân vật đi đến khi chạm cạnh","Phát nhạc nền suốt trò chơi"],answers:[0,1]},{id:"th5-lap-18",type:"tf",q:"Khi dùng khối “lặp lại cho đến khi chạm vào cạnh”, em không cần biết trước số lần lặp.",explain:"Đúng. Khối này tự dừng khi nhân vật chạm cạnh, dù lặp bao nhiêu lần.",answer:!0}]},{questions:[{id:"th5-lap-19",type:"number",q:"Hà muốn vẽ hình có 5 cạnh bằng nhau và 5 góc bằng nhau: “lặp lại 5 lần”: “di chuyển 50 bước”, “xoay … độ”. Mỗi lần cần xoay bao nhiêu độ?",explain:"Năm lần xoay phải đủ một vòng: 360 : 5 = 72 độ.",answer:72,unit:"độ"},{id:"th5-lap-20",type:"number",q:"Chương trình: “lặp lại 2 lần”, bên trong có khối “lặp lại 3 lần”: “di chuyển 10 bước”. Nhân vật đi tất cả bao nhiêu bước?",explain:"Khối trong chạy 3 lần cho mỗi lần của khối ngoài: 2 × 3 × 10 = 60 bước.",answer:60,unit:"bước"},{id:"th5-lap-21",type:"mc",q:"Nam muốn mèo đi thẳng tới khi chạm cạnh sân khấu nhưng không biết cần bao nhiêu bước. Nam nên dùng cách lặp nào?",emoji:"🐱",explain:"Không biết trước số lần, dừng khi chạm cạnh thì dùng “lặp lại cho đến khi chạm vào cạnh”.",options:["Lặp với số lần đoán trước","Lặp cho đến khi chạm cạnh","Lặp liên tục không dừng","Không dùng lệnh lặp"],answer:1},{id:"th5-lap-22",type:"tf",q:"Lan viết: “lặp lại 4 lần”: “di chuyển 60 bước”, “xoay 120 độ”. Nhân vật vẽ đúng một hình tam giác đều, không đi thừa.",explain:"Sai. Ba lần đã đủ tam giác; lần thứ tư nhân vật đi lại lên cạnh đầu tiên.",answer:!1},{id:"th5-lap-23",type:"number",q:"Chương trình: “lặp lại 4 lần”: “di chuyển 25 bước”, “xoay 90 độ”; sau đó “lặp lại 3 lần”: “di chuyển 30 bước”, “xoay 120 độ”. Nhân vật đi tất cả bao nhiêu bước?",explain:"Hình vuông: 4 × 25 = 100 bước; tam giác: 3 × 30 = 90 bước; cộng lại 190 bước.",answer:190,unit:"bước"},{id:"th5-lap-24",type:"mc",q:"Chương trình: “lặp lại 8 lần”: “xoay 45 độ”. Nhân vật quay tất cả bao nhiêu độ?",explain:"Tám lần, mỗi lần 45 độ: 8 × 45 = 360 độ.",options:["180 độ","270 độ","360 độ","405 độ"],answer:2},{id:"th5-lap-25",type:"tf",q:"Thảo đặt “di chuyển 10 bước” và “nếu chạm vào cạnh thì bật lại” trong khối “liên tục”. Nhân vật đi qua đi lại mãi cho đến khi bấm nút đỏ.",explain:"Đúng. Khối “liên tục” lặp mãi, chạm cạnh thì nhân vật bật lại và đi tiếp.",answer:!0},{id:"th5-lap-26",type:"multi",q:"Những chương trình nào làm nhân vật quay đúng một vòng 360 độ?",explain:"4 × 90, 3 × 120 và 6 × 60 đều bằng 360 độ; còn 5 × 60 = 300 độ.",options:["lặp lại 4 lần: xoay 90 độ","lặp lại 3 lần: xoay 120 độ","lặp lại 6 lần: xoay 60 độ","lặp lại 5 lần: xoay 60 độ"],answers:[0,1,2]},{id:"th5-lap-27",type:"number",q:"Chương trình: “đặt đếm thành 0”; “lặp lại cho đến khi đếm bằng 4”: “di chuyển 10 bước”, “thay đổi đếm một lượng 1”. Nhân vật đi tất cả bao nhiêu bước?",explain:"Biến đếm tăng 0, 1, 2, 3, 4 nên khối lặp chạy 4 lần: 4 × 10 = 40 bước.",answer:40,unit:"bước"}]}],challenge:{questions:[{id:"th5-lap-20",type:"number",q:"Chương trình: “lặp lại 2 lần”, bên trong có khối “lặp lại 3 lần”: “di chuyển 10 bước”. Nhân vật đi tất cả bao nhiêu bước?",explain:"Khối trong chạy 3 lần cho mỗi lần của khối ngoài: 2 × 3 × 10 = 60 bước.",answer:60,unit:"bước"},{id:"th5-lap-22",type:"tf",q:"Lan viết: “lặp lại 4 lần”: “di chuyển 60 bước”, “xoay 120 độ”. Nhân vật vẽ đúng một hình tam giác đều, không đi thừa.",explain:"Sai. Ba lần đã đủ tam giác; lần thứ tư nhân vật đi lại lên cạnh đầu tiên.",answer:!1},{id:"th5-lap-23",type:"number",q:"Chương trình: “lặp lại 4 lần”: “di chuyển 25 bước”, “xoay 90 độ”; sau đó “lặp lại 3 lần”: “di chuyển 30 bước”, “xoay 120 độ”. Nhân vật đi tất cả bao nhiêu bước?",explain:"Hình vuông: 4 × 25 = 100 bước; tam giác: 3 × 30 = 90 bước; cộng lại 190 bước.",answer:190,unit:"bước"},{id:"th5-lap-26",type:"multi",q:"Những chương trình nào làm nhân vật quay đúng một vòng 360 độ?",explain:"4 × 90, 3 × 120 và 6 × 60 đều bằng 360 độ; còn 5 × 60 = 300 độ.",options:["lặp lại 4 lần: xoay 90 độ","lặp lại 3 lần: xoay 120 độ","lặp lại 6 lần: xoay 60 độ","lặp lại 5 lần: xoay 60 độ"],answers:[0,1,2]},{id:"th5-lap-28",type:"number",q:"Chương trình: “lặp lại 3 lần”, bên trong có khối “lặp lại 4 lần”: “di chuyển 10 bước”, “xoay 90 độ”. Nhân vật đi tất cả bao nhiêu bước?",explain:"Mỗi lần khối ngoài chạy là một hình vuông 4 × 10 = 40 bước; 3 lần là 3 × 40 = 120 bước.",answer:120,unit:"bước"},{id:"th5-lap-29",type:"mc",q:"Khoa muốn vẽ đúng một hình vuông nhưng viết: “lặp lại 6 lần”: “di chuyển 30 bước”, “xoay 90 độ”. Cần sửa gì?",explain:"Hình vuông có 4 cạnh nên chỉ cần lặp 4 lần; lặp 6 lần thì nhân vật đi đè lên 2 cạnh.",options:["Đổi số bước thành 90","Đổi góc xoay thành 60 độ","Bỏ khối xoay đi","Đổi số lần lặp thành 4"],answer:3},{id:"th5-lap-30",type:"number",q:"Chương trình: “đặt điểm thành 0”; “lặp lại cho đến khi điểm bằng 10”: “thay đổi điểm một lượng 2”. Khối lặp chạy bao nhiêu lần?",explain:"Điểm tăng 2, 4, 6, 8, 10; tới 10 thì dừng, vậy khối lặp chạy 5 lần.",answer:5,unit:"lần"}]},summary:["Có ba cách lặp: lặp số lần biết trước, lặp liên tục và lặp cho đến khi điều kiện đúng.","Muốn vẽ hình có các cạnh bằng nhau, em lặp đi một cạnh rồi xoay, góc xoay bằng 360 độ chia cho số cạnh."]},{id:"th5-re-nhanh",title:"Bài 15: Cấu trúc rẽ nhánh",weeks:[30,32],learn:[{title:"Rẽ nhánh là gì?",text:"Có lúc chương trình phải chọn việc để làm tùy theo một điều kiện. Cấu trúc rẽ nhánh giúp chương trình kiểm tra điều kiện rồi chọn việc phù hợp.",example:"❓ → ✅ / ❌"},{title:"Khối “nếu … thì”",text:"Khối “nếu … thì” kiểm tra một điều kiện. Điều kiện đúng thì chạy các lệnh bên trong, điều kiện sai thì bỏ qua.",example:"nếu 🧱 chạm vào cạnh thì ↩️"},{title:"Khối “nếu … thì … nếu không thì”",text:"Khối này có hai nhánh. Điều kiện đúng thì chạy nhánh “thì”, điều kiện sai thì chạy nhánh “nếu không thì”. Mỗi lần chỉ một nhánh được chạy.",example:"✅ thì · ❌ nếu không thì"},{title:"Điều kiện thường gặp",text:"Điều kiện chỉ có thể đúng hoặc sai, như “chạm vào cạnh”, “nhấn phím trái”, “điểm lớn hơn 5”. Khối rẽ nhánh thường đặt trong khối “liên tục” để kiểm tra mãi.",example:"🧱 · ⬅️ · 🏆 > 5"}],practice:[{questions:[{id:"th5-re-nhanh-01",type:"mc",q:"Cấu trúc nào giúp chương trình chọn việc để làm tùy theo điều kiện?",emoji:"🔀",explain:"Cấu trúc rẽ nhánh kiểm tra điều kiện rồi chọn việc phù hợp.",options:["Cấu trúc tuần tự","Cấu trúc lặp","Cấu trúc rẽ nhánh","Khối đặt biến"],answer:2},{id:"th5-re-nhanh-02",type:"tf",q:"Trong khối “nếu … thì”, khi điều kiện sai, các lệnh bên trong vẫn được chạy.",explain:"Sai. Điều kiện sai thì các lệnh bên trong khối “nếu … thì” bị bỏ qua.",answer:!1},{id:"th5-re-nhanh-03",type:"tf",q:"Khối “nếu … thì … nếu không thì” có hai nhánh lệnh.",explain:"Đúng. Một nhánh chạy khi điều kiện đúng, nhánh kia chạy khi điều kiện sai.",answer:!0},{id:"th5-re-nhanh-04",type:"mc",q:"Điều kiện trong khối rẽ nhánh có thể nhận những kết quả nào?",explain:"Điều kiện chỉ có thể đúng hoặc sai.",options:["Chỉ đúng hoặc sai","Một số bất kì","Một màu bất kì","Một tên nhân vật"],answer:0},{id:"th5-re-nhanh-05",type:"mc",q:"Khối nào dùng được làm điều kiện trong khối “nếu … thì”?",explain:"“Chạm vào cạnh” là điều kiện vì nó chỉ có thể đúng hoặc sai; các khối còn lại là lệnh làm việc.",options:["“di chuyển 10 bước”","“xoay 90 độ”","“đặt điểm thành 0”","“chạm vào cạnh”"],answer:3},{id:"th5-re-nhanh-06",type:"tf",q:"Với khối “nếu … thì … nếu không thì”, mỗi lần kiểm tra chỉ có một nhánh được chạy.",explain:"Đúng. Điều kiện đúng thì chạy nhánh “thì”, sai thì chạy nhánh “nếu không thì”.",answer:!0},{id:"th5-re-nhanh-07",type:"match",q:"Ghép mỗi điều kiện với ý nghĩa của nó.",explain:"Mỗi điều kiện kiểm tra một điều có thể đúng hoặc sai.",pairs:[["chạm vào cạnh","Nhân vật đụng mép sân khấu"],["nhấn phím trái","Người chơi bấm phím mũi tên trái"],["điểm lớn hơn 5","Giá trị của điểm vượt quá 5"]]},{id:"th5-re-nhanh-08",type:"fill",q:"Điền từ: Muốn khối “nếu … thì” kiểm tra điều kiện mãi, em đặt nó bên trong khối “…”.",explain:"Đặt trong khối “liên tục” thì điều kiện được kiểm tra lặp lại mãi.",answer:["liên tục"]},{id:"th5-re-nhanh-09",type:"mc",q:"Trong khối “nếu … thì … nếu không thì”, khi điều kiện sai thì chạy nhánh nào?",explain:"Điều kiện sai thì chạy nhánh “nếu không thì”.",options:["Nhánh “thì”","Nhánh “nếu không thì”","Cả hai nhánh cùng lúc","Không chạy nhánh nào"],answer:1}]},{questions:[{id:"th5-re-nhanh-10",type:"mc",q:"Chương trình: “nếu điểm lớn hơn 5 thì nói Giỏi quá”. Điểm đang là 3. Nhân vật làm gì?",explain:"3 không lớn hơn 5, điều kiện sai nên lệnh nói bị bỏ qua.",options:["Nói “Giỏi quá”","Không nói gì","Nói số 3"],answer:1},{id:"th5-re-nhanh-11",type:"tf",q:"Điểm bằng 5. Điều kiện “điểm lớn hơn 5” là đúng.",explain:"Sai. 5 bằng 5 chứ không lớn hơn 5, nên điều kiện sai.",answer:!1},{id:"th5-re-nhanh-12",type:"mc",q:"Chương trình: “nếu nhấn phím trái thì nói Trái, nếu không thì nói Chờ”. Người chơi không nhấn phím nào. Nhân vật nói gì?",explain:"Không nhấn phím trái nên điều kiện sai, chạy nhánh “nếu không thì”.",options:["Nói “Chờ”","Nói “Trái”","Nói cả hai","Không nói gì"],answer:0},{id:"th5-re-nhanh-13",type:"number",q:"Chương trình: “đặt điểm thành 4”; “nếu điểm lớn hơn 3 thì thay đổi điểm một lượng 10”. Điểm bằng bao nhiêu?",explain:"4 lớn hơn 3 nên điều kiện đúng: 4 + 10 = 14.",answer:14},{id:"th5-re-nhanh-14",type:"number",q:"Chương trình: “đặt điểm thành 2”; “nếu điểm lớn hơn 3 thì thay đổi điểm một lượng 10, nếu không thì thay đổi điểm một lượng 1”. Điểm bằng bao nhiêu?",explain:"2 không lớn hơn 3 nên chạy nhánh “nếu không thì”: 2 + 1 = 3.",answer:3},{id:"th5-re-nhanh-15",type:"tf",q:"Khối “nếu … thì” không nằm trong lệnh lặp chỉ kiểm tra điều kiện một lần, lúc chương trình chạy tới nó.",explain:"Đúng. Muốn kiểm tra nhiều lần, em đặt khối rẽ nhánh trong lệnh lặp.",answer:!0},{id:"th5-re-nhanh-16",type:"multi",q:"Những gì có thể làm điều kiện cho khối “nếu … thì”?",explain:"Ba ý đầu đều đúng hoặc sai được; “di chuyển 10 bước” là lệnh, không phải điều kiện.",options:["chạm vào cạnh","nhấn phím trái","điểm lớn hơn 5","di chuyển 10 bước"],answers:[0,1,2]},{id:"th5-re-nhanh-17",type:"mc",q:"Em muốn nhân vật nói “Đúng rồi” khi trả lời đúng và nói “Thử lại nhé” khi trả lời sai. Em dùng khối nào?",explain:"Có hai trường hợp đúng và sai nên dùng khối rẽ nhánh có hai nhánh “thì” và “nếu không thì”.",options:["Khối lặp lại 2 lần","Khối đặt biến thành số 0","Khối lặp liên tục","Khối rẽ nhánh có hai nhánh"],answer:3},{id:"th5-re-nhanh-18",type:"tf",q:"Nhân vật đang ở giữa sân khấu, không chạm cạnh. Khối “nếu chạm vào cạnh thì nói Ối” làm nhân vật nói “Ối”.",explain:"Sai. Nhân vật không chạm cạnh nên điều kiện sai, lệnh nói bị bỏ qua.",answer:!1}]},{questions:[{id:"th5-re-nhanh-19",type:"number",q:"Trò chơi bắt đầu với điểm bằng 0. Mỗi khi nhân vật chạm quả táo, “nếu chạm vào quả táo thì thay đổi điểm một lượng 2”. Bình bắt được 3 quả táo. Điểm bằng bao nhiêu?",emoji:"🍎",explain:"Ba lần chạm táo, mỗi lần cộng 2: 3 × 2 = 6.",answer:6},{id:"th5-re-nhanh-20",type:"mc",q:"Chương trình: “nếu điểm lớn hơn 10 thì nói Thắng rồi, nếu không thì nói Cố lên”. Điểm bằng 10. Nhân vật nói gì?",explain:"10 không lớn hơn 10 nên điều kiện sai, nhân vật nói “Cố lên”.",options:["Nói “Thắng rồi”","Nói cả hai câu","Nói “Cố lên”","Không nói gì"],answer:2},{id:"th5-re-nhanh-21",type:"tf",q:"Hà muốn nhân vật nói “Thắng rồi” khi điểm từ 5 trở lên, nên dùng điều kiện “điểm lớn hơn 5”. Khi điểm bằng 5, nhân vật vẫn nói “Thắng rồi”.",explain:"Sai. 5 không lớn hơn 5 nên điều kiện sai; Hà nên dùng điều kiện “điểm lớn hơn 4”.",answer:!1},{id:"th5-re-nhanh-22",type:"order",q:"Sắp xếp các việc máy tính làm khi chạy khối “nếu điểm lớn hơn 5 thì …, nếu không thì …”.",explain:"Máy tính lấy giá trị điểm, kiểm tra điều kiện, chạy đúng một nhánh rồi chạy tiếp lệnh sau.",items:["Lấy giá trị của biến điểm","Kiểm tra điểm có lớn hơn 5 không","Chạy nhánh phù hợp với kết quả","Chạy tiếp lệnh nằm sau khối rẽ nhánh"]},{id:"th5-re-nhanh-23",type:"tf",q:"Ngọc muốn cộng 1 điểm mỗi khi nhân vật chạm ngôi sao, nên đặt “thay đổi điểm một lượng 1” bên trong khối “nếu chạm vào ngôi sao thì”.",emoji:"⭐",explain:"Đúng. Lệnh cộng điểm chỉ chạy khi điều kiện chạm ngôi sao đúng.",answer:!0},{id:"th5-re-nhanh-24",type:"multi",q:"Khoa làm trò chơi: chạm ngôi sao thì cộng 1 điểm, chạm cạnh thì nói “Ối”. Khoa cần những khối nào?",explain:"Cần hai khối rẽ nhánh và khối cộng điểm; đổi phông nền không liên quan đến yêu cầu.",options:["nếu chạm vào ngôi sao thì","thay đổi điểm một lượng 1","nếu chạm vào cạnh thì","đổi phông nền thành vũ trụ"],answers:[0,1,2]},{id:"th5-re-nhanh-25",type:"tf",q:"Khối “nếu nhấn phím trái thì nói Trái” không nằm trong lệnh lặp. Người chơi nhấn phím trái sau khi khối đã chạy xong, nhân vật vẫn nói “Trái”.",explain:"Sai. Khối chỉ kiểm tra một lần lúc chạy tới; muốn kiểm tra mãi phải đặt trong khối “liên tục”.",answer:!1},{id:"th5-re-nhanh-26",type:"number",q:"Chương trình: “đặt điểm thành 8”; “nếu điểm lớn hơn 5 thì thay đổi điểm một lượng 2”; tiếp theo “nếu điểm lớn hơn 9 thì thay đổi điểm một lượng 10”. Điểm cuối cùng bằng bao nhiêu?",explain:"8 lớn hơn 5 nên điểm thành 10; 10 lớn hơn 9 nên cộng thêm 10, được 20.",answer:20},{id:"th5-re-nhanh-27",type:"mc",q:"Chương trình: “liên tục”: “nếu nhấn phím trái thì nói Trái, nếu không thì nói Đứng yên”. Tùng giữ phím trái rồi thả ra. Sau khi thả, nhân vật nói gì?",explain:"Khối “liên tục” kiểm tra mãi; thả phím thì điều kiện sai nên nhân vật nói “Đứng yên”.",options:["Nói “Đứng yên”","Nói “Trái”","Không nói gì nữa"],answer:0}]}],challenge:{questions:[{id:"th5-re-nhanh-14",type:"number",q:"Chương trình: “đặt điểm thành 2”; “nếu điểm lớn hơn 3 thì thay đổi điểm một lượng 10, nếu không thì thay đổi điểm một lượng 1”. Điểm bằng bao nhiêu?",explain:"2 không lớn hơn 3 nên chạy nhánh “nếu không thì”: 2 + 1 = 3.",answer:3},{id:"th5-re-nhanh-21",type:"tf",q:"Hà muốn nhân vật nói “Thắng rồi” khi điểm từ 5 trở lên, nên dùng điều kiện “điểm lớn hơn 5”. Khi điểm bằng 5, nhân vật vẫn nói “Thắng rồi”.",explain:"Sai. 5 không lớn hơn 5 nên điều kiện sai; Hà nên dùng điều kiện “điểm lớn hơn 4”.",answer:!1},{id:"th5-re-nhanh-25",type:"tf",q:"Khối “nếu nhấn phím trái thì nói Trái” không nằm trong lệnh lặp. Người chơi nhấn phím trái sau khi khối đã chạy xong, nhân vật vẫn nói “Trái”.",explain:"Sai. Khối chỉ kiểm tra một lần lúc chạy tới; muốn kiểm tra mãi phải đặt trong khối “liên tục”.",answer:!1},{id:"th5-re-nhanh-26",type:"number",q:"Chương trình: “đặt điểm thành 8”; “nếu điểm lớn hơn 5 thì thay đổi điểm một lượng 2”; tiếp theo “nếu điểm lớn hơn 9 thì thay đổi điểm một lượng 10”. Điểm cuối cùng bằng bao nhiêu?",explain:"8 lớn hơn 5 nên điểm thành 10; 10 lớn hơn 9 nên cộng thêm 10, được 20.",answer:20},{id:"th5-re-nhanh-28",type:"number",q:"Chương trình: “đặt điểm thành 0”; “lặp lại 4 lần”: “nếu điểm lớn hơn 1 thì thay đổi điểm một lượng 5, nếu không thì thay đổi điểm một lượng 1”. Điểm cuối cùng bằng bao nhiêu?",explain:"Lần 1: 0 thành 1; lần 2: 1 thành 2; lần 3: 2 lớn hơn 1 nên thành 7; lần 4: thành 12.",answer:12},{id:"th5-re-nhanh-29",type:"number",q:"Chương trình: “đặt điểm thành 0”; “lặp lại 5 lần”: “thay đổi điểm một lượng 3”, rồi “nếu điểm lớn hơn 10 thì đặt điểm thành 0”. Điểm cuối cùng bằng bao nhiêu?",explain:"Điểm lần lượt là 3, 6, 9, 12; vì 12 lớn hơn 10 nên về 0; lần thứ năm cộng 3 được 3.",answer:3},{id:"th5-re-nhanh-30",type:"mc",q:"Chương trình: “nếu điểm lớn hơn 5 thì nói Giỏi, nếu không thì nói Cố lên”. Điểm bằng bao nhiêu thì nhân vật nói “Giỏi”?",explain:"Chỉ có 6 lớn hơn 5; điểm bằng 5 thì điều kiện vẫn sai.",options:["Điểm bằng 3","Điểm bằng 5","Điểm bằng 0","Điểm bằng 6"],answer:3}]},summary:["Cấu trúc rẽ nhánh kiểm tra một điều kiện đúng hay sai rồi chọn việc để làm.","Khối “nếu … thì” chỉ chạy lệnh khi điều kiện đúng; khối “nếu … thì … nếu không thì” luôn chạy đúng một trong hai nhánh.","Muốn kiểm tra điều kiện nhiều lần, em đặt khối rẽ nhánh trong lệnh lặp."]},{id:"th5-chuong-trinh-con-go-loi",title:"Bài 16: Chương trình con và gỡ lỗi",weeks:[33,35],learn:[{title:"Chương trình con",text:"Chương trình con là một nhóm lệnh được đặt tên riêng để dùng lại nhiều lần. Trong phần mềm lập trình khối lệnh, em tạo chương trình con bằng cách tự tạo một khối lệnh mới.",example:"🧩 khối tự tạo"},{title:"Đặt tên và gọi chương trình con",text:"Em đặt tên rõ ràng cho khối mới, như “vẽ hình vuông”, rồi ghép các lệnh vào phần định nghĩa của nó. Mỗi lần gọi khối “vẽ hình vuông”, các lệnh đó chạy một lần.",example:"✏️ vẽ hình vuông × 3"},{title:"Gỡ lỗi là gì?",text:"Lỗi là chỗ sai làm chương trình chạy không như mong muốn. Gỡ lỗi là tìm ra chỗ sai và sửa lại cho đúng.",example:"🐞 → 🔧"},{title:"Các bước gỡ lỗi",text:"Chạy chương trình và quan sát, tìm khối lệnh sai, sửa lại rồi chạy thử lần nữa. Lỗi hay gặp là sai con số, sai thứ tự, thiếu khối hoặc sai số lần lặp.",example:"▶️ 👀 🔍 🔧 🔁"}],practice:[{questions:[{id:"th5-chuong-trinh-con-go-loi-01",type:"mc",q:"Chương trình con là gì?",emoji:"🧩",explain:"Chương trình con là một nhóm lệnh được đặt tên riêng để dùng lại nhiều lần.",options:["Một nhân vật nhỏ trên sân khấu","Nhóm lệnh có tên, dùng lại được","Một phông nền được vẽ thêm","Một biến dùng để lưu điểm"],answer:1},{id:"th5-chuong-trinh-con-go-loi-02",type:"tf",q:"Một chương trình con có thể được gọi nhiều lần trong chương trình.",explain:"Đúng. Mỗi lần gọi, các lệnh trong chương trình con lại chạy.",answer:!0},{id:"th5-chuong-trinh-con-go-loi-03",type:"tf",q:"Gỡ lỗi là xóa hết chương trình rồi viết lại từ đầu.",explain:"Sai. Gỡ lỗi là tìm đúng chỗ sai và sửa chỗ đó.",answer:!1},{id:"th5-chuong-trinh-con-go-loi-04",type:"mc",q:"Tên nào rõ ràng nhất cho chương trình con vẽ một hình vuông?",explain:"Tên “vẽ hình vuông” cho biết ngay khối đó làm gì.",options:["khối số 1","abc xyz","chương trình 1","vẽ hình vuông"],answer:3},{id:"th5-chuong-trinh-con-go-loi-05",type:"order",q:"Sắp xếp các bước gỡ lỗi chương trình.",emoji:"🐞",explain:"Chạy và quan sát, tìm chỗ sai, sửa, rồi chạy thử lại để chắc chắn đã đúng.",items:["Chạy chương trình và quan sát","Tìm khối lệnh bị sai","Sửa khối lệnh đó","Chạy thử lại để kiểm tra"]},{id:"th5-chuong-trinh-con-go-loi-06",type:"fill",q:"Điền từ: Tìm ra chỗ sai trong chương trình rồi sửa lại cho đúng gọi là gỡ ….",emoji:"🐞",explain:"Việc tìm và sửa chỗ sai trong chương trình gọi là gỡ lỗi.",answer:["lỗi"]},{id:"th5-chuong-trinh-con-go-loi-07",type:"mc",q:"Lỗi trong chương trình là gì?",explain:"Lỗi là chỗ sai làm chương trình chạy không như em mong muốn.",options:["Nút đỏ dùng để dừng chương trình","Khối lệnh đặt ở trên cùng","Chỗ sai làm chương trình chạy sai","Biến đang ẩn khỏi sân khấu"],answer:2},{id:"th5-chuong-trinh-con-go-loi-08",type:"match",q:"Ghép mỗi loại lỗi với ví dụ của nó.",explain:"Sai con số, sai thứ tự và thiếu khối là những lỗi hay gặp.",pairs:[["Sai con số","Viết “xoay 80 độ” thay cho “xoay 90 độ”"],["Sai thứ tự","Nói “Tạm biệt” trước rồi mới nói “Xin chào”"],["Thiếu khối","Quên khối “đặt điểm thành 0” khi bắt đầu"]]},{id:"th5-chuong-trinh-con-go-loi-09",type:"tf",q:"Sau khi sửa lỗi, em nên chạy thử lại chương trình để kiểm tra.",explain:"Đúng. Chạy thử lại giúp chắc chắn lỗi đã được sửa đúng.",answer:!0}]},{questions:[{id:"th5-chuong-trinh-con-go-loi-10",type:"number",q:"Chương trình con “bước tới” gồm “di chuyển 10 bước” và “đợi 1 giây”. Chương trình chính gọi “bước tới” 3 lần. Nhân vật đi tất cả bao nhiêu bước?",explain:"Mỗi lần gọi đi 10 bước, gọi 3 lần: 3 × 10 = 30 bước.",answer:30,unit:"bước"},{id:"th5-chuong-trinh-con-go-loi-11",type:"tf",q:"Khi sửa lệnh bên trong chương trình con, mọi chỗ gọi chương trình con đó đều chạy theo cách mới.",explain:"Đúng. Các lệnh chỉ viết ở một chỗ nên sửa một lần là mọi lần gọi đều thay đổi.",answer:!0},{id:"th5-chuong-trinh-con-go-loi-12",type:"mc",q:"Vì sao nên đặt tên chương trình con rõ ràng, như “vẽ hình vuông”?",explain:"Tên rõ ràng giúp đọc tên là hiểu khối đó làm gì.",options:["Để nhân vật chạy nhanh hơn","Để chương trình có nhiều màu","Để không cần lá cờ xanh","Để đọc tên là biết khối làm gì"],answer:3},{id:"th5-chuong-trinh-con-go-loi-13",type:"mc",q:"Vy viết: “lặp lại 3 lần”: “di chuyển 50 bước”, “xoay 90 độ”. Vy muốn vẽ hình vuông nhưng hình chỉ có 3 cạnh. Lỗi nằm ở đâu?",explain:"Hình vuông có 4 cạnh nên phải lặp 4 lần; Vy ghi sai số lần lặp.",options:["Số lần lặp","Số bước đi","Góc xoay","Khối lá cờ xanh"],answer:0},{id:"th5-chuong-trinh-con-go-loi-14",type:"tf",q:"An viết: “lặp lại 4 lần”: “di chuyển 50 bước”, “xoay 60 độ”. Chương trình này vẽ đúng một hình vuông.",explain:"Sai. Hình vuông cần xoay 90 độ mỗi lần; 4 × 60 = 240 độ nên hình không khép kín.",answer:!1},{id:"th5-chuong-trinh-con-go-loi-15",type:"multi",q:"Những lỗi nào là lỗi hay gặp khi lập trình?",explain:"Sai con số, sai thứ tự, thiếu khối là lỗi; đặt tên rõ ràng là việc tốt, không phải lỗi.",options:["Sai con số trong khối lệnh","Sai thứ tự các khối","Thiếu một khối cần thiết","Đặt tên chương trình con rõ ràng"],answers:[0,1,2]},{id:"th5-chuong-trinh-con-go-loi-16",type:"number",q:"Chương trình con “vẽ hình vuông”: “lặp lại 4 lần”: “di chuyển 30 bước”, “xoay 90 độ”. Chương trình chính gọi “vẽ hình vuông” 2 lần. Nhân vật đi tất cả bao nhiêu bước?",emoji:"⬜",explain:"Mỗi hình vuông 4 × 30 = 120 bước; hai lần là 2 × 120 = 240 bước.",answer:240,unit:"bước"},{id:"th5-chuong-trinh-con-go-loi-17",type:"mc",q:"Bình gọi chương trình con “nhảy múa” 3 lần. Các lệnh trong “nhảy múa” chạy mấy lần?",explain:"Mỗi lần gọi, các lệnh trong chương trình con chạy một lần; gọi 3 lần thì chạy 3 lần.",options:["1 lần","2 lần","3 lần","6 lần"],answer:2},{id:"th5-chuong-trinh-con-go-loi-18",type:"tf",q:"Sau khi tạo khối mới, em phải ghép lệnh vào phần định nghĩa thì khối đó mới làm được việc.",explain:"Đúng. Phần định nghĩa chứa các lệnh mà khối mới sẽ chạy khi được gọi.",answer:!0}]},{questions:[{id:"th5-chuong-trinh-con-go-loi-19",type:"mc",q:"Chi muốn mỗi lần chơi, điểm bắt đầu từ 0, nhưng điểm cứ cộng tiếp từ lần chơi trước. Chi đã quên khối nào?",explain:"Thiếu khối “đặt điểm thành 0” ở đầu chương trình nên điểm không được đặt lại.",options:["“hiện biến điểm”","“đặt điểm thành 0”","“ẩn biến điểm”","“liên tục”"],answer:1},{id:"th5-chuong-trinh-con-go-loi-20",type:"number",q:"Minh muốn nhân vật đi đúng 100 bước nhưng viết: “lặp lại 4 lần”: “di chuyển 20 bước”. Nhân vật còn thiếu bao nhiêu bước?",explain:"Nhân vật đi 4 lần 20 bằng 80 bước; còn thiếu 100 trừ 80 bằng 20 bước.",answer:20,unit:"bước"},{id:"th5-chuong-trinh-con-go-loi-21",type:"mc",q:"Nam muốn nhân vật đi đúng 100 bước nhưng viết: “lặp lại 4 lần”: “di chuyển 20 bước”. Cách sửa nào đúng?",explain:"Lặp 5 lần, mỗi lần 20 bước: 5 × 20 = 100 bước.",options:["Đổi 4 lần thành 5 lần","Đổi 20 bước thành 30 bước","Đổi 4 lần thành 6 lần","Thêm khối xoay 90 độ"],answer:0},{id:"th5-chuong-trinh-con-go-loi-22",type:"order",q:"Sắp xếp các bước dùng chương trình con để vẽ ba hình vuông.",explain:"Tạo khối mới, ghép lệnh vào phần định nghĩa, gọi khối trong chương trình chính, rồi chạy thử.",items:["Tạo khối mới tên là “vẽ hình vuông”","Ghép các lệnh vẽ hình vuông vào phần định nghĩa","Gọi “vẽ hình vuông” 3 lần trong chương trình chính","Bấm lá cờ xanh và xem kết quả"]},{id:"th5-chuong-trinh-con-go-loi-23",type:"tf",q:"Lan muốn nhân vật chào rồi mới tạm biệt, nhưng ghép “nói Tạm biệt” ở trên “nói Xin chào”. Đây là lỗi sai thứ tự.",explain:"Đúng. Hai khối đều có nhưng đặt ngược thứ tự.",answer:!0},{id:"th5-chuong-trinh-con-go-loi-24",type:"number",q:"Chương trình con “vẽ tam giác”: “lặp lại 3 lần”: “di chuyển 40 bước”, “xoay 120 độ”. Chương trình chính gọi “vẽ tam giác” 4 lần. Nhân vật đi tất cả bao nhiêu bước?",emoji:"🔺",explain:"Mỗi tam giác 3 × 40 = 120 bước; bốn lần là 4 × 120 = 480 bước.",answer:480,unit:"bước"},{id:"th5-chuong-trinh-con-go-loi-25",type:"multi",q:"Tùng chạy chương trình thấy nhân vật vẽ sai hình. Tùng nên làm gì?",explain:"Quan sát, kiểm tra các con số, sửa rồi chạy thử là cách gỡ lỗi; bỏ cuộc thì không sửa được lỗi.",options:["Quan sát xem nhân vật sai ở bước nào","Kiểm tra số bước, góc xoay và số lần lặp","Sửa khối sai rồi chạy thử lại","Xóa hết chương trình rồi bỏ cuộc"],answers:[0,1,2]},{id:"th5-chuong-trinh-con-go-loi-26",type:"mc",q:"Thảo cần vẽ 5 hình vuông giống nhau. Cách nào gọn nhất?",explain:"Tạo chương trình con một lần rồi gọi 5 lần thì gọn và dễ sửa nhất.",options:["Ghép 5 lần đủ các lệnh vẽ hình vuông","Gọi 5 lần khối tự tạo “vẽ hình vuông”","Chỉ vẽ một hình vuông thật to"],answer:1},{id:"th5-chuong-trinh-con-go-loi-27",type:"tf",q:"Phúc tạo chương trình con nhưng quên gọi nó trong chương trình chính. Khi bấm lá cờ xanh, các lệnh trong chương trình con vẫn chạy.",explain:"Sai. Chương trình con chỉ chạy khi được gọi.",answer:!1}]}],challenge:{questions:[{id:"th5-chuong-trinh-con-go-loi-16",type:"number",q:"Chương trình con “vẽ hình vuông”: “lặp lại 4 lần”: “di chuyển 30 bước”, “xoay 90 độ”. Chương trình chính gọi “vẽ hình vuông” 2 lần. Nhân vật đi tất cả bao nhiêu bước?",emoji:"⬜",explain:"Mỗi hình vuông 4 × 30 = 120 bước; hai lần là 2 × 120 = 240 bước.",answer:240,unit:"bước"},{id:"th5-chuong-trinh-con-go-loi-21",type:"mc",q:"Nam muốn nhân vật đi đúng 100 bước nhưng viết: “lặp lại 4 lần”: “di chuyển 20 bước”. Cách sửa nào đúng?",explain:"Lặp 5 lần, mỗi lần 20 bước: 5 × 20 = 100 bước.",options:["Đổi 4 lần thành 5 lần","Đổi 20 bước thành 30 bước","Đổi 4 lần thành 6 lần","Thêm khối xoay 90 độ"],answer:0},{id:"th5-chuong-trinh-con-go-loi-24",type:"number",q:"Chương trình con “vẽ tam giác”: “lặp lại 3 lần”: “di chuyển 40 bước”, “xoay 120 độ”. Chương trình chính gọi “vẽ tam giác” 4 lần. Nhân vật đi tất cả bao nhiêu bước?",emoji:"🔺",explain:"Mỗi tam giác 3 × 40 = 120 bước; bốn lần là 4 × 120 = 480 bước.",answer:480,unit:"bước"},{id:"th5-chuong-trinh-con-go-loi-27",type:"tf",q:"Phúc tạo chương trình con nhưng quên gọi nó trong chương trình chính. Khi bấm lá cờ xanh, các lệnh trong chương trình con vẫn chạy.",explain:"Sai. Chương trình con chỉ chạy khi được gọi.",answer:!1},{id:"th5-chuong-trinh-con-go-loi-28",type:"number",q:"Chương trình con “bước tới”: “di chuyển 15 bước”, “thay đổi điểm một lượng 1”. Chương trình chính: “đặt điểm thành 0”; “lặp lại 3 lần”: gọi “bước tới” 2 lần. Điểm bằng bao nhiêu?",explain:"Khối lặp chạy 3 lần, mỗi lần gọi 2 lần: 3 × 2 = 6 lần cộng 1, nên điểm bằng 6.",answer:6},{id:"th5-chuong-trinh-con-go-loi-29",type:"mc",q:"Ngọc muốn vẽ tam giác đều nhưng viết: “lặp lại 3 lần”: “di chuyển 60 bước”, “xoay 90 độ”. Hình không khép kín. Ngọc cần sửa thế nào?",emoji:"🔺",explain:"Tam giác đều cần xoay 120 độ mỗi lần: 3 × 120 = 360 độ.",options:["Đổi 3 lần thành 4 lần","Đổi 60 bước thành 90 bước","Đổi 90 độ thành 120 độ","Đổi 90 độ thành 60 độ"],answer:2},{id:"th5-chuong-trinh-con-go-loi-30",type:"number",q:"Dũng muốn nhân vật đi 120 bước và viết: “lặp lại 5 lần”: “di chuyển 20 bước”. Dũng chỉ sửa số lần lặp. Cần lặp bao nhiêu lần?",explain:"Mỗi lần 20 bước, cần 120 bước: 120 : 20 = 6 lần.",answer:6,unit:"lần"}]},summary:["Chương trình con là nhóm lệnh có tên rõ ràng, viết một lần và gọi được nhiều lần.","Gỡ lỗi gồm chạy và quan sát, tìm chỗ sai, sửa, rồi chạy thử lại."]}]}],g={grade:5,subject:n,title:h,review:i,topics:t};export{g as default,c as grade,i as review,n as subject,h as title,t as topics};
